(333150,37017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ella ... el equilibrio sobre la mesa de reuniones un minuto entero.'::text,'mantuvo'::text,'fue mantenida'::text,'manteniendo'::text,'Amiga, al parecer ella mantuvo el equilibrio sobre la mesa de reuniones un minuto entero.'::text),
(333149,37017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle ... son équilibre sur la table de réunion pendant une minute entière.'::text,'a gardé'::text,'a été gardée'::text,'gardant'::text,'Ma belle, apparemment elle a gardé son équilibre sur la table de réunion pendant une minute entière.'::text),
(333152,37017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre toplantı masasında tam bir dakika dengesini ...'::text,'korumuş'::text,'korunmuş'::text,'koruyarak'::text,'Kanka, duyduğuma göre toplantı masasında tam bir dakika dengesini korumuş.'::text),
(333153,37017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egy teljes percig ... az egyensúlyát a tárgyalóasztalon.'::text,'megtartotta'::text,'meg lett tartva'::text,'megtartva'::text,'Csajszi, állítólag egy teljes percig megtartotta az egyensúlyát a tárgyalóasztalon.'::text),
(333156,37018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, sie ... ein krasses Gleichgewicht haben, um diesen Handstand zu schaffen.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Hör zu, er hat mir gesagt, sie muss ein krasses Gleichgewicht haben, um diesen Handstand zu schaffen.'::text),
(333160,37018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що вона ... мати шалену рівновагу, щоб зробити ту стійку на руках.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Слухай, він сказав мені, що вона мусить мати шалену рівновагу, щоб зробити ту стійку на руках.'::text),
(333159,37018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ella ... tener un equilibrio brutal para hacer ese pino.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Oye, me dijo que ella debe de tener un equilibrio brutal para hacer ese pino.'::text),
(333158,37018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''elle ... avoir un équilibre de fou pour faire ce poirier.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Écoute, il m''a dit qu''elle doit avoir un équilibre de fou pour faire ce poirier.'::text),
(333161,37018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki o amudu atmak için onun müthiş bir dengesi ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Dinle, bana dedi ki o amudu atmak için onun müthiş bir dengesi olmalı.'::text),
(333162,37018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy őrületes egyensúlya ..., hogy megcsinálja azt a kézenállást.'::text,'biztos van'::text,'nem lehet'::text,'nem szabad, hogy legyen'::text,'Figyelj, azt mondta, hogy őrületes egyensúlya biztos van, hogy megcsinálja azt a kézenállást.'::text),
(333165,37019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kollegin, ... Gleichgewicht das Büro verblüfft hat, hat einen Handstand auf dem Konferenztisch gemacht.'::text,'deren'::text,'die'::text,'welche'::text,'Die Kollegin, deren Gleichgewicht das Büro verblüfft hat, hat einen Handstand auf dem Konferenztisch gemacht.'::text),
(333169,37019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колега, ... рівновага вразила весь офіс, зробила стійку на руках на столі для нарад.'::text,'чия'::text,'яка'::text,'котра'::text,'Колега, чия рівновага вразила весь офіс, зробила стійку на руках на столі для нарад.'::text),
(333168,37019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La compañera ... equilibrio asombró a la oficina hizo el pino sobre la mesa de reuniones.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La compañera cuyo equilibrio asombró a la oficina hizo el pino sobre la mesa de reuniones.'::text),
(333167,37019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La collègue ... l''équilibre a épaté le bureau a fait le poirier sur la table de réunion.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La collègue dont l''équilibre a épaté le bureau a fait le poirier sur la table de réunion.'::text),
(333170,37019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dengesi ofisi ... iş arkadaşı toplantı masasında amut attı.'::text,'büyüleyen'::text,'büyüleyen'::text,'büyüleyen'::text,'Dengesi ofisi büyüleyen iş arkadaşı toplantı masasında amut attı.'::text),
(333171,37019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a kolléga, ... egyensúlya lenyűgözte az irodát, kézenállást csinált a tárgyalóasztalon.'::text,'akinek az'::text,'aki'::text,'amely'::text,'Az a kolléga, akinek az egyensúlya lenyűgözte az irodát, kézenállást csinált a tárgyalóasztalon.'::text),
(333174,37020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Kollege sagte, dass sie eine ganze Minute lang auf dem Tisch das Gleichgewicht ...'::text,'gehalten hatte'::text,'gehalten hat'::text,'hält'::text,'Ein Kollege sagte, dass sie eine ganze Minute lang auf dem Tisch das Gleichgewicht gehalten hatte.'::text),
(333178,37020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колега сказав, що вона ... рівновагу на столі цілу хвилину.'::text,'втримувала'::text,'втримала'::text,'тримає'::text,'Колега сказав, що вона втримувала рівновагу на столі цілу хвилину.'::text),
(333177,37020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un compañero dijo que ella ... el equilibrio sobre la mesa un minuto entero.'::text,'había mantenido'::text,'ha mantenido'::text,'mantiene'::text,'Un compañero dijo que ella había mantenido el equilibrio sobre la mesa un minuto entero.'::text),
(333176,37020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un collègue a dit qu''elle ... son équilibre sur la table pendant une minute entière.'::text,'avait gardé'::text,'a gardé'::text,'garde'::text,'Un collègue a dit qu''elle avait gardé son équilibre sur la table pendant une minute entière.'::text),
(333179,37020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir iş arkadaşı, onun masada tam bir dakika dengesini ... söyledi.'::text,'koruduğunu'::text,'koruduğunu'::text,'koruduğunu'::text,'Bir iş arkadaşı, onun masada tam bir dakika dengesini koruduğunu söyledi.'::text),
(333180,37020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kolléga azt mondta, hogy egy teljes percig ... az egyensúlyát az asztalon.'::text,'megtartotta'::text,'megtartotta'::text,'tartja'::text,'Egy kolléga azt mondta, hogy egy teljes percig megtartotta az egyensúlyát az asztalon.'::text),
(333192,37022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Abteilung hat sich darauf geeinigt, 15 Minuten am Tag in Gleichgewichtstraining ...'::text,'zu investieren'::text,'das Investieren'::text,'investieren'::text,'Die Abteilung hat sich darauf geeinigt, 15 Minuten am Tag in Gleichgewichtstraining zu investieren.'::text),
(333196,37022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відділ погодився ... 15 хвилин на день на тренування рівноваги.'::text,'витрачати'::text,'витрачання'::text,'витрачати'::text,'Відділ погодився витрачати 15 хвилин на день на тренування рівноваги.'::text),
(333195,37022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El departamento acordó ... 15 minutos al día al entrenamiento de equilibrio.'::text,'dedicar'::text,'dedicando'::text,'dedicar'::text,'El departamento acordó dedicar 15 minutos al día al entrenamiento de equilibrio.'::text),
(333194,37022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le service a accepté ... 15 minutes par jour à l''entraînement de l''équilibre.'::text,'de consacrer'::text,'consacrant'::text,'consacrer'::text,'Le service a accepté de consacrer 15 minutes par jour à l''entraînement de l''équilibre.'::text),
(333197,37022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Departman denge antrenmanına günde 15 dakika ... kabul etti.'::text,'ayırmayı'::text,'ayırmayı'::text,'ayırmayı'::text,'Departman denge antrenmanına günde 15 dakika ayırmayı kabul etti.'::text),
(333198,37022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az osztály beleegyezett, hogy napi 15 percet ... egyensúlyedzésre.'::text,'fordítson'::text,'fordítás'::text,'fordít'::text,'Az osztály beleegyezett, hogy napi 15 percet fordítson egyensúlyedzésre.'::text),
(333201,37023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Weil sie nicht fällt, hat sie ein gutes Gleichgewicht, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Weil sie nicht fällt, hat sie ein gutes Gleichgewicht, oder?'::text),
(333205,37023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оскільки вона не падає, у неї добра рівновага, ...?'::text,'так'::text,'так'::text,'так'::text,'Оскільки вона не падає, у неї добра рівновага, так?'::text),
(333204,37023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Como no se cae, tiene buen equilibrio, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Como no se cae, tiene buen equilibrio, ¿verdad?'::text),
(333203,37023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme elle ne tombe pas, elle a un bon équilibre, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Comme elle ne tombe pas, elle a un bon équilibre, n''est-ce pas ?'::text),
(333206,37023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Düşmediğine göre dengesi iyi, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Düşmediğine göre dengesi iyi, değil mi?'::text),
(333207,37023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mivel nem esik el, jó az egyensúlya, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Mivel nem esik el, jó az egyensúlya, ugye?'::text),
(333210,37024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Kollegen konnten ihr Gleichgewicht nicht fassen, und die zwei Frauen an den Computern ...'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Ihre Kollegen konnten ihr Gleichgewicht nicht fassen, und die zwei Frauen an den Computern auch nicht.'::text),
(333214,37024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колеги не могли повірити в її рівновагу, і дві жінки за комп''ютерами ...'::text,'теж не могли'::text,'теж могли'::text,'теж не повірили'::text,'Колеги не могли повірити в її рівновагу, і дві жінки за комп''ютерами теж не могли.'::text),
(333213,37024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus compañeros no podían creerse su equilibrio, y las dos mujeres de los ordenadores ...'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Sus compañeros no podían creerse su equilibrio, y las dos mujeres de los ordenadores tampoco.'::text),
(333212,37024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses collègues n''en revenaient pas de son équilibre, et les deux femmes devant les ordinateurs ...'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Ses collègues n''en revenaient pas de son équilibre, et les deux femmes devant les ordinateurs non plus.'::text),
(333215,37024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşları onun dengesine inanamadı, bilgisayar başındaki iki kadın da ...'::text,'inanamadı'::text,'inanabildi'::text,'inanmadı'::text,'İş arkadaşları onun dengesine inanamadı, bilgisayar başındaki iki kadın da inanamadı.'::text),
(333216,37024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégái nem tudták elhinni az egyensúlyát, és a két nő a gépeknél ...'::text,'sem tudta elhinni'::text,'is el tudta hinni'::text,'sem hitte el'::text,'A kollégái nem tudták elhinni az egyensúlyát, és a két nő a gépeknél sem tudta elhinni.'::text),
(333219,37025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... monatelang an ihrem Gleichgewicht gearbeitet, bevor sie das Meeting mit einem Handstand ruiniert hat!'::text,'hatte'::text,'hat'::text,'arbeitete'::text,'Sie hatte monatelang an ihrem Gleichgewicht gearbeitet, bevor sie das Meeting mit einem Handstand ruiniert hat!'::text),
(333223,37025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... над своєю рівновагою місяцями, перш ніж зірвала нараду стійкою на руках!'::text,'працювала'::text,'працює'::text,'працювала'::text,'Вона працювала над своєю рівновагою місяцями, перш ніж зірвала нараду стійкою на руках!'::text),
(333222,37025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... en su equilibrio durante meses antes de arruinar la reunión con un pino!'::text,'había estado trabajando'::text,'ha estado trabajando'::text,'estaba trabajando'::text,'¡Ella había estado trabajando en su equilibrio durante meses antes de arruinar la reunión con un pino!'::text),
(333221,37025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur son équilibre pendant des mois avant de ruiner la réunion avec un poirier !'::text,'avait travaillé'::text,'a travaillé'::text,'travaillait'::text,'Elle avait travaillé sur son équilibre pendant des mois avant de ruiner la réunion avec un poirier !'::text),
(333224,37025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantıyı amutla mahvetmeden önce aylardır dengesi üzerinde ...!'::text,'çalışıyordu'::text,'çalışıyor'::text,'çalışıyordu'::text,'Toplantıyı amutla mahvetmeden önce aylardır dengesi üzerinde çalışıyordu!'::text),
(333225,37025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hónapokig ... az egyensúlyán, mielőtt egy kézenállással tönkretette a megbeszélést!'::text,'dolgozott'::text,'dolgozik'::text,'dolgozott'::text,'Hónapokig dolgozott az egyensúlyán, mielőtt egy kézenállással tönkretette a megbeszélést!'::text),
(333237,37027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Mittag wird sie da oben drei Stunden lang an ihrem Gleichgewicht ...! Das Meeting ist ruiniert!'::text,'gearbeitet haben'::text,'arbeiten'::text,'arbeiten'::text,'Bis zum Mittag wird sie da oben drei Stunden lang an ihrem Gleichgewicht gearbeitet haben! Das Meeting ist ruiniert!'::text),
(333241,37027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду вона ... над своєю рівновагою там нагорі три години. Нарада зірвана!'::text,'пропрацює'::text,'працюватиме'::text,'працюватиме'::text,'До обіду вона пропрацює над своєю рівновагою там нагорі три години. Нарада зірвана!'::text),
(333240,37027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, ella ... en su equilibrio ahí arriba durante tres horas. ¡La reunión está arruinada!'::text,'habrá estado trabajando'::text,'estará trabajando'::text,'trabajará'::text,'Para la hora de comer, ella habrá estado trabajando en su equilibrio ahí arriba durante tres horas. ¡La reunión está arruinada!'::text),
(333239,37027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le déjeuner, elle ... sur son équilibre là-haut pendant trois heures. La réunion est fichue !'::text,'aura travaillé'::text,'sera en train de travailler'::text,'travaillera'::text,'D''ici le déjeuner, elle aura travaillé sur son équilibre là-haut pendant trois heures. La réunion est fichue !'::text),
(333242,37027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar orada üç saattir dengesi üzerinde ...! Toplantı mahvoldu!'::text,'çalışıyor olacak'::text,'çalışıyor olacak'::text,'çalışacak'::text,'Öğlene kadar orada üç saattir dengesi üzerinde çalışıyor olacak! Toplantı mahvoldu!'::text),
(333243,37027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédre már három órája ... ott fent az egyensúlyán. Tönkrement a megbeszélés!'::text,'fog dolgozni'::text,'fog dolgozni'::text,'dolgozik majd'::text,'Ebédre már három órája fog dolgozni ott fent az egyensúlyán. Tönkrement a megbeszélés!'::text),
(359778,39976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jet-Toaster ... gerade das Brot, als plötzlich blaue Flammen aus seinen Düsen schossen.'::text,'erhitzte'::text,'erhitzte'::text,'hat erhitzt'::text,'Der Jet-Toaster erhitzte gerade das Brot, als plötzlich blaue Flammen aus seinen Düsen schossen.'::text),
(359782,39976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тостер-винищувач ... хліб, коли з його сопел раптом вирвалося синє полум''я.'::text,'нагрівав'::text,'нагрів'::text,'нагрів'::text,'Тостер-винищувач нагрівав хліб, коли з його сопел раптом вирвалося синє полум''я.'::text),
(359781,39976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tostadora-caza ... el pan cuando de repente salieron llamas azules de sus toberas.'::text,'estaba calentando'::text,'calentó'::text,'ha calentado'::text,'La tostadora-caza estaba calentando el pan cuando de repente salieron llamas azules de sus toberas.'::text),
(359780,39976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grille-pain avion ... le pain quand des flammes bleues ont soudain jailli de ses tuyères.'::text,'chauffait'::text,'a chauffé'::text,'a chauffé'::text,'Le grille-pain avion chauffait le pain quand des flammes bleues ont soudain jailli de ses tuyères.'::text),
(359783,39976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jet tost makinesi ekmeği ... birden nozullarından mavi alevler fışkırdı.'::text,'ısıtırken'::text,'ısıttı'::text,'ısıttı'::text,'Jet tost makinesi ekmeği ısıtırken birden nozullarından mavi alevler fışkırdı.'::text),
(359784,39976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vadászgép-kenyérpirító éppen ... a kenyeret, amikor hirtelen kék lángok csaptak ki a fúvókáiból.'::text,'melegítette'::text,'megmelegítette'::text,'megmelegítette'::text,'A vadászgép-kenyérpirító éppen melegítette a kenyeret, amikor hirtelen kék lángok csaptak ki a fúvókáiból.'::text),
(359796,39978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Toaster ... das Brot eine Minute lang, und dann kam der goldene Toast hoch.'::text,'erhitzte'::text,'erhitzte gerade'::text,'hat erhitzt'::text,'Der Toaster erhitzte das Brot eine Minute lang, und dann kam der goldene Toast hoch.'::text),
(359800,39978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тостер ... хліб хвилину, а потім вискочили золотисті тости.'::text,'нагрівав'::text,'нагрівав'::text,'нагрів'::text,'Тостер нагрівав хліб хвилину, а потім вискочили золотисті тости.'::text),
(359799,39978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tostadora ... el pan durante un minuto y luego subieron las tostadas doradas.'::text,'calentó'::text,'estaba calentando'::text,'ha calentado'::text,'La tostadora calentó el pan durante un minuto y luego subieron las tostadas doradas.'::text),
(359798,39978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grille-pain ... le pain pendant une minute, puis les toasts dorés sont remontés.'::text,'a chauffé'::text,'chauffait'::text,'a chauffé'::text,'Le grille-pain a chauffé le pain pendant une minute, puis les toasts dorés sont remontés.'::text),
(359801,39978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tost makinesi ekmeği bir dakika ..., sonra altın rengi tostlar yukarı çıktı.'::text,'ısıttı'::text,'ısıtıyordu'::text,'ısıttı'::text,'Tost makinesi ekmeği bir dakika ısıttı, sonra altın rengi tostlar yukarı çıktı.'::text),
(359802,39978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenyérpirító egy percig ... a kenyeret, aztán felugrottak az aranybarna pirítósok.'::text,'melegítette'::text,'melegítette éppen'::text,'megmelegítette'::text,'A kenyérpirító egy percig melegítette a kenyeret, aztán felugrottak az aranybarna pirítósok.'::text),
(359805,39979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... der Jet-Toaster 240 Scheiben erhitzt, locker im Rahmen des Küchenbudgets.'::text,'hat'::text,'hat'::text,'erhitzt'::text,'Bisher hat der Jet-Toaster 240 Scheiben erhitzt, locker im Rahmen des Küchenbudgets.'::text),
(359809,39979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі тостер-винищувач ... 240 скибок, з великим запасом у межах кухонного бюджету.'::text,'нагрів'::text,'нагрівав'::text,'нагріває'::text,'Досі тостер-винищувач нагрів 240 скибок, з великим запасом у межах кухонного бюджету.'::text),
(359808,39979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, la tostadora-caza ... 240 rebanadas, muy dentro del presupuesto de cocina.'::text,'ha calentado'::text,'ha estado calentando'::text,'está calentando'::text,'Hasta ahora, la tostadora-caza ha calentado 240 rebanadas, muy dentro del presupuesto de cocina.'::text),
(359807,39979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, le grille-pain avion ... 240 tranches, largement dans le budget cuisine.'::text,'a chauffé'::text,'chauffe'::text,'est en train de chauffer'::text,'Jusqu''ici, le grille-pain avion a chauffé 240 tranches, largement dans le budget cuisine.'::text),
(359810,39979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar jet tost makinesi mutfak bütçesinin rahatça içinde kalarak 240 dilim ...'::text,'ısıttı'::text,'ısıtıyor'::text,'ısıtıyor'::text,'Şimdiye kadar jet tost makinesi mutfak bütçesinin rahatça içinde kalarak 240 dilim ısıttı.'::text),
(359811,39979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig a vadászgép-kenyérpirító 240 szeletet ..., bőven a konyhai kereten belül.'::text,'melegített meg'::text,'melegít'::text,'melegít'::text,'Eddig a vadászgép-kenyérpirító 240 szeletet melegített meg, bőven a konyhai kereten belül.'::text),
(359814,39980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum 9-Uhr-Meeting ... der Jet-Toaster beide Scheiben erhitzt, bis sie golden waren.'::text,'hatte'::text,'hat'::text,'erhitzt'::text,'Bis zum 9-Uhr-Meeting hatte der Jet-Toaster beide Scheiben erhitzt, bis sie golden waren.'::text),
(359818,39980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наради о 9:00 тостер-винищувач ... обидві скибки, аж поки вони не стали золотистими.'::text,'нагрів'::text,'нагрів'::text,'нагріває'::text,'До наради о 9:00 тостер-винищувач нагрів обидві скибки, аж поки вони не стали золотистими.'::text),
(359817,39980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la reunión de las 9:00, la tostadora-caza ya ... las dos rebanadas hasta dejarlas doradas.'::text,'había calentado'::text,'ha calentado'::text,'calienta'::text,'Para la reunión de las 9:00, la tostadora-caza ya había calentado las dos rebanadas hasta dejarlas doradas.'::text),
(359816,39980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant la réunion de 9 h, le grille-pain avion ... les deux tranches jusqu''à ce qu''elles soient dorées.'::text,'avait chauffé'::text,'a chauffé'::text,'chauffe'::text,'Avant la réunion de 9 h, le grille-pain avion avait chauffé les deux tranches jusqu''à ce qu''elles soient dorées.'::text),
(359819,39980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9 toplantısına kadar jet tost makinesi iki dilimi de altın rengi olana kadar ...'::text,'ısıtmıştı'::text,'ısıttı'::text,'ısıtıyor'::text,'Saat 9 toplantısına kadar jet tost makinesi iki dilimi de altın rengi olana kadar ısıtmıştı.'::text),
(359820,39980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 9 órás megbeszélésig a vadászgép-kenyérpirító mindkét szeletet ..., amíg aranybarnák nem lettek.'::text,'melegítette'::text,'melegítette'::text,'melegíti'::text,'A 9 órás megbeszélésig a vadászgép-kenyérpirító mindkét szeletet melegítette, amíg aranybarnák nem lettek.'::text),
(359823,39981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird der Jet-Toaster gerade 40 Scheiben für das Kundenfrühstück ...'::text,'erhitzen'::text,'erhitzen'::text,'erhitzt'::text,'Morgen um diese Zeit wird der Jet-Toaster gerade 40 Scheiben für das Kundenfrühstück erhitzen.'::text),
(359827,39981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час тостер-винищувач ... 40 скибок для сніданку з клієнтом.'::text,'нагріватиме'::text,'нагріє'::text,'нагріває'::text,'Завтра в цей час тостер-винищувач нагріватиме 40 скибок для сніданку з клієнтом.'::text),
(359826,39981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, la tostadora-caza ... 40 rebanadas para el desayuno con el cliente.'::text,'estará calentando'::text,'calentará'::text,'calienta'::text,'Mañana a esta hora, la tostadora-caza estará calentando 40 rebanadas para el desayuno con el cliente.'::text),
(359825,39981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, le grille-pain avion ... 40 tranches pour le petit-déjeuner client.'::text,'sera en train de chauffer'::text,'chauffera'::text,'chauffe'::text,'Demain à cette heure-ci, le grille-pain avion sera en train de chauffer 40 tranches pour le petit-déjeuner client.'::text),
(359828,39981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte jet tost makinesi müşteri kahvaltısı için 40 dilim ...'::text,'ısıtıyor olacak'::text,'ısıtacak'::text,'ısıtıyor'::text,'Yarın bu saatte jet tost makinesi müşteri kahvaltısı için 40 dilim ısıtıyor olacak.'::text),
(359829,39981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a vadászgép-kenyérpirító 40 szeletet ... az ügyfélreggelihez.'::text,'fog melegíteni'::text,'melegít majd'::text,'melegít'::text,'Holnap ilyenkor a vadászgép-kenyérpirító 40 szeletet fog melegíteni az ügyfélreggelihez.'::text),
(359832,39982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sobald die Scheiben abgesenkt sind, wird das Gerät sie in etwa zwei Minuten ...'::text,'erhitzen'::text,'gerade erhitzen'::text,'erhitzt'::text,'Sobald die Scheiben abgesenkt sind, wird das Gerät sie in etwa zwei Minuten erhitzen.'::text),
(359836,39982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно скибки опустяться, пристрій ... їх приблизно за дві хвилини.'::text,'нагріє'::text,'нагріватиме'::text,'нагріває'::text,'Щойно скибки опустяться, пристрій нагріє їх приблизно за дві хвилини.'::text),
(359835,39982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una vez bajadas las rebanadas, el dispositivo las ... en aproximadamente dos minutos.'::text,'calentará'::text,'estará calentando'::text,'está calentando'::text,'Una vez bajadas las rebanadas, el dispositivo las calentará en aproximadamente dos minutos.'::text),
(359834,39982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fois les tranches abaissées, l''appareil les ... en deux minutes environ.'::text,'chauffera'::text,'sera en train de chauffer'::text,'est en train de chauffer'::text,'Une fois les tranches abaissées, l''appareil les chauffera en deux minutes environ.'::text),
(359837,39982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dilimler indirildiğinde cihaz onları yaklaşık iki dakikada ...'::text,'ısıtacak'::text,'ısıtıyor olacak'::text,'ısıtıyor'::text,'Dilimler indirildiğinde cihaz onları yaklaşık iki dakikada ısıtacak.'::text),
(359838,39982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amint a szeletek lemennek, a készülék körülbelül két perc alatt ... őket.'::text,'felmelegíti'::text,'melegíteni fogja'::text,'melegíti'::text,'Amint a szeletek lemennek, a készülék körülbelül két perc alatt felmelegíti őket.'::text),
(359841,39983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Heizelemente das Brot lange genug ..., stößt das Gerät typischerweise blaue Flammen aus.'::text,'erhitzen'::text,'erhitzen werden'::text,'erhitzten'::text,'Wenn die Heizelemente das Brot lange genug erhitzen, stößt das Gerät typischerweise blaue Flammen aus.'::text),
(359845,39983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо нагрівальні елементи ... хліб достатньо довго, пристрій зазвичай випускає синє полум''я.'::text,'нагрівають'::text,'нагріють'::text,'нагрівали'::text,'Якщо нагрівальні елементи нагрівають хліб достатньо довго, пристрій зазвичай випускає синє полум''я.'::text),
(359844,39983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los elementos ... el pan el tiempo suficiente, el dispositivo suele emitir llamas azules.'::text,'calientan'::text,'calentarán'::text,'calentaban'::text,'Si los elementos calientan el pan el tiempo suficiente, el dispositivo suele emitir llamas azules.'::text),
(359843,39983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les résistances ... le pain assez longtemps, l''appareil émet généralement des flammes bleues.'::text,'chauffent'::text,'chaufferont'::text,'chauffaient'::text,'Si les résistances chauffent le pain assez longtemps, l''appareil émet généralement des flammes bleues.'::text),
(359846,39983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Isıtıcı teller ekmeği yeterince uzun süre ..., cihaz genellikle mavi alevler çıkarır.'::text,'ısıtırsa'::text,'ısıtacaksa'::text,'ısıttıysa'::text,'Isıtıcı teller ekmeği yeterince uzun süre ısıtırsa, cihaz genellikle mavi alevler çıkarır.'::text),
(359847,39983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fűtőszálak elég sokáig ... a kenyeret, a készülék jellemzően kék lángokat bocsát ki.'::text,'melegítik'::text,'melegíteni fogják'::text,'melegítették'::text,'Ha a fűtőszálak elég sokáig melegítik a kenyeret, a készülék jellemzően kék lángokat bocsát ki.'::text),
(359850,39984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Hebel unten bleibt, ... das Gerät die Scheiben, bis sie deutlich dunkler werden.'::text,'erhitzt'::text,'würde erhitzen'::text,'erhitzte'::text,'Wenn der Hebel unten bleibt, erhitzt das Gerät die Scheiben, bis sie deutlich dunkler werden.'::text),
(359854,39984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо важіль залишиться внизу, пристрій ... скибки, доки вони помітно не потемніють.'::text,'нагріватиме'::text,'нагрівав би'::text,'нагрівав'::text,'Якщо важіль залишиться внизу, пристрій нагріватиме скибки, доки вони помітно не потемніють.'::text),
(359853,39984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la palanca se queda abajo, el dispositivo ... las rebanadas hasta que se oscurezcan considerablemente.'::text,'calentará'::text,'calentaría'::text,'calentó'::text,'Si la palanca se queda abajo, el dispositivo calentará las rebanadas hasta que se oscurezcan considerablemente.'::text),
(359852,39984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le levier reste en bas, l''appareil ... les tranches jusqu''à ce qu''elles deviennent nettement plus foncées.'::text,'chauffera'::text,'chaufferait'::text,'a chauffé'::text,'Si le levier reste en bas, l''appareil chauffera les tranches jusqu''à ce qu''elles deviennent nettement plus foncées.'::text),
(359855,39984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kol aşağıda kalırsa cihaz dilimleri belirgin şekilde koyulaşana kadar ...'::text,'ısıtacak'::text,'ısıtırdı'::text,'ısıttı'::text,'Kol aşağıda kalırsa cihaz dilimleri belirgin şekilde koyulaşana kadar ısıtacak.'::text),
(359856,39984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kar lent marad, a készülék addig ... a szeleteket, amíg jóval sötétebbek nem lesznek.'::text,'fogja melegíteni'::text,'melegítené'::text,'melegítette'::text,'Ha a kar lent marad, a készülék addig fogja melegíteni a szeleteket, amíg jóval sötétebbek nem lesznek.'::text),
(359859,39985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser Jet das Brot noch schneller erhitzen würde, ... er abheben, weil Jets schnell sind.'::text,'würde'::text,'wird'::text,'hebt'::text,'Wenn dieser Jet das Brot noch schneller erhitzen würde, würde er abheben, weil Jets schnell sind.'::text),
(359863,39985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби цей винищувач нагрівав хліб ще швидше, він ..., бо винищувачі швидкі.'::text,'злетів би'::text,'злетить'::text,'злітає'::text,'Якби цей винищувач нагрівав хліб ще швидше, він злетів би, бо винищувачі швидкі.'::text),
(359862,39985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si este caza calentara el pan aún más rápido, ..., porque los cazas son rápidos.'::text,'despegaría'::text,'despegará'::text,'despega'::text,'Si este caza calentara el pan aún más rápido, despegaría, porque los cazas son rápidos.'::text),
(359861,39985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cet avion chauffait le pain encore plus vite, il ..., parce que les avions sont rapides.'::text,'décollerait'::text,'décollera'::text,'décolle'::text,'Si cet avion chauffait le pain encore plus vite, il décollerait, parce que les avions sont rapides.'::text),
(359864,39985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu jet ekmeği daha da hızlı ısıtsa ..., çünkü jetler hızlıdır.'::text,'havalanırdı'::text,'havalanacak'::text,'havalanıyor'::text,'Bu jet ekmeği daha da hızlı ısıtsa havalanırdı, çünkü jetler hızlıdır.'::text),
(359865,39985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a gép még gyorsabban melegítené a kenyeret, ..., mert a vadászgépek gyorsak.'::text,'felszállna'::text,'fel fog szállni'::text,'felszáll'::text,'Ha ez a gép még gyorsabban melegítené a kenyeret, felszállna, mert a vadászgépek gyorsak.'::text),
(359868,39986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Brot ... heute Morgen von einem Jet erhitzt, also war es ein sehr schnelles Frühstück.'::text,'wurde'::text,'wird'::text,'erhitzte'::text,'Das Brot wurde heute Morgen von einem Jet erhitzt, also war es ein sehr schnelles Frühstück.'::text),
(359872,39986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хліб ... сьогодні вранці винищувачем, тож сніданок був дуже швидкий.'::text,'був нагрітий'::text,'нагрівається'::text,'нагрів'::text,'Хліб був нагрітий сьогодні вранці винищувачем, тож сніданок був дуже швидкий.'::text),
(359871,39986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pan ... por un caza esta mañana, así que fue un desayuno muy rápido.'::text,'fue calentado'::text,'es calentado'::text,'calentó'::text,'El pan fue calentado por un caza esta mañana, así que fue un desayuno muy rápido.'::text),
(359870,39986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pain ... par un avion ce matin, donc c''était un petit-déjeuner très rapide.'::text,'a été chauffé'::text,'est chauffé'::text,'a chauffé'::text,'Le pain a été chauffé par un avion ce matin, donc c''était un petit-déjeuner très rapide.'::text),
(359873,39986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekmek bu sabah bir jet tarafından ..., yani çok hızlı bir kahvaltıydı.'::text,'ısıtıldı'::text,'ısıtılıyor'::text,'ısıttı'::text,'Ekmek bu sabah bir jet tarafından ısıtıldı, yani çok hızlı bir kahvaltıydı.'::text),
(359874,39986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenyeret ma reggel egy vadászgép ..., szóval nagyon gyors reggeli volt.'::text,'melegítette meg'::text,'melegíti meg'::text,'melegítette'::text,'A kenyeret ma reggel egy vadászgép melegítette meg, szóval nagyon gyors reggeli volt.'::text),
(398271,44253,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... gerade den versunkenen Baumstamm entlang, als ich im durchsichtigen Wasser einen Frosch bemerkte.'::text,'lief'::text,'bin gelaufen'::text,'laufe'::text,'Ich lief gerade den versunkenen Baumstamm entlang, als ich im durchsichtigen Wasser einen Frosch bemerkte.'::text),
(398275,44253,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я ... по затопленій колоді, коли помітив жабу в прозорій воді.'::text,'йшов'::text,'пройшов'::text,'іду'::text,'Я йшов по затопленій колоді, коли помітив жабу в прозорій воді.'::text),
(398274,44253,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo ... por el tronco hundido cuando vi una rana en el agua transparente.'::text,'caminaba'::text,'he caminado'::text,'camino'::text,'Yo caminaba por el tronco hundido cuando vi una rana en el agua transparente.'::text),
(398273,44253,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je ... sur le tronc immergé quand j''ai remarqué une grenouille dans l''eau transparente.'::text,'marchais'::text,'ai marché'::text,'marche'::text,'Je marchais sur le tronc immergé quand j''ai remarqué une grenouille dans l''eau transparente.'::text),
(398276,44253,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Batık kütüğün üzerinde ... şeffaf suda bir kurbağa fark ettim.'::text,'yürürken'::text,'yürüdüm'::text,'yürüyorum'::text,'Batık kütüğün üzerinde yürürken şeffaf suda bir kurbağa fark ettim.'::text),
(398277,44253,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen a víz alatti farönkön ..., amikor észrevettem egy békát az átlátszó vízben.'::text,'sétáltam'::text,'sétáltam'::text,'sétálok'::text,'Éppen a víz alatti farönkön sétáltam, amikor észrevettem egy békát az átlátszó vízben.'::text),
(398280,44254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... seit einer Stunde auf diesem Baumstamm im durchsichtigen See, und jetzt will der Frosch Rache!'::text,'stehe'::text,'stehe'::text,'stehe'::text,'Ich stehe seit einer Stunde auf diesem Baumstamm im durchsichtigen See, und jetzt will der Frosch Rache!'::text),
(398284,44254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я ... на цій колоді в прозорому озері вже годину, а тепер жаба хоче помсти!'::text,'стою'::text,'стою'::text,'стою'::text,'Я стою на цій колоді в прозорому озері вже годину, а тепер жаба хоче помсти!'::text),
(398283,44254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Yo ... de pie en este tronco del lago transparente una hora, y ahora la rana quiere venganza!'::text,'llevo'::text,'estoy'::text,'estoy'::text,'¡Yo llevo de pie en este tronco del lago transparente una hora, y ahora la rana quiere venganza!'::text),
(398282,44254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je ... sur ce tronc dans le lac transparent depuis une heure, et maintenant la grenouille veut se venger !'::text,'suis debout'::text,'suis debout'::text,'me tiens'::text,'Je suis debout sur ce tronc dans le lac transparent depuis une heure, et maintenant la grenouille veut se venger !'::text),
(398285,44254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir şeffaf göldeki bu kütüğün üstünde ... ve şimdi kurbağa intikam istiyor!'::text,'duruyorum'::text,'duruyorum'::text,'dururum'::text,'Bir saattir şeffaf göldeki bu kütüğün üstünde duruyorum ve şimdi kurbağa intikam istiyor!'::text),
(398286,44254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... ezen a farönkön az átlátszó tóban, és most a béka bosszút akar!'::text,'állok'::text,'állok'::text,'állok'::text,'Már egy órája állok ezen a farönkön az átlátszó tóban, és most a béka bosszút akar!'::text),
(398289,44255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... gerade das durchsichtige Wasser, als plötzlich ein Frosch auf meine Kamera zuschwamm. Katastrophe!'::text,'filmte'::text,'filmte'::text,'habe gefilmt'::text,'Ich filmte gerade das durchsichtige Wasser, als plötzlich ein Frosch auf meine Kamera zuschwamm. Katastrophe!'::text),
(398293,44255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я ... прозору воду, коли раптом до моєї камери підпливла жаба. Катастрофа!'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Я знімав прозору воду, коли раптом до моєї камери підпливла жаба. Катастрофа!'::text),
(398292,44255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo ... el agua transparente cuando de repente una rana nadó hacia mi cámara. ¡Un desastre!'::text,'estaba grabando'::text,'grabé'::text,'he grabado'::text,'Yo estaba grabando el agua transparente cuando de repente una rana nadó hacia mi cámara. ¡Un desastre!'::text),
(398291,44255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je ... l''eau transparente quand soudain une grenouille a nagé vers ma caméra. La cata !'::text,'filmais'::text,'ai filmé'::text,'ai filmé'::text,'Je filmais l''eau transparente quand soudain une grenouille a nagé vers ma caméra. La cata !'::text),
(398294,44255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şeffaf suyu ... birden bir kurbağa kameraya doğru yüzdü. Felaket!'::text,'çekerken'::text,'çektim'::text,'çektim'::text,'Şeffaf suyu çekerken birden bir kurbağa kameraya doğru yüzdü. Felaket!'::text),
(398295,44255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen ... az átlátszó vizet, amikor hirtelen egy béka a kamerámhoz úszott. Katasztrófa!'::text,'filmeztem'::text,'lefilmeztem'::text,'lefilmeztem'::text,'Éppen filmeztem az átlátszó vizet, amikor hirtelen egy béka a kamerámhoz úszott. Katasztrófa!'::text),
(398298,44256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar ... heute bisher dreimal durch das durchsichtige Flachwasser geschwommen.'::text,'ist'::text,'ist'::text,'schwimmt'::text,'Das Exemplar ist heute bisher dreimal durch das durchsichtige Flachwasser geschwommen.'::text),
(398302,44256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особина сьогодні вже тричі ... через прозоре мілководдя.'::text,'перепливла'::text,'пливла'::text,'пливе'::text,'Особина сьогодні вже тричі перепливла через прозоре мілководдя.'::text),
(398301,44256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ejemplar ... tres veces por los bajíos transparentes en lo que va de día.'::text,'ha nadado'::text,'ha estado nadando'::text,'está nadando'::text,'El ejemplar ha nadado tres veces por los bajíos transparentes en lo que va de día.'::text),
(398300,44256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen ... trois fois à travers les hauts-fonds transparents aujourd''hui.'::text,'a nagé'::text,'nage'::text,'nage'::text,'Le spécimen a nagé trois fois à travers les hauts-fonds transparents aujourd''hui.'::text),
(398303,44256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örnek bugün şimdiye kadar şeffaf sığlıkları üç kez ...'::text,'yüzerek geçti'::text,'yüzüyor'::text,'yüzüyor'::text,'Örnek bugün şimdiye kadar şeffaf sığlıkları üç kez yüzerek geçti.'::text),
(398304,44256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A példány ma eddig háromszor ... át az átlátszó sekélyesen.'::text,'úszott'::text,'úszkált'::text,'úszik'::text,'A példány ma eddig háromszor úszott át az átlátszó sekélyesen.'::text),
(398307,44257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kamera ins durchsichtige Wasser eintauchte, ... das Exemplar den Baumstamm bereits erreicht.'::text,'hatte'::text,'hat'::text,'erreicht'::text,'Als die Kamera ins durchsichtige Wasser eintauchte, hatte das Exemplar den Baumstamm bereits erreicht.'::text),
(398311,44257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли камера занурилася в прозору воду, особина вже ... до колоди.'::text,'дісталася'::text,'дісталася'::text,'дістається'::text,'Коли камера занурилася в прозору воду, особина вже дісталася до колоди.'::text),
(398310,44257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la cámara entró en el agua transparente, el ejemplar ya ... el tronco.'::text,'había alcanzado'::text,'ha alcanzado'::text,'alcanza'::text,'Cuando la cámara entró en el agua transparente, el ejemplar ya había alcanzado el tronco.'::text),
(398309,44257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la caméra est entrée dans l''eau transparente, le spécimen ... le tronc.'::text,'avait déjà atteint'::text,'a déjà atteint'::text,'atteint'::text,'Quand la caméra est entrée dans l''eau transparente, le spécimen avait déjà atteint le tronc.'::text),
(398312,44257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera şeffaf suya girdiğinde örnek kütüğe çoktan ...'::text,'ulaşmıştı'::text,'ulaştı'::text,'ulaşıyor'::text,'Kamera şeffaf suya girdiğinde örnek kütüğe çoktan ulaşmıştı.'::text),
(398313,44257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamera belemerült az átlátszó vízbe, a példány már ... a farönkhöz.'::text,'odaért'::text,'odaért'::text,'odaér'::text,'Mire a kamera belemerült az átlátszó vízbe, a példány már odaért a farönkhöz.'::text),
(398316,44258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird der Frosch durch das durchsichtige Flachwasser ..., wie er es typischerweise tut.'::text,'schwimmen'::text,'schwimmen'::text,'schwimmt'::text,'Morgen um diese Zeit wird der Frosch durch das durchsichtige Flachwasser schwimmen, wie er es typischerweise tut.'::text),
(398320,44258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час жаба ... прозорим мілководдям, як вона зазвичай робить.'::text,'плаватиме'::text,'попливе'::text,'плаває'::text,'Завтра в цей час жаба плаватиме прозорим мілководдям, як вона зазвичай робить.'::text),
(398319,44258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, la rana ... por los bajíos transparentes, como suele hacer.'::text,'estará nadando'::text,'nadará'::text,'nada'::text,'Mañana a esta hora, la rana estará nadando por los bajíos transparentes, como suele hacer.'::text),
(398318,44258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, la grenouille ... dans les hauts-fonds transparents, comme elle le fait habituellement.'::text,'sera en train de nager'::text,'nagera'::text,'nage'::text,'Demain à cette heure-ci, la grenouille sera en train de nager dans les hauts-fonds transparents, comme elle le fait habituellement.'::text),
(398321,44258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte kurbağa, genelde yaptığı gibi, şeffaf sığlıklarda ...'::text,'yüzüyor olacak'::text,'yüzecek'::text,'yüzer'::text,'Yarın bu saatte kurbağa, genelde yaptığı gibi, şeffaf sığlıklarda yüzüyor olacak.'::text),
(398322,44258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a béka az átlátszó sekélyesben ..., ahogy jellemzően szokott.'::text,'fog úszkálni'::text,'úszik majd'::text,'úszik'::text,'Holnap ilyenkor a béka az átlátszó sekélyesben fog úszkálni, ahogy jellemzően szokott.'::text),
(398325,44259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der See ist durchsichtig, also ... ich den Grund, wenn ich nach unten schaue.'::text,'sehe'::text,'werde gerade sehen'::text,'sah'::text,'Der See ist durchsichtig, also sehe ich den Grund, wenn ich nach unten schaue.'::text),
(398329,44259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Озеро прозоре, тож я ... дно, коли подивлюся вниз.'::text,'побачу'::text,'бачитиму'::text,'бачив'::text,'Озеро прозоре, тож я побачу дно, коли подивлюся вниз.'::text),
(398328,44259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lago es transparente, así que ... el fondo cuando mire hacia abajo.'::text,'veré'::text,'estaré viendo'::text,'vi'::text,'El lago es transparente, así que veré el fondo cuando mire hacia abajo.'::text),
(398327,44259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lac est transparent, donc je ... le fond quand je regarderai en bas.'::text,'verrai'::text,'serai en train de voir'::text,'ai vu'::text,'Le lac est transparent, donc je verrai le fond quand je regarderai en bas.'::text),
(398330,44259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Göl şeffaf, yani aşağı baktığımda dibi ...'::text,'göreceğim'::text,'görüyor olacağım'::text,'gördüm'::text,'Göl şeffaf, yani aşağı baktığımda dibi göreceğim.'::text),
(398331,44259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tó átlátszó, szóval ... az alját, amikor lenézek.'::text,'látni fogom'::text,'látni fogom'::text,'láttam'::text,'A tó átlátszó, szóval látni fogom az alját, amikor lenézek.'::text),
(398343,44261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Frosch noch näher schwimmt, ... die Kamera ihn klar durch das durchsichtige Wasser.'::text,'filmt'::text,'würde filmen'::text,'filmte'::text,'Wenn der Frosch noch näher schwimmt, filmt die Kamera ihn klar durch das durchsichtige Wasser.'::text),
(398347,44261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо жаба підпливе ще ближче, камера чітко ... її крізь прозору воду.'::text,'зніме'::text,'зняла б'::text,'зняла'::text,'Якщо жаба підпливе ще ближче, камера чітко зніме її крізь прозору воду.'::text),
(398346,44261,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rana se acerca más nadando, la cámara la ... con claridad a través del agua transparente.'::text,'grabará'::text,'grabaría'::text,'grabó'::text,'Si la rana se acerca más nadando, la cámara la grabará con claridad a través del agua transparente.'::text),
(398345,44261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la grenouille nage encore plus près, la caméra la ... nettement à travers l''eau transparente.'::text,'filmera'::text,'filmerait'::text,'filma'::text,'Si la grenouille nage encore plus près, la caméra la filmera nettement à travers l''eau transparente.'::text),
(398348,44261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kurbağa biraz daha yaklaşırsa kamera onu şeffaf suyun içinden net bir şekilde ...'::text,'çekecek'::text,'çekerdi'::text,'çekti'::text,'Kurbağa biraz daha yaklaşırsa kamera onu şeffaf suyun içinden net bir şekilde çekecek.'::text),
(398349,44261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a béka még közelebb úszik, a kamera tisztán ... az átlátszó vízen át.'::text,'le fogja filmezni'::text,'lefilmezné'::text,'lefilmezte'::text,'Ha a béka még közelebb úszik, a kamera tisztán le fogja filmezni az átlátszó vízen át.'::text),
(398352,44262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Wasser nicht so durchsichtig wäre, ... wir die Steine am Grund nicht sehen.'::text,'würden'::text,'werden'::text,NULL::text,'Wenn das Wasser nicht so durchsichtig wäre, würden wir die Steine am Grund nicht sehen.'::text),
(398356,44262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вода не була такою прозорою, ми ... каміння на дні.'::text,'не бачили б'::text,'не побачимо'::text,'не бачимо'::text,'Якби вода не була такою прозорою, ми не бачили б каміння на дні.'::text),
(398355,44262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el agua no fuera tan transparente, no ... las piedras del fondo.'::text,'veríamos'::text,'veremos'::text,'vemos'::text,'Si el agua no fuera tan transparente, no veríamos las piedras del fondo.'::text),
(398354,44262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''eau n''était pas si transparente, on ne ... pas les pierres au fond.'::text,'verrait'::text,'verra'::text,'voit'::text,'Si l''eau n''était pas si transparente, on ne verrait pas les pierres au fond.'::text),
(398357,44262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su bu kadar şeffaf olmasa dipteki taşları ...'::text,'görmezdik'::text,'görmeyeceğiz'::text,'görmüyoruz'::text,'Su bu kadar şeffaf olmasa dipteki taşları görmezdik.'::text),
(398358,44262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a víz nem lenne ilyen átlátszó, nem ... a köveket a fenéken.'::text,'látnánk'::text,'fogjuk látni'::text,'látjuk'::text,'Ha a víz nem lenne ilyen átlátszó, nem látnánk a köveket a fenéken.'::text),
(398361,44263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Steine am Grund ... klar durch das durchsichtige Wasser zu sehen.'::text,'waren'::text,'konnten'::text,'sahen'::text,'Die Steine am Grund waren klar durch das durchsichtige Wasser zu sehen.'::text),
(398365,44263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Каміння на дні ... чітко крізь прозору воду.'::text,'було видно'::text,'могло бачити'::text,'бачило'::text,'Каміння на дні було видно чітко крізь прозору воду.'::text),
(398364,44263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las piedras del fondo ... con claridad a través del agua transparente.'::text,'se podían ver'::text,'podían ver'::text,'estaban viendo'::text,'Las piedras del fondo se podían ver con claridad a través del agua transparente.'::text),
(398363,44263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pierres au fond ... nettement à travers l''eau transparente.'::text,'pouvaient être vues'::text,'pouvaient voir'::text,'voyaient'::text,'Les pierres au fond pouvaient être vues nettement à travers l''eau transparente.'::text),
(398366,44263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dipteki taşlar şeffaf suyun içinden net bir şekilde ...'::text,'görülebiliyordu'::text,'görebiliyordu'::text,'görüyordu'::text,'Dipteki taşlar şeffaf suyun içinden net bir şekilde görülebiliyordu.'::text),
(398367,44263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fenéken lévő kövek tisztán ... az átlátszó vízen át.'::text,'látszottak'::text,'láthattak'::text,'láttak'::text,'A fenéken lévő kövek tisztán látszottak az átlátszó vízen át.'::text),
(385284,42810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, anscheinend ... er den ganzen Apfelbaum, und der Hund schaute nur zu.'::text,'schüttelte'::text,'wurde geschüttelt'::text,'schüttelnd'::text,'Süße, anscheinend schüttelte er den ganzen Apfelbaum, und der Hund schaute nur zu.'::text),
(385288,42810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... всю яблуню, а пес просто дивився.'::text,'потряс'::text,'був потрясений'::text,'трясучи'::text,'Подруго, кажуть, він потряс всю яблуню, а пес просто дивився.'::text),
(385287,42810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer él ... el manzano entero, y el perro solo miraba.'::text,'sacudió'::text,'fue sacudido'::text,'sacudiendo'::text,'Tía, al parecer él sacudió el manzano entero, y el perro solo miraba.'::text),
(385286,42810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... tout le pommier, et le chien a juste regardé.'::text,'a secoué'::text,'a été secoué'::text,'secouant'::text,'Meuf, apparemment il a secoué tout le pommier, et le chien a juste regardé.'::text),
(385289,42810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre bütün elma ağacını ..., köpek de sadece izlemiş.'::text,'sallamış'::text,'sallanmış'::text,'sallayarak'::text,'Kızım, duyduğuma göre bütün elma ağacını sallamış, köpek de sadece izlemiş.'::text),
(385290,42810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ... az egész almafát, a kutya meg csak nézte.'::text,'megrázta'::text,'meg lett rázva'::text,'rázva'::text,'Csajszi, állítólag megrázta az egész almafát, a kutya meg csak nézte.'::text),
(385293,42811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... er den Baum für seinen Hund schütteln, aber keiner weiß es genau.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Hör zu, anscheinend könnte er den Baum für seinen Hund schütteln, aber keiner weiß es genau.'::text),
(385297,42811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... трусити дерево для свого пса, але ніхто точно не знає.'::text,'може'::text,'мусить'::text,'мав би'::text,'Слухай, кажуть, він може трусити дерево для свого пса, але ніхто точно не знає.'::text),
(385296,42811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer él ... sacudir el árbol para su perro, pero nadie lo sabe seguro.'::text,'podría'::text,'debe de'::text,'debería'::text,'Oye, al parecer él podría sacudir el árbol para su perro, pero nadie lo sabe seguro.'::text),
(385295,42811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... secouer l''arbre pour son chien, mais personne n''en est sûr.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Écoute, apparemment il pourrait secouer l''arbre pour son chien, mais personne n''en est sûr.'::text),
(385298,42811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre ağacı köpeği için ..., ama kimse emin değil.'::text,'sallıyor olabilir'::text,'sallıyor olmalı'::text,'sallamalı'::text,'Dinle, duyduğuma göre ağacı köpeği için sallıyor olabilir, ama kimse emin değil.'::text),
(385299,42811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ... a fát a kutyájának, de senki sem tudja biztosan.'::text,'megrázhatja'::text,'meg kell ráznia'::text,'meg kellene ráznia'::text,'Figyelj, állítólag megrázhatja a fát a kutyájának, de senki sem tudja biztosan.'::text),
(385302,42812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, der Ast, ... du so fest geschüttelt hast, hat überall Äpfel abgeworfen.'::text,'den'::text,'der'::text,'dessen'::text,'Ehrlich, der Ast, den du so fest geschüttelt hast, hat überall Äpfel abgeworfen.'::text),
(385306,42812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, гілка, ... ти так сильно трусонув, скинула яблука всюди.'::text,'яку'::text,'хто'::text,'чия'::text,'Чесно, гілка, яку ти так сильно трусонув, скинула яблука всюди.'::text),
(385305,42812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, la rama ... sacudiste tan fuerte tiró manzanas por todas partes.'::text,'que'::text,'quien'::text,'cuya'::text,'En serio, la rama que sacudiste tan fuerte tiró manzanas por todas partes.'::text),
(385304,42812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la branche ... tu as secouée si fort a fait tomber des pommes partout.'::text,'que'::text,'qui'::text,'dont'::text,'Franchement, la branche que tu as secouée si fort a fait tomber des pommes partout.'::text),
(385307,42812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o kadar sert ... dal her yere elma döktü.'::text,'salladığın'::text,'salladığın'::text,'salladığın'::text,'Açıkçası, o kadar sert salladığın dal her yere elma döktü.'::text),
(385308,42812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az az ág, ... olyan erősen megráztál, mindenhová almát szórt.'::text,'amit'::text,'aki'::text,'akinek a'::text,'Őszintén, az az ág, amit olyan erősen megráztál, mindenhová almát szórt.'::text),
(385311,42813,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... den Ast nur einmal schütteln, und ehrlich, der Apfelregen war legendär.'::text,'würdest'::text,'wirst'::text,'schüttelst'::text,'Du hast gesagt, du würdest den Ast nur einmal schütteln, und ehrlich, der Apfelregen war legendär.'::text),
(385315,42813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав, що ... гілку лише раз, і чесно, той яблучний дощ був легендарний.'::text,'трусонеш'::text,'трусонеш'::text,'трусиш'::text,'Ти сказав, що трусонеш гілку лише раз, і чесно, той яблучний дощ був легендарний.'::text),
(385314,42813,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... la rama solo una vez, y la verdad, la lluvia de manzanas fue icónica.'::text,'sacudirías'::text,'sacudirás'::text,'estás sacudiendo'::text,'Dijiste que sacudirías la rama solo una vez, y la verdad, la lluvia de manzanas fue icónica.'::text),
(385313,42813,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... la branche une seule fois, et franchement, la pluie de pommes était iconique.'::text,'secouerais'::text,'secoueras'::text,'secoues'::text,'Tu as dit que tu secouerais la branche une seule fois, et franchement, la pluie de pommes était iconique.'::text),
(385316,42813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalı sadece bir kez ... söylemiştin ve açıkçası o elma yağmuru efsaneydi.'::text,'sallayacağını'::text,'sallayacağını'::text,'salladığını'::text,'Dalı sadece bir kez sallayacağını söylemiştin ve açıkçası o elma yağmuru efsaneydi.'::text),
(385317,42813,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy csak egyszer ... meg az ágat, és őszintén, az almaeső ikonikus volt.'::text,'rázod'::text,'rázod'::text,'rázod'::text,'Azt mondtad, hogy csak egyszer rázod meg az ágat, és őszintén, az almaeső ikonikus volt.'::text),
(385329,42815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschloss, den Ast nachts ..., offensichtlich die beste Zeit zum Äpfelpflücken.'::text,'zu schütteln'::text,'Schütteln'::text,'schütteln'::text,'Er beschloss, den Ast nachts zu schütteln, offensichtlich die beste Zeit zum Äpfelpflücken.'::text),
(385333,42815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішив ... гілку вночі, очевидно, найкращий час для збору яблук.'::text,'потрусити'::text,'трусіння'::text,'потрусити'::text,'Він вирішив потрусити гілку вночі, очевидно, найкращий час для збору яблук.'::text),
(385332,42815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decidió ... la rama de noche, obviamente el mejor momento para recoger manzanas.'::text,'sacudir'::text,'sacudiendo'::text,'sacudir'::text,'Decidió sacudir la rama de noche, obviamente el mejor momento para recoger manzanas.'::text),
(385331,42815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a décidé ... la branche la nuit, évidemment le meilleur moment pour cueillir des pommes.'::text,'de secouer'::text,'secouant'::text,'secouer'::text,'Il a décidé de secouer la branche la nuit, évidemment le meilleur moment pour cueillir des pommes.'::text),
(385334,42815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalı gece ... karar verdi, belli ki elma toplamak için en iyi zaman.'::text,'sallamaya'::text,'sallamaya'::text,'sallamaya'::text,'Dalı gece sallamaya karar verdi, belli ki elma toplamak için en iyi zaman.'::text),
(385335,42815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy éjjel ... meg az ágat, nyilván ez a legjobb idő almaszedésre.'::text,'rázza'::text,'rázás'::text,'rázza'::text,'Úgy döntött, hogy éjjel rázza meg az ágat, nyilván ez a legjobb idő almaszedésre.'::text),
(385338,42816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, du hast den Baum irgendwie zu doll geschüttelt, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Bro, du hast den Baum irgendwie zu doll geschüttelt, oder?'::text),
(385342,42816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти якось надто сильно потряс те дерево, ...?'::text,'так'::text,'так'::text,'так'::text,'Бро, ти якось надто сильно потряс те дерево, так?'::text),
(385341,42816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sacudiste ese árbol un poco demasiado fuerte, ¿...?'::text,'no'::text,'no'::text,'no'::text,'Bro, sacudiste ese árbol un poco demasiado fuerte, ¿no?'::text),
(385340,42816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, t''as un peu trop secoué cet arbre, ... ?'::text,'non'::text,'non'::text,'non'::text,'Frère, t''as un peu trop secoué cet arbre, non ?'::text),
(385343,42816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ağacı biraz fazla sert salladın, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kanka, o ağacı biraz fazla sert salladın, değil mi?'::text),
(385344,42816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, kicsit túl erősen ráztad meg azt a fát, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'Tesó, kicsit túl erősen ráztad meg azt a fát, nem?'::text),
(385347,42817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der niedrige Ast wackelte, und ...'::text,'die Äpfel daran auch'::text,'die Äpfel daran auch'::text,'die Äpfel daran auch nicht'::text,'Der niedrige Ast wackelte, und die Äpfel daran auch.'::text),
(385351,42817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Низька гілка трусилася, і ...'::text,'яблука на ній теж'::text,'яблука на ній теж'::text,'яблука на ній теж ні'::text,'Низька гілка трусилася, і яблука на ній теж.'::text),
(385350,42817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rama baja temblaba, y ...'::text,'también las manzanas que tenía'::text,'también las manzanas que tenía'::text,'tampoco las manzanas que tenía'::text,'La rama baja temblaba, y también las manzanas que tenía.'::text),
(385349,42817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La branche basse tremblait, et ...'::text,'les pommes dessus aussi'::text,'les pommes dessus aussi'::text,'les pommes dessus non plus'::text,'La branche basse tremblait, et les pommes dessus aussi.'::text),
(385352,42817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alçak dal sallanıyordu, ...'::text,'üstündeki elmalar da öyle'::text,'üstündeki elmalar da öyle'::text,'üstündeki elmalar da değil'::text,'Alçak dal sallanıyordu, üstündeki elmalar da öyle.'::text),
(385353,42817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alacsony ág remegett, és ...'::text,'a rajta lévő almák is'::text,'a rajta lévő almák is'::text,'a rajta lévő almák sem'::text,'Az alacsony ág remegett, és a rajta lévő almák is.'::text),
(385356,42818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Ast eine Minute lang geschüttelt, bevor endlich die letzten Äpfel fielen.'::text,'hatte'::text,'hat'::text,'schüttelt'::text,'Er hatte den Ast eine Minute lang geschüttelt, bevor endlich die letzten Äpfel fielen.'::text),
(385360,42818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... гілку цілу хвилину, перш ніж нарешті впали останні яблука.'::text,'трусив'::text,'трусить'::text,'трусить'::text,'Він трусив гілку цілу хвилину, перш ніж нарешті впали останні яблука.'::text),
(385359,42818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la rama durante un minuto antes de que por fin cayeran las últimas manzanas.'::text,'había estado sacudiendo'::text,'ha estado sacudiendo'::text,'está sacudiendo'::text,'Él había estado sacudiendo la rama durante un minuto antes de que por fin cayeran las últimas manzanas.'::text),
(385358,42818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la branche pendant une minute avant que les dernières pommes ne tombent enfin.'::text,'avait secoué'::text,'a secoué'::text,'secoue'::text,'Il avait secoué la branche pendant une minute avant que les dernières pommes ne tombent enfin.'::text),
(385361,42818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son elmalar nihayet düşene kadar dalı bir dakika boyunca ...'::text,'sallıyordu'::text,'sallıyor'::text,'sallıyor'::text,'Son elmalar nihayet düşene kadar dalı bir dakika boyunca sallıyordu.'::text),
(385362,42818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy percig ... az ágat, mielőtt végre lehullottak az utolsó almák.'::text,'rázta'::text,'rázza'::text,'rázza'::text,'Egy percig rázta az ágat, mielőtt végre lehullottak az utolsó almák.'::text),
(385365,42819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis der Hund zurückkommt, wird er jeden Apfel vom Baum ...'::text,'geschüttelt haben'::text,'schütteln'::text,'gerade schütteln'::text,'Bis der Hund zurückkommt, wird er jeden Apfel vom Baum geschüttelt haben.'::text),
(385369,42819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки пес повернеться, він уже ... з дерева кожне яблуко.'::text,'струсить'::text,'струсить'::text,'труситиме'::text,'Поки пес повернеться, він уже струсить з дерева кожне яблуко.'::text),
(385368,42819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando vuelva el perro, él ... todas las manzanas del árbol.'::text,'habrá sacudido'::text,'sacudirá'::text,'estará sacudiendo'::text,'Para cuando vuelva el perro, él habrá sacudido todas las manzanas del árbol.'::text),
(385367,42819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que le chien revienne, il ... toutes les pommes de l''arbre.'::text,'aura fait tomber'::text,'fera tomber'::text,'sera en train de faire tomber'::text,'D''ici à ce que le chien revienne, il aura fait tomber toutes les pommes de l''arbre.'::text),
(385370,42819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek geri döndüğünde ağaçtaki bütün elmaları ...'::text,'silkelemiş olacak'::text,'silkeleyecek'::text,'silkeliyor olacak'::text,'Köpek geri döndüğünde ağaçtaki bütün elmaları silkelemiş olacak.'::text),
(385371,42819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kutya visszajön, ... a fáról az összes almát.'::text,'már lerázta'::text,'le fogja rázni'::text,'éppen rázni fogja'::text,'Mire a kutya visszajön, már lerázta a fáról az összes almát.'::text),
(345828,38426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tour ihr Ziel von 50 Buchungen erreicht hätte, ... das Deck heute Morgen voll gewesen.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn die Tour ihr Ziel von 50 Buchungen erreicht hätte, wäre das Deck heute Morgen voll gewesen.'::text),
(345832,38426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби тур досяг мети в 50 бронювань, палуба ... сьогодні вранці переповнена.'::text,'була б'::text,'буде'::text,'була'::text,'Якби тур досяг мети в 50 бронювань, палуба була б сьогодні вранці переповнена.'::text),
(345831,38426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la excursión hubiera alcanzado su objetivo de 50 reservas, la cubierta ... abarrotada esta mañana.'::text,'habría estado'::text,'estará'::text,'estaba'::text,'Si la excursión hubiera alcanzado su objetivo de 50 reservas, la cubierta habría estado abarrotada esta mañana.'::text),
(345830,38426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''excursion avait atteint son objectif de 50 réservations, le pont ... bondé ce matin.'::text,'aurait été'::text,'sera'::text,'était'::text,'Si l''excursion avait atteint son objectif de 50 réservations, le pont aurait été bondé ce matin.'::text),
(345833,38426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tur 50 rezervasyon hedefine ulaşsaydı güverte bu sabah kalabalık ...'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Tur 50 rezervasyon hedefine ulaşsaydı güverte bu sabah kalabalık olurdu.'::text),
(345834,38426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a túra elérte volna az 50 foglalásos célt, a fedélzet ma reggel zsúfolt ...'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Ha a túra elérte volna az 50 foglalásos célt, a fedélzet ma reggel zsúfolt lett volna.'::text),
(345837,38427,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre die Person unter Deck geblieben, ... der Eisberg jetzt nicht für sie sichtbar.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Wäre die Person unter Deck geblieben, wäre der Eisberg jetzt nicht für sie sichtbar.'::text),
(345841,38427,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ця особа залишилася під палубою, айсберг ... для неї зараз видимим.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби ця особа залишилася під палубою, айсберг не був би для неї зараз видимим.'::text),
(345840,38427,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el individuo se hubiera quedado bajo cubierta, el iceberg no ... visible para él ahora.'::text,'sería'::text,'habría sido'::text,'será'::text,'Si el individuo se hubiera quedado bajo cubierta, el iceberg no sería visible para él ahora.'::text),
(345839,38427,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''individu était resté sous le pont, l''iceberg ne lui ... pas visible maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si l''individu était resté sous le pont, l''iceberg ne lui serait pas visible maintenant.'::text),
(345842,38427,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birey güvertenin altında kalsaydı buzdağı şu an onun için görünür ...'::text,'olmazdı'::text,'olmazdı'::text,'olmayacak'::text,'Birey güvertenin altında kalsaydı buzdağı şu an onun için görünür olmazdı.'::text),
(345843,38427,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyén a fedélzet alatt maradt volna, a jéghegy most nem ... számára látható.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha az egyén a fedélzet alatt maradt volna, a jéghegy most nem lenne számára látható.'::text),
(345846,38428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Holzdeck soll vor hundert Jahren von Hand gebaut ...'::text,'worden sein'::text,'werden'::text,'seiend'::text,'Das Holzdeck soll vor hundert Jahren von Hand gebaut worden sein.'::text),
(345850,38428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що дерев''яна палуба ... збудована вручну сто років тому.'::text,'була'::text,'бути'::text,'будучи'::text,'Кажуть, що дерев''яна палуба була збудована вручну сто років тому.'::text),
(345849,38428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la cubierta de madera ... construida a mano hace cien años.'::text,'fue'::text,'es'::text,'siendo'::text,'Se dice que la cubierta de madera fue construida a mano hace cien años.'::text),
(345848,38428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le pont en bois ... construit à la main il y a cent ans.'::text,'a été'::text,'est'::text,'étant'::text,'On dit que le pont en bois a été construit à la main il y a cent ans.'::text),
(345851,38428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap güvertenin yüz yıl önce elle ... söyleniyor.'::text,'yapıldığı'::text,'yapıldığı'::text,'yapılarak'::text,'Ahşap güvertenin yüz yıl önce elle yapıldığı söyleniyor.'::text),
(345852,38428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a fa fedélzetet száz évvel ezelőtt kézzel ...'::text,'építették'::text,'építik'::text,'építve'::text,'Azt mondják, a fa fedélzetet száz évvel ezelőtt kézzel építették.'::text),
(345864,38430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Deck ist trocken und sauber, also ... die Crew es vor Sonnenaufgang geputzt haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Das Deck ist trocken und sauber, also muss die Crew es vor Sonnenaufgang geputzt haben.'::text),
(345868,38430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Палуба суха й чиста, тож екіпаж ... її до світанку.'::text,'мабуть, прибрав'::text,'мав прибрати'::text,'не міг прибрати'::text,'Палуба суха й чиста, тож екіпаж мабуть, прибрав її до світанку.'::text),
(345867,38430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cubierta está seca y despejada, así que la tripulación ... antes del amanecer.'::text,'debe de haberla limpiado'::text,'debería haberla limpiado'::text,'no puede haberla limpiado'::text,'La cubierta está seca y despejada, así que la tripulación debe de haberla limpiado antes del amanecer.'::text),
(345866,38430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pont est sec et dégagé, donc l''équipage ... avant le lever du soleil.'::text,'a dû le nettoyer'::text,'aurait dû le nettoyer'::text,'ne peut pas l''avoir nettoyé'::text,'Le pont est sec et dégagé, donc l''équipage a dû le nettoyer avant le lever du soleil.'::text),
(345869,38430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güverte kuru ve temiz, yani mürettebat onu gün doğmadan önce ...'::text,'temizlemiş olmalı'::text,'temizlemeliydi'::text,'temizlemiş olamaz'::text,'Güverte kuru ve temiz, yani mürettebat onu gün doğmadan önce temizlemiş olmalı.'::text),
(345870,38430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fedélzet száraz és tiszta, szóval a legénység ... napfelkelte előtt.'::text,'biztosan feltakarította'::text,'fel kellett volna takarítania'::text,'nem takaríthatta fel'::text,'A fedélzet száraz és tiszta, szóval a legénység biztosan feltakarította napfelkelte előtt.'::text),
(345873,38431,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... einen so furchterregenden Eisberg vom Deck eines Schiffes gesehen!'::text,'habe ich'::text,'ich habe'::text,'sah ich'::text,'Noch nie habe ich einen so furchterregenden Eisberg vom Deck eines Schiffes gesehen!'::text),
(345877,38431,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... такого жахливого айсберга з палуби корабля!'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив такого жахливого айсберга з палуби корабля!'::text),
(345876,38431,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... un iceberg tan aterrador desde la cubierta de un barco!'::text,'he visto'::text,'yo he visto'::text,'vi'::text,'¡Nunca he visto un iceberg tan aterrador desde la cubierta de un barco!'::text),
(345875,38431,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... un iceberg aussi terrifiant depuis le pont d''un navire !'::text,'n''ai-je vu'::text,'je n''ai vu'::text,'je ne vis'::text,'Jamais n''ai-je vu un iceberg aussi terrifiant depuis le pont d''un navire !'::text),
(345878,38431,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir geminin güvertesinden hiç bu kadar korkunç bir buzdağı ...!'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Bir geminin güvertesinden hiç bu kadar korkunç bir buzdağı görmedim!'::text),
(345879,38431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ilyen félelmetes jéghegyet egy hajó fedélzetéről!'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam még ilyen félelmetes jéghegyet egy hajó fedélzetéről!'::text),
(345882,38432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, der Kapitän ... vor dieser Reise anscheinend das ganze Deck lackieren.'::text,'ließ'::text,'ließ'::text,'ließ'::text,'Warte, der Kapitän ließ vor dieser Reise anscheinend das ganze Deck lackieren.'::text),
(345886,38432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, капітан, кажуть, перед цією подорожжю ... залакувати всю палубу.'::text,'звелів'::text,'змусив'::text,'дозволив'::text,'Чекай, капітан, кажуть, перед цією подорожжю звелів залакувати всю палубу.'::text),
(345885,38432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer el capitán ... barnizar toda la cubierta antes de este viaje.'::text,'mandó'::text,'hizo'::text,'dejó'::text,'Espera, al parecer el capitán mandó barnizar toda la cubierta antes de este viaje.'::text),
(345884,38432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment le capitaine ... vernir tout le pont avant ce voyage.'::text,'a fait'::text,'a obligé à'::text,'a laissé'::text,'Attends, apparemment le capitaine a fait vernir tout le pont avant ce voyage.'::text),
(345887,38432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duyduğuma göre kaptan bu yolculuktan önce bütün güverteyi ...'::text,'cilalatmış'::text,'cilalatmış'::text,'cilalamalarına izin vermiş'::text,'Dur, duyduğuma göre kaptan bu yolculuktan önce bütün güverteyi cilalatmış.'::text),
(345888,38432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag a kapitány ... az egész fedélzetet az út előtt.'::text,'lelakkoztatta'::text,'lelakkoztatta'::text,'hagyta lelakkozni'::text,'Várj, állítólag a kapitány lelakkoztatta az egész fedélzetet az út előtt.'::text),
(345891,38433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolles Wetter zum Sonnenbaden, klar. Ich wünschte, dieses Deck ... ein bisschen wärmer.'::text,'wäre'::text,'ist'::text,'wird'::text,'Tolles Wetter zum Sonnenbaden, klar. Ich wünschte, dieses Deck wäre ein bisschen wärmer.'::text),
(345895,38433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова погода для засмаги, звісно. Хотів би я, щоб ця палуба ... трохи теплішою.'::text,'була'::text,'є'::text,'буде'::text,'Чудова погода для засмаги, звісно. Хотів би я, щоб ця палуба була трохи теплішою.'::text),
(345894,38433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiempo perfecto para tomar el sol, obvio. Ojalá esta cubierta ... un poco más cálida.'::text,'fuera'::text,'es'::text,'será'::text,'Tiempo perfecto para tomar el sol, obvio. Ojalá esta cubierta fuera un poco más cálida.'::text),
(345893,38433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Temps idéal pour bronzer, évidemment. J''aimerais que ce pont ... un peu plus chaud.'::text,'soit'::text,'est'::text,'sera'::text,'Temps idéal pour bronzer, évidemment. J''aimerais que ce pont soit un peu plus chaud.'::text),
(345896,38433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneşlenmek için harika hava tabii. Keşke bu güverte biraz daha sıcak ...'::text,'olsa'::text,NULL::text,'olacak'::text,'Güneşlenmek için harika hava tabii. Keşke bu güverte biraz daha sıcak olsa.'::text),
(345897,38433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes idő napozáshoz, persze. Bárcsak ez a fedélzet egy kicsit melegebb ...'::text,'lenne'::text,NULL::text,'lesz'::text,'Tökéletes idő napozáshoz, persze. Bárcsak ez a fedélzet egy kicsit melegebb lenne.'::text),
(345900,38434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieses Deck, ... Planken älter aussehen als mein Opa, ist irgendwie legendär.'::text,'dessen'::text,'das'::text,'das'::text,'Bro, dieses Deck, dessen Planken älter aussehen als mein Opa, ist irgendwie legendär.'::text),
(345904,38434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця палуба, ... дошки виглядають старшими за мого діда, реально легендарна.'::text,'чиї'::text,'яка'::text,'що'::text,'Бро, ця палуба, чиї дошки виглядають старшими за мого діда, реально легендарна.'::text),
(345903,38434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esta cubierta, ... tablas parecen más viejas que mi abuelo, es medio icónica.'::text,'cuyas'::text,'la cual'::text,'que'::text,'Bro, esta cubierta, cuyas tablas parecen más viejas que mi abuelo, es medio icónica.'::text),
(345902,38434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce pont, ... les planches ont l''air plus vieilles que mon grand-père, est grave iconique.'::text,'dont'::text,'lequel'::text,'que'::text,'Frère, ce pont, dont les planches ont l''air plus vieilles que mon grand-père, est grave iconique.'::text),
(345905,38434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tahtaları dedemden yaşlı ... bu güverte resmen efsane.'::text,'görünen'::text,'görünen'::text,'görünen'::text,'Kanka, tahtaları dedemden yaşlı görünen bu güverte resmen efsane.'::text),
(345906,38434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a fedélzet, ... deszkái öregebbnek tűnnek a nagyapámnál, elég ikonikus.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Tesó, ez a fedélzet, amelynek a deszkái öregebbnek tűnnek a nagyapámnál, elég ikonikus.'::text),
(345909,38435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zeitplan-Update: Die Deckcrew ist seit 12 Tagen ...'::text,'auf See'::text,'am Meer'::text,'auf einem Meer'::text,'Zeitplan-Update: Die Deckcrew ist seit 12 Tagen auf See.'::text),
(345913,38435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення графіка: палубна команда вже 12 днів ...'::text,'у морі'::text,'біля моря'::text,'на морі'::text,'Оновлення графіка: палубна команда вже 12 днів у морі.'::text),
(345912,38435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización del calendario: la tripulación de cubierta lleva 12 días ...'::text,'en alta mar'::text,'en el mar'::text,'en un mar'::text,'Actualización del calendario: la tripulación de cubierta lleva 12 días en alta mar.'::text),
(345911,38435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Point planning : l''équipage de pont est ... depuis 12 jours.'::text,'en mer'::text,'à la mer'::text,'sur une mer'::text,'Point planning : l''équipage de pont est en mer depuis 12 jours.'::text),
(345914,38435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takvim güncellemesi: güverte ekibi 12 gündür ...'::text,'denizde'::text,'deniz kenarında'::text,'bir denizde'::text,'Takvim güncellemesi: güverte ekibi 12 gündür denizde.'::text),
(345915,38435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütemterv-frissítés: a fedélzeti személyzet 12 napja ...'::text,'a tengeren van'::text,'a tengerparton van'::text,'egy tengeren van'::text,'Ütemterv-frissítés: a fedélzeti személyzet 12 napja a tengeren van.'::text),
(345918,38436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew hielt die Morgenbesprechung ... der Temperatur von minus 5 Grad auf dem Deck ab.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Die Crew hielt die Morgenbesprechung trotz der Temperatur von minus 5 Grad auf dem Deck ab.'::text),
(345922,38436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екіпаж провів ранкову нараду на палубі ... температуру мінус 5 градусів.'::text,'попри'::text,'хоча'::text,'через'::text,'Екіпаж провів ранкову нараду на палубі попри температуру мінус 5 градусів.'::text),
(345921,38436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tripulación celebró la reunión matutina en la cubierta ... la temperatura de 5 grados bajo cero.'::text,'a pesar de'::text,'aunque'::text,'debido a'::text,'La tripulación celebró la reunión matutina en la cubierta a pesar de la temperatura de 5 grados bajo cero.'::text),
(345920,38436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipage a tenu la réunion du matin sur le pont ... la température de moins 5 degrés.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'L''équipage a tenu la réunion du matin sur le pont malgré la température de moins 5 degrés.'::text),
(345923,38436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mürettebat, eksi 5 derecelik sıcaklığa ... sabah toplantısını güvertede yaptı.'::text,'rağmen'::text,'olsa da'::text,'yüzünden'::text,'Mürettebat, eksi 5 derecelik sıcaklığa rağmen sabah toplantısını güvertede yaptı.'::text),
(345924,38436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legénység a mínusz 5 fokos hőmérséklet ... a fedélzeten tartotta a reggeli megbeszélést.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A legénység a mínusz 5 fokos hőmérséklet ellenére a fedélzeten tartotta a reggeli megbeszélést.'::text),
(381882,42432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn dein Koffer nicht so gut gerollt wäre, ... du den Gang nicht so schnell erreicht.'::text,'hättest'::text,'wirst'::text,'hast'::text,'Ehrlich, wenn dein Koffer nicht so gut gerollt wäre, hättest du den Gang nicht so schnell erreicht.'::text),
(381886,42432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби твоя валіза так добре не котилася, ти ... до переходу так швидко.'::text,'не дістався б'::text,'не дістанешся'::text,'не дістався'::text,'Чесно, якби твоя валіза так добре не котилася, ти не дістався б до переходу так швидко.'::text),
(381885,42432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si tu maleta no hubiera rodado tan bien, no ... a la pasarela tan rápido.'::text,'habrías llegado'::text,'llegarás'::text,'llegaste'::text,'La verdad, si tu maleta no hubiera rodado tan bien, no habrías llegado a la pasarela tan rápido.'::text),
(381884,42432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si ta valise n''avait pas si bien roulé, tu ... à la passerelle aussi vite.'::text,'ne serais pas arrivé'::text,'n''arriveras pas'::text,'n''es pas arrivé'::text,'Franchement, si ta valise n''avait pas si bien roulé, tu ne serais pas arrivé à la passerelle aussi vite.'::text),
(381887,42432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bavulun bu kadar iyi yuvarlanmasaydı geçide bu kadar hızlı ...'::text,'ulaşamazdın'::text,'ulaşamayacaksın'::text,'ulaşamadın'::text,'Açıkçası, bavulun bu kadar iyi yuvarlanmasaydı geçide bu kadar hızlı ulaşamazdın.'::text),
(381888,42432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha a bőröndöd nem gurult volna ilyen jól, nem ... ilyen gyorsan a folyosóhoz.'::text,'értél volna'::text,'fogsz érni'::text,'értél'::text,'Őszintén, ha a bőröndöd nem gurult volna ilyen jól, nem értél volna ilyen gyorsan a folyosóhoz.'::text),
(381891,42433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er einen schwereren Koffer gepackt, ... der Koffer jetzt nicht so leicht neben seinem Skateboard.'::text,'rollte'::text,'wäre gerollt'::text,'wird rollen'::text,'Hätte er einen schwereren Koffer gepackt, rollte der Koffer jetzt nicht so leicht neben seinem Skateboard.'::text),
(381895,42433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він спакував важчу валізу, вона зараз ... поруч зі скейтбордом так легко.'::text,'не котилася б'::text,'не покотилася б'::text,'не котитиметься'::text,'Якби він спакував важчу валізу, вона зараз не котилася б поруч зі скейтбордом так легко.'::text),
(381894,42433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera hecho una maleta más pesada, ahora no ... tan fácilmente junto a su monopatín.'::text,'estaría rodando'::text,'habría rodado'::text,'rodará'::text,'Si hubiera hecho una maleta más pesada, ahora no estaría rodando tan fácilmente junto a su monopatín.'::text),
(381893,42433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait fait une valise plus lourde, elle ne ... pas si facilement à côté de son skateboard maintenant.'::text,'roulerait'::text,'aurait roulé'::text,'roulera'::text,'S''il avait fait une valise plus lourde, elle ne roulerait pas si facilement à côté de son skateboard maintenant.'::text),
(381896,42433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha ağır bir bavul hazırlasaydı bavul şimdi kaykayının yanında bu kadar kolay ...'::text,'yuvarlanmıyor olurdu'::text,'yuvarlanmazdı'::text,'yuvarlanmayacak'::text,'Daha ağır bir bavul hazırlasaydı bavul şimdi kaykayının yanında bu kadar kolay yuvarlanmıyor olurdu.'::text),
(381897,42433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nehezebb bőröndöt pakolt volna, az most nem ... ilyen könnyen a gördeszkája mellett.'::text,'gurulna'::text,'gurult volna'::text,'fog gurulni'::text,'Ha nehezebb bőröndöt pakolt volna, az most nem gurulna ilyen könnyen a gördeszkája mellett.'::text),
(381900,42434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koffer soll den ganzen Weg vom Parkplatz neben ihm her ...'::text,'gerollt sein'::text,'rollen'::text,'rollend'::text,'Der Koffer soll den ganzen Weg vom Parkplatz neben ihm her gerollt sein.'::text),
(381904,42434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, валіза ... поруч із ним усю дорогу від парковки.'::text,'котилася'::text,'котиться'::text,'котячись'::text,'Кажуть, валіза котилася поруч із ним усю дорогу від парковки.'::text),
(381903,42434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la maleta ... a su lado todo el camino desde el aparcamiento.'::text,'rodó'::text,'rueda'::text,'rodando'::text,'Se dice que la maleta rodó a su lado todo el camino desde el aparcamiento.'::text),
(381902,42434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la valise ... à côté de lui depuis le parking.'::text,'a roulé'::text,'roule'::text,'roulant'::text,'On dit que la valise a roulé à côté de lui depuis le parking.'::text),
(381905,42434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavulun otoparktan beri tüm yol boyunca yanında ... söyleniyor.'::text,'yuvarlandığı'::text,'yuvarlandığı'::text,'yuvarlanarak'::text,'Bavulun otoparktan beri tüm yol boyunca yanında yuvarlandığı söyleniyor.'::text),
(381906,42434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a bőrönd végig ... mellette a parkolótól.'::text,'gurult'::text,'gurul'::text,'gurulva'::text,'Azt mondják, a bőrönd végig gurult mellette a parkolótól.'::text),
(381909,42435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er stritt ab, seinen Koffer gegen einen Poller auf dem Dachdeck ...'::text,'gerollt zu haben'::text,'zu rollen'::text,'rollte'::text,'Er stritt ab, seinen Koffer gegen einen Poller auf dem Dachdeck gerollt zu haben.'::text),
(381913,42435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... свою валізу в стовпчик на даху.'::text,'закотив'::text,'закотити'::text,'закотив'::text,'Він заперечив, що закотив свою валізу в стовпчик на даху.'::text),
(381912,42435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... su maleta contra un bolardo de la azotea.'::text,'haber hecho rodar'::text,'hacer rodar'::text,'hizo rodar'::text,'Negó haber hecho rodar su maleta contra un bolardo de la azotea.'::text),
(381911,42435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... sa valise contre une borne sur le toit-terrasse.'::text,'avoir fait rouler'::text,'faire rouler'::text,'a fait rouler'::text,'Il a nié avoir fait rouler sa valise contre une borne sur le toit-terrasse.'::text),
(381914,42435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatı terasında bavulunu bir bariyer direğine ... inkâr etti.'::text,'yuvarladığını'::text,'yuvarlamayı'::text,'yuvarladı'::text,'Çatı terasında bavulunu bir bariyer direğine yuvarladığını inkâr etti.'::text),
(381915,42435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy ... a bőröndjét egy terelőoszlopnak a tetőteraszon.'::text,'nekigurította'::text,'nekigurítani'::text,'nekigurította'::text,'Tagadta, hogy nekigurította a bőröndjét egy terelőoszlopnak a tetőteraszon.'::text),
(381927,42437,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... rollt ein Reisender bei Sonnenuntergang einen Koffer neben einem Skateboard.'::text,''::text,'ist'::text,'hat'::text,'Selten rollt ein Reisender bei Sonnenuntergang einen Koffer neben einem Skateboard.'::text),
(381931,42437,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... мандрівник котить валізу поруч зі скейтбордом на заході сонця.'::text,''::text,'є'::text,'має'::text,'Рідко мандрівник котить валізу поруч зі скейтбордом на заході сонця.'::text),
(381930,42437,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... un viajero hace rodar una maleta junto a un monopatín al atardecer.'::text,''::text,'está'::text,'ha'::text,'Rara vez un viajero hace rodar una maleta junto a un monopatín al atardecer.'::text),
(381929,42437,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un voyageur fait rouler une valise à côté d''un skateboard au coucher du soleil.'::text,''::text,'est'::text,'a'::text,'Rarement un voyageur fait rouler une valise à côté d''un skateboard au coucher du soleil.'::text),
(381932,42437,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... bir yolcu gün batımında kaykayın yanında bavul yuvarlar.'::text,''::text,NULL::text,NULL::text,'Nadiren bir yolcu gün batımında kaykayın yanında bavul yuvarlar.'::text),
(381933,42437,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... egy utazó bőröndöt gurít egy gördeszka mellett naplementekor.'::text,''::text,NULL::text,NULL::text,'Ritkán egy utazó bőröndöt gurít egy gördeszka mellett naplementekor.'::text),
(381936,42438,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, nächstes Mal lässt er seinen Kumpel den Koffer für ihn ..., ohne Witz.'::text,'rollen'::text,'zu rollen'::text,'gerollt'::text,'Bro, nächstes Mal lässt er seinen Kumpel den Koffer für ihn rollen, ohne Witz.'::text),
(381940,42438,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, наступної поїздки він змусить друга ... валізу за нього, чесно.'::text,'котити'::text,'котити'::text,'котив'::text,'Бро, наступної поїздки він змусить друга котити валізу за нього, чесно.'::text),
(381939,42438,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, en el próximo viaje va a hacer que su colega le ... la maleta, sin mentir.'::text,'arrastre'::text,'a arrastrar'::text,'arrastrada'::text,'Bro, en el próximo viaje va a hacer que su colega le arrastre la maleta, sin mentir.'::text),
(381938,42438,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, au prochain voyage, il va faire ... la valise à son pote, sans mentir.'::text,'rouler'::text,'à rouler'::text,'roulée'::text,'Frère, au prochain voyage, il va faire rouler la valise à son pote, sans mentir.'::text),
(381941,42438,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir sonraki yolculukta bavulu kankasına ..., yalan yok.'::text,'yuvarlatacak'::text,'yuvarlatacak'::text,'yuvarlanmış'::text,'Kanka, bir sonraki yolculukta bavulu kankasına yuvarlatacak, yalan yok.'::text),
(381942,42438,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a következő úton a haverjával fogja ... a bőröndöt, komolyan.'::text,'guríttatni'::text,'guríttatni'::text,'gurított'::text,'Tesó, a következő úton a haverjával fogja guríttatni a bőröndöt, komolyan.'::text),
(381945,42439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, sein Koffer ... schneller; Check-in-Schluss ist um 18:40.'::text,'rollte'::text,'wird rollen'::text,'rollt'::text,'Er wünscht sich, sein Koffer rollte schneller; Check-in-Schluss ist um 18:40.'::text),
(381949,42439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб його валіза ... швидше; реєстрація закінчується о 18:40.'::text,'котилася'::text,'котитиметься'::text,'котиться'::text,'Він хоче, щоб його валіза котилася швидше; реєстрація закінчується о 18:40.'::text),
(381948,42439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía que su maleta ... más rápido; el check-in cierra a las 18:40.'::text,'rodara'::text,'rodará'::text,'rueda'::text,'Él desearía que su maleta rodara más rápido; el check-in cierra a las 18:40.'::text),
(381947,42439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que sa valise ... plus vite ; l''enregistrement ferme à 18 h 40.'::text,'roule'::text,'roulera'::text,'roule'::text,'Il aimerait que sa valise roule plus vite ; l''enregistrement ferme à 18 h 40.'::text),
(381950,42439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bavulu daha hızlı ... diye düşünüyor; check-in son saati 18:40.'::text,'yuvarlansa'::text,'yuvarlanacak'::text,'yuvarlanıyor'::text,'Keşke bavulu daha hızlı yuvarlansa diye düşünüyor; check-in son saati 18:40.'::text),
(381951,42439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha a bőröndje gyorsabban ...; a check-in határideje 18:40.'::text,'gurulna'::text,'fog gurulni'::text,'gurul'::text,'Azt szeretné, ha a bőröndje gyorsabban gurulna; a check-in határideje 18:40.'::text),
(381954,42440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koffer, ... Rollen über den Parkplatz rollten, folgte ihm überallhin.'::text,'dessen'::text,'der'::text,'das'::text,'Der Koffer, dessen Rollen über den Parkplatz rollten, folgte ihm überallhin.'::text),
(381958,42440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Валіза, ... коліщата котилися парковкою, всюди за ним їхала.'::text,'чиї'::text,'яка'::text,'що'::text,'Валіза, чиї коліщата котилися парковкою, всюди за ним їхала.'::text),
(381957,42440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maleta, ... ruedas rodaban por el aparcamiento, lo seguía a todas partes.'::text,'cuyas'::text,'la cual'::text,'que'::text,'La maleta, cuyas ruedas rodaban por el aparcamiento, lo seguía a todas partes.'::text),
(381956,42440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La valise, ... les roulettes roulaient sur le parking, le suivait partout.'::text,'dont'::text,'laquelle'::text,'que'::text,'La valise, dont les roulettes roulaient sur le parking, le suivait partout.'::text),
(381959,42440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekerlekleri otoparkta ... bavul onu her yere takip etti.'::text,'yuvarlanan'::text,'yuvarlanan'::text,'yuvarlanan'::text,'Tekerlekleri otoparkta yuvarlanan bavul onu her yere takip etti.'::text),
(381960,42440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bőrönd, ... kerekei végiggurultak a parkolón, mindenhová követte.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A bőrönd, amelynek a kerekei végiggurultak a parkolón, mindenhová követte.'::text),
(381963,42441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koffer rollt ... seiner vier Rollen leicht, wie auf dem Dachdeck beobachtet.'::text,'dank'::text,'trotz'::text,'während'::text,'Der Koffer rollt dank seiner vier Rollen leicht, wie auf dem Dachdeck beobachtet.'::text),
(381967,42441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Валіза легко котиться ... своїм чотирьом коліщатам, як було помічено на даху.'::text,'завдяки'::text,'попри'::text,'тоді як'::text,'Валіза легко котиться завдяки своїм чотирьом коліщатам, як було помічено на даху.'::text),
(381966,42441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maleta rueda con facilidad ... sus cuatro ruedas, como se observó en la azotea.'::text,'gracias a'::text,'a pesar de'::text,'mientras que'::text,'La maleta rueda con facilidad gracias a sus cuatro ruedas, como se observó en la azotea.'::text),
(381965,42441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La valise roule facilement ... ses quatre roulettes, comme observé sur le toit-terrasse.'::text,'grâce à'::text,'malgré'::text,'alors que'::text,'La valise roule facilement grâce à ses quatre roulettes, comme observé sur le toit-terrasse.'::text),
(381968,42441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavul, çatı terasında gözlemlendiği üzere, dört tekerleği ... kolayca yuvarlanıyor.'::text,'sayesinde'::text,'rağmen'::text,'oysa'::text,'Bavul, çatı terasında gözlemlendiği üzere, dört tekerleği sayesinde kolayca yuvarlanıyor.'::text),
(381969,42441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bőrönd a négy kerekének ... könnyen gurul, ahogy a tetőteraszon megfigyelték.'::text,'köszönhetően'::text,'ellenére'::text,'míg'::text,'A bőrönd a négy kerekének köszönhetően könnyen gurul, ahogy a tetőteraszon megfigyelték.'::text),
(381972,42442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wusstest, dass dein Koffer den ganzen Weg neben dir ..., und ehrlich, Respekt.'::text,'rollen würde'::text,'rollen wird'::text,'rollt'::text,'Du wusstest, dass dein Koffer den ganzen Weg neben dir rollen würde, und ehrlich, Respekt.'::text),
(381976,42442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти знав, що твоя валіза ... поруч із тобою всю дорогу, і чесно, респект.'::text,'котитиметься'::text,'котитиметься'::text,'котиться'::text,'Ти знав, що твоя валіза котитиметься поруч із тобою всю дорогу, і чесно, респект.'::text),
(381975,42442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabías que tu maleta ... a tu lado todo el camino, y la verdad, respeto.'::text,'rodaría'::text,'rodará'::text,'rueda'::text,'Sabías que tu maleta rodaría a tu lado todo el camino, y la verdad, respeto.'::text),
(381974,42442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu savais que ta valise ... à côté de toi tout le long, et franchement, respect.'::text,'roulerait'::text,'roulera'::text,'roule'::text,'Tu savais que ta valise roulerait à côté de toi tout le long, et franchement, respect.'::text),
(381977,42442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavulunun tüm yol boyunca yanında ... biliyordun ve açıkçası, saygı.'::text,'yuvarlanacağını'::text,'yuvarlanacağını'::text,'yuvarlandığını'::text,'Bavulunun tüm yol boyunca yanında yuvarlanacağını biliyordun ve açıkçası, saygı.'::text),
(381978,42442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudtad, hogy a bőröndöd végig ... melletted, és őszintén, respekt.'::text,'gurulni fog'::text,'gurulni fog'::text,'gurul'::text,'Tudtad, hogy a bőröndöd végig gurulni fog melletted, és őszintén, respekt.'::text),
(363945,40439,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rote Laterne für 90 Euro ... aus dem Designbudget sein, aber keiner ist sicher.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Die rote Laterne für 90 Euro könnte aus dem Designbudget sein, aber keiner ist sicher.'::text),
(363949,40439,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний ліхтар за 90 євро ... бути з бюджету на дизайн, але ніхто не впевнений.'::text,'може'::text,'мусить'::text,'має'::text,'Червоний ліхтар за 90 євро може бути з бюджету на дизайн, але ніхто не впевнений.'::text),
(363948,40439,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El farol rojo de 90 euros ... ser del presupuesto de diseño, pero nadie está seguro.'::text,'podría'::text,'debe de'::text,'debería'::text,'El farol rojo de 90 euros podría ser del presupuesto de diseño, pero nadie está seguro.'::text),
(363947,40439,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lanterne rouge à 90 euros ... venir du budget déco, mais personne n''en est sûr.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'La lanterne rouge à 90 euros pourrait venir du budget déco, mais personne n''en est sûr.'::text),
(363950,40439,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'90 euroluk kırmızı fener tasarım bütçesinden ..., ama kimse emin değil.'::text,'olabilir'::text,'olmalı'::text,'olmalı'::text,'90 euroluk kırmızı fener tasarım bütçesinden olabilir, ama kimse emin değil.'::text),
(363951,40439,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 90 eurós piros lámpás a dizájnkeretből ..., de senki sem biztos benne.'::text,'származhat'::text,'kell származnia'::text,'kellene származnia'::text,'A 90 eurós piros lámpás a dizájnkeretből származhat, de senki sem biztos benne.'::text),
(363954,40440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die orangefarbene Laterne, ... über dem Bett hängt, hat 45 Euro des Beleuchtungsbudgets verbraucht.'::text,'die'::text,'wer'::text,'wo'::text,'Die orangefarbene Laterne, die über dem Bett hängt, hat 45 Euro des Beleuchtungsbudgets verbraucht.'::text),
(363958,40440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помаранчевий ліхтар, ... висить над ліжком, забрав 45 євро з бюджету на освітлення.'::text,'який'::text,'хто'::text,'де'::text,'Помаранчевий ліхтар, який висить над ліжком, забрав 45 євро з бюджету на освітлення.'::text),
(363957,40440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El farol naranja ... cuelga sobre la cama consumió 45 euros del presupuesto de iluminación.'::text,'que'::text,'quien'::text,'donde'::text,'El farol naranja que cuelga sobre la cama consumió 45 euros del presupuesto de iluminación.'::text),
(363956,40440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lanterne orange ... est suspendue au-dessus du lit a coûté 45 euros du budget éclairage.'::text,'qui'::text,'qui'::text,'où'::text,'La lanterne orange qui est suspendue au-dessus du lit a coûté 45 euros du budget éclairage.'::text),
(363959,40440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yatağın üstünde ... turuncu fener aydınlatma bütçesinden 45 euro yedi.'::text,'asılı duran'::text,'asılı duran'::text,'asılı duran'::text,'Yatağın üstünde asılı duran turuncu fener aydınlatma bütçesinden 45 euro yedi.'::text),
(363960,40440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A narancssárga lámpás, ... az ágy fölött lóg, a világítási keret 45 euróját vitte el.'::text,'amely'::text,'aki'::text,'ahol'::text,'A narancssárga lámpás, amely az ágy fölött lóg, a világítási keret 45 euróját vitte el.'::text),
(363963,40441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Designer sagte, die Laternen ... an jenem Abend bis 18 Uhr für den Kunden brennen.'::text,'würden'::text,'werden'::text,'sind'::text,'Der Designer sagte, die Laternen würden an jenem Abend bis 18 Uhr für den Kunden brennen.'::text),
(363967,40441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дизайнер сказав, що ліхтарі ... увімкнені до 18:00 того вечора для клієнта.'::text,'будуть'::text,'будуть'::text,NULL::text,'Дизайнер сказав, що ліхтарі будуть увімкнені до 18:00 того вечора для клієнта.'::text),
(363966,40441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El diseñador dijo que los faroles ... encendidos a las 18:00 esa tarde para el cliente.'::text,'estarían'::text,'estarán'::text,'están'::text,'El diseñador dijo que los faroles estarían encendidos a las 18:00 esa tarde para el cliente.'::text),
(363965,40441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le designer a dit que les lanternes ... allumées à 18 h ce soir-là pour le client.'::text,'seraient'::text,'seront'::text,'sont'::text,'Le designer a dit que les lanternes seraient allumées à 18 h ce soir-là pour le client.'::text),
(363968,40441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tasarımcı, fenerlerin o akşam müşteri için saat 18:00''e kadar ... söyledi.'::text,'yanmış olacağını'::text,'yanmış olacağını'::text,'yandığını'::text,'Tasarımcı, fenerlerin o akşam müşteri için saat 18:00''e kadar yanmış olacağını söyledi.'::text),
(363969,40441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dizájner azt mondta, a lámpások aznap este 18 órára ... az ügyfélnek.'::text,'égni fognak'::text,'égni fognak'::text,'égnek'::text,'A dizájner azt mondta, a lámpások aznap este 18 órára égni fognak az ügyfélnek.'::text),
(363972,40442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Loft ... nur ein Küchen-Lichtband; die Laternen wurden erst später ergänzt.'::text,'hatte früher'::text,'pflegte zu haben'::text,'war es gewohnt, zu haben'::text,'Das Loft hatte früher nur ein Küchen-Lichtband; die Laternen wurden erst später ergänzt.'::text),
(363976,40442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У лофті ... лише кухонна світлова стрічка; ліхтарі додали згодом.'::text,'колись була'::text,'бувала'::text,'звикли мати'::text,'У лофті колись була лише кухонна світлова стрічка; ліхтарі додали згодом.'::text),
(363975,40442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loft ... tener solo una tira de luz en la cocina; los faroles se añadieron posteriormente.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El loft solía tener solo una tira de luz en la cocina; los faroles se añadieron posteriormente.'::text),
(363974,40442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le loft ... qu''une bande lumineuse dans la cuisine ; les lanternes ont été ajoutées par la suite.'::text,'n''avait autrefois'::text,'n''avait'::text,'était habitué à n''avoir'::text,'Le loft n''avait autrefois qu''une bande lumineuse dans la cuisine ; les lanternes ont été ajoutées par la suite.'::text),
(363977,40442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Loftta eskiden yalnızca bir mutfak şerit ışığı ...; fenerler sonradan eklendi.'::text,'vardı'::text,'olurdu'::text,'alışkındı'::text,'Loftta eskiden yalnızca bir mutfak şerit ışığı vardı; fenerler sonradan eklendi.'::text),
(363978,40442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A loftban régen csak egy konyhai fénycsík ...; a lámpásokat utólag tették fel.'::text,'volt'::text,'szokott lenni'::text,'volt megszokva'::text,'A loftban régen csak egy konyhai fénycsík volt; a lámpásokat utólag tették fel.'::text),
(363981,40443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich vermied der Bewohner ... der Papierlaternen in der Nähe der Kerzen.'::text,'das Aufstellen'::text,'aufzustellen'::text,'aufstellen'::text,'Offensichtlich vermied der Bewohner das Aufstellen der Papierlaternen in der Nähe der Kerzen.'::text),
(363985,40443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, мешканець уникав ... паперових ліхтарів біля свічок.'::text,'розміщення'::text,'розмістити'::text,'розмістити'::text,'Очевидно, мешканець уникав розміщення паперових ліхтарів біля свічок.'::text),
(363984,40443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evidentemente, el ocupante evitó ... los faroles de papel cerca de las velas.'::text,'colocar'::text,'colocar'::text,'colocar'::text,'Evidentemente, el ocupante evitó colocar los faroles de papel cerca de las velas.'::text),
(363983,40443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement, l''occupant a évité ... les lanternes en papier près des bougies.'::text,'de placer'::text,'placer'::text,'placer'::text,'Visiblement, l''occupant a évité de placer les lanternes en papier près des bougies.'::text),
(363986,40443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki oturan kişi kâğıt fenerleri mumların yanına ... kaçındı.'::text,'koymaktan'::text,'koymaktan'::text,'koymaktan'::text,'Belli ki oturan kişi kâğıt fenerleri mumların yanına koymaktan kaçındı.'::text),
(363987,40443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan a lakó kerülte, hogy a papírlámpásokat a gyertyák közelébe ...'::text,'tegye'::text,'tenni'::text,'tesz'::text,'Nyilvánvalóan a lakó kerülte, hogy a papírlámpásokat a gyertyák közelébe tegye.'::text),
(363990,40444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rote Laterne leuchtet neben dem Fenster, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die rote Laterne leuchtet neben dem Fenster, oder?'::text),
(363994,40444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний ліхтар світиться біля вікна, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Червоний ліхтар світиться біля вікна, правда?'::text),
(363993,40444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El farol rojo brilla junto a la ventana, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'El farol rojo brilla junto a la ventana, ¿verdad?'::text),
(363992,40444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lanterne rouge brille près de la fenêtre, ... ?'::text,'hein'::text,'hein'::text,'hein'::text,'La lanterne rouge brille près de la fenêtre, hein ?'::text),
(363995,40444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı fener pencerenin yanında parlıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kırmızı fener pencerenin yanında parlıyor, değil mi?'::text),
(363996,40444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros lámpás ott világít az ablak mellett, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A piros lámpás ott világít az ablak mellett, ugye?'::text),
(363999,40445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die rote Laterne ist rund, weil sie nicht eckig ist, und die orangefarbene ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Die rote Laterne ist rund, weil sie nicht eckig ist, und die orangefarbene auch.'::text),
(364003,40445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний ліхтар круглий, бо він не квадратний, і помаранчевий ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Червоний ліхтар круглий, бо він не квадратний, і помаранчевий теж.'::text),
(364002,40445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El farol rojo es redondo porque no es cuadrado, y el naranja ...'::text,'también'::text,'también'::text,'tampoco'::text,'El farol rojo es redondo porque no es cuadrado, y el naranja también.'::text),
(364001,40445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lanterne rouge est ronde parce qu''elle n''est pas carrée, et l''orange ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'La lanterne rouge est ronde parce qu''elle n''est pas carrée, et l''orange aussi.'::text),
(364004,40445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı fener kare olmadığı için yuvarlak, turuncu olan da ...'::text,'öyle'::text,'öyle'::text,'değil'::text,'Kırmızı fener kare olmadığı için yuvarlak, turuncu olan da öyle.'::text),
(364005,40445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros lámpás kerek, mert nem szögletes, és a narancssárga ...'::text,'is'::text,'is'::text,'sem'::text,'A piros lámpás kerek, mert nem szögletes, és a narancssárga is.'::text),
(364017,40447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Einbruch der Dunkelheit wird jemand jede Laterne und jede Lichterkette im Loft ...'::text,'eingeschaltet haben'::text,'einschalten'::text,'einschaltet'::text,'Bis zum Einbruch der Dunkelheit wird jemand jede Laterne und jede Lichterkette im Loft eingeschaltet haben.'::text),
(364021,40447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До настання темряви хтось уже ... кожен ліхтар і кожну гірлянду в лофті.'::text,'увімкне'::text,'увімкне'::text,'вмикає'::text,'До настання темряви хтось уже увімкне кожен ліхтар і кожну гірлянду в лофті.'::text),
(364020,40447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando anochezca, alguien ya ... todos los faroles y guirnaldas de luces del loft.'::text,'habrá encendido'::text,'encenderá'::text,'enciende'::text,'Para cuando anochezca, alguien ya habrá encendido todos los faroles y guirnaldas de luces del loft.'::text),
(364019,40447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la tombée de la nuit, quelqu''un ... chaque lanterne et chaque guirlande lumineuse du loft.'::text,'aura allumé'::text,'allumera'::text,'allume'::text,'D''ici la tombée de la nuit, quelqu''un aura allumé chaque lanterne et chaque guirlande lumineuse du loft.'::text),
(364022,40447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava kararana kadar biri loftaki her feneri ve ışık zincirini ...'::text,'yakmış olacak'::text,'yakacak'::text,'yakıyor'::text,'Hava kararana kadar biri loftaki her feneri ve ışık zincirini yakmış olacak.'::text),
(364023,40447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire besötétedik, valaki már ... a loft összes lámpását és fényfüzérét.'::text,'felkapcsolta'::text,'fel fogja kapcsolni'::text,'felkapcsolja'::text,'Mire besötétedik, valaki már felkapcsolta a loft összes lámpását és fényfüzérét.'::text),
(364026,40448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht wird die rote Laterne schon sechs Stunden neben dem Fenster ...'::text,'geleuchtet haben'::text,'leuchten'::text,'leuchten'::text,'Um Mitternacht wird die rote Laterne schon sechs Stunden neben dem Fenster geleuchtet haben.'::text),
(364030,40448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівночі червоний ліхтар ... біля вікна вже шість годин.'::text,'світитиме'::text,'світитиме'::text,'світитиме'::text,'Опівночі червоний ліхтар світитиме біля вікна вже шість годин.'::text),
(364029,40448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A medianoche, el farol rojo ... junto a la ventana durante seis horas.'::text,'habrá estado brillando'::text,'estará brillando'::text,'brillará'::text,'A medianoche, el farol rojo habrá estado brillando junto a la ventana durante seis horas.'::text),
(364028,40448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, la lanterne rouge ... près de la fenêtre pendant six heures.'::text,'aura brillé'::text,'sera en train de briller'::text,'brillera'::text,'À minuit, la lanterne rouge aura brillé près de la fenêtre pendant six heures.'::text),
(364031,40448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısı olduğunda kırmızı fener altı saattir pencerenin yanında ...'::text,'parlıyor olacak'::text,'parlıyor olacak'::text,'parlayacak'::text,'Gece yarısı olduğunda kırmızı fener altı saattir pencerenin yanında parlıyor olacak.'::text),
(364032,40448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélkor a piros lámpás már hat órája ... az ablak mellett.'::text,'fog világítani'::text,'fog világítani'::text,'világít majd'::text,'Éjfélkor a piros lámpás már hat órája fog világítani az ablak mellett.'::text),
(381153,42351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Welpe in seinem pinken Schwimmring ..., hat der Pitbull den Pool übernommen. Verrat!'::text,'trieb'::text,'trieb'::text,'ist getrieben'::text,'Während der Welpe in seinem pinken Schwimmring trieb, hat der Pitbull den Pool übernommen. Verrat!'::text),
(381157,42351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки цуценя ... у своєму рожевому колі, пітбуль захопив басейн. Зрада!'::text,'плавало'::text,'поплавало'::text,'поплавало'::text,'Поки цуценя плавало у своєму рожевому колі, пітбуль захопив басейн. Зрада!'::text),
(381156,42351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el cachorro ... en su flotador rosa, el pitbull se adueñó de la piscina. ¡Traición!'::text,'flotaba'::text,'flotó'::text,'ha flotado'::text,'Mientras el cachorro flotaba en su flotador rosa, el pitbull se adueñó de la piscina. ¡Traición!'::text),
(381155,42351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le chiot ... dans sa bouée rose, le pitbull a pris le contrôle de la piscine. Trahison !'::text,'flottait'::text,'a flotté'::text,'a flotté'::text,'Pendant que le chiot flottait dans sa bouée rose, le pitbull a pris le contrôle de la piscine. Trahison !'::text),
(381158,42351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru köpek pembe simidinde ... pitbull havuzu ele geçirdi. İhanet!'::text,'süzülürken'::text,'süzüldü'::text,'süzüldü'::text,'Yavru köpek pembe simidinde süzülürken pitbull havuzu ele geçirdi. İhanet!'::text),
(381159,42351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg a kiskutya a rózsaszín úszógumijában ..., a pitbull elfoglalta a medencét. Árulás!'::text,'lebegett'::text,'lebegett'::text,'lebegett'::text,'Amíg a kiskutya a rózsaszín úszógumijában lebegett, a pitbull elfoglalta a medencét. Árulás!'::text),
(381162,42352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Welpe ... seit einer Stunde im pinken Schwimmring und weigert sich rauszugehen. Katastrophe!'::text,'treibt'::text,'treibt'::text,'treibt'::text,'Dieser Welpe treibt seit einer Stunde im pinken Schwimmring und weigert sich rauszugehen. Katastrophe!'::text),
(381166,42352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це цуценя ... в рожевому колі вже годину й відмовляється вилазити. Катастрофа!'::text,'плаває'::text,'плаває'::text,'плаває'::text,'Це цуценя плаває в рожевому колі вже годину й відмовляється вилазити. Катастрофа!'::text),
(381165,42352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este cachorro ... en el flotador rosa desde hace una hora y se niega a salir. ¡Desastre!'::text,'flota'::text,'está flotando'::text,'flota'::text,'Este cachorro flota en el flotador rosa desde hace una hora y se niega a salir. ¡Desastre!'::text),
(381164,42352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce chiot ... dans la bouée rose depuis une heure et refuse d''en sortir. La cata !'::text,'flotte'::text,'flotte'::text,'flotte'::text,'Ce chiot flotte dans la bouée rose depuis une heure et refuse d''en sortir. La cata !'::text),
(381167,42352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yavru köpek bir saattir pembe simitte ... ve çıkmayı reddediyor. Felaket!'::text,'süzülüyor'::text,'süzülüyor'::text,'süzülür'::text,'Bu yavru köpek bir saattir pembe simitte süzülüyor ve çıkmayı reddediyor. Felaket!'::text),
(381168,42352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a kiskutya már egy órája ... a rózsaszín úszógumiban, és nem hajlandó kijönni. Katasztrófa!'::text,'lebeg'::text,'lebeg'::text,'lebeg'::text,'Ez a kiskutya már egy órája lebeg a rózsaszín úszógumiban, és nem hajlandó kijönni. Katasztrófa!'::text),
(381171,42353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe ... gerade in seinem Schwimmring, als der Pitbull vorbeitrieb. Der Horror!'::text,'döste'::text,'döste'::text,'hat gedöst'::text,'Der Welpe döste gerade in seinem Schwimmring, als der Pitbull vorbeitrieb. Der Horror!'::text),
(381175,42353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя ... у своєму колі, коли повз пропливав пітбуль. Жах!'::text,'дрімало'::text,'задрімало'::text,'задрімало'::text,'Цуценя дрімало у своєму колі, коли повз пропливав пітбуль. Жах!'::text),
