(381176,42353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pitbull yanından süzülüp geçtiğinde yavru köpek simidinde ...! Dehşet!'::text,'uyukluyordu'::text,'uyukladı'::text,'uyukladı'::text,'Pitbull yanından süzülüp geçtiğinde yavru köpek simidinde uyukluyordu! Dehşet!'::text),
(381177,42353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya éppen ... az úszógumijában, amikor a pitbull elúszott mellette. Borzalom!'::text,'szundikált'::text,'elszundított'::text,'elszundított'::text,'A kiskutya éppen szundikált az úszógumijában, amikor a pitbull elúszott mellette. Borzalom!'::text),
(381180,42354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... der Welpe heute dreimal in diesem pinken Schwimmring eingeschlafen.'::text,'ist'::text,'ist'::text,'schlief'::text,'Bestie, anscheinend ist der Welpe heute dreimal in diesem pinken Schwimmring eingeschlafen.'::text),
(381184,42354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, цуценя сьогодні вже тричі ... в тому рожевому колі.'::text,'заснуло'::text,'засинало'::text,'заснуло'::text,'Подруго, кажуть, цуценя сьогодні вже тричі заснуло в тому рожевому колі.'::text),
