(381185,42354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre yavru köpek bugün o pembe simitte üç kez ...'::text,'uyuyakalmış'::text,'uyuyakalıyormuş'::text,'uyuyakaldı'::text,'Kanka, duyduğuma göre yavru köpek bugün o pembe simitte üç kez uyuyakalmış.'::text),
