(381200,42356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chiot glisse hors de la bouée rose, l''homme le ... avec sa serviette.'::text,'sortira'::text,'sortirait'::text,'sortit'::text,'Si le chiot glisse hors de la bouée rose, l''homme le sortira avec sa serviette.'::text),
(381203,42356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru köpek pembe simitten kayarsa adam onu havlusuyla ...'::text,'çıkaracak'::text,'çıkarırdı'::text,'çıkardı'::text,'Yavru köpek pembe simitten kayarsa adam onu havlusuyla çıkaracak.'::text),
