(381225,42359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Pitbull in einem roten Schwimmring am Welpen vorbei.'::text,'treibt'::text,'treibt'::text,'ist getrieben'::text,'Gerade treibt der Pitbull in einem roten Schwimmring am Welpen vorbei.'::text),
(381229,42359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз пітбуль ... повз цуценя в червоному колі.'::text,'пропливає'::text,'пропливає'::text,'проплив'::text,'Саме зараз пітбуль пропливає повз цуценя в червоному колі.'::text),
(381228,42359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, el pitbull ... junto al cachorro en un flotador rojo.'::text,'está pasando'::text,'pasa'::text,'ha pasado'::text,'Ahora mismo, el pitbull está pasando junto al cachorro en un flotador rojo.'::text),
(381227,42359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le pitbull ... devant le chiot dans une bouée rouge.'::text,'dérive'::text,'dérive'::text,'a dérivé'::text,'En ce moment, le pitbull dérive devant le chiot dans une bouée rouge.'::text),
(381230,42359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda pitbull kırmızı bir simitle yavru köpeğin yanından ...'::text,'süzülüp geçiyor'::text,'süzülüp geçer'::text,'süzülüp geçti'::text,'Şu anda pitbull kırmızı bir simitle yavru köpeğin yanından süzülüp geçiyor.'::text),
(381231,42359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a pitbull egy piros úszógumiban ... el a kiskutya mellett.'::text,'sodródik'::text,'sodródik'::text,'sodródott'::text,'Épp most a pitbull egy piros úszógumiban sodródik el a kiskutya mellett.'::text),
(381243,42361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird das Exemplar etwa drei Stunden im pinken Schwimmring ...'::text,'getrieben sein'::text,'treiben'::text,'treibt'::text,'Bis Sonnenuntergang wird das Exemplar etwa drei Stunden im pinken Schwimmring getrieben sein.'::text),
(381247,42361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця особина ... в рожевому колі приблизно три години.'::text,'пробуде'::text,'плаватиме'::text,'плаває'::text,'До заходу сонця особина пробуде в рожевому колі приблизно три години.'::text),
(381246,42361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, el ejemplar ... en el flotador rosa unas tres horas.'::text,'habrá flotado'::text,'flotará'::text,'está flotando'::text,'Para el atardecer, el ejemplar habrá flotado en el flotador rosa unas tres horas.'::text),
(381245,42361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, le spécimen ... dans la bouée rose pendant environ trois heures.'::text,'aura flotté'::text,'flottera'::text,'flotte'::text,'D''ici le coucher du soleil, le spécimen aura flotté dans la bouée rose pendant environ trois heures.'::text),
(381248,42361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar örnek pembe simitte yaklaşık üç saat ...'::text,'süzülmüş olacak'::text,'süzülecek'::text,'süzülüyor'::text,'Gün batımına kadar örnek pembe simitte yaklaşık üç saat süzülmüş olacak.'::text),
(381249,42361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementéig a példány körülbelül három órát ... a rózsaszín úszógumiban.'::text,'fog lebegni'::text,'lebeg majd'::text,'lebeg'::text,'Naplementéig a példány körülbelül három órát fog lebegni a rózsaszín úszógumiban.'::text),
(339672,37742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, das Kätzchen ... den Ball gerade um den Turm, als ich auf Aufnahme gedrückt hab, echt jetzt.'::text,'jagte'::text,'jagte'::text,'hat gejagt'::text,'Digga, das Kätzchen jagte den Ball gerade um den Turm, als ich auf Aufnahme gedrückt hab, echt jetzt.'::text),
(339676,37742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, кошеня ... м''ячик навколо вежі, коли я ввімкнув запис, чесно.'::text,'ганяло'::text,'погнало'::text,'погнало'::text,'Бро, кошеня ганяло м''ячик навколо вежі, коли я ввімкнув запис, чесно.'::text),
(339675,37742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el gatito ... la pelota alrededor de la torre cuando le di a grabar, en serio.'::text,'estaba persiguiendo'::text,'persiguió'::text,'ha perseguido'::text,'Tío, el gatito estaba persiguiendo la pelota alrededor de la torre cuando le di a grabar, en serio.'::text),
(339674,37742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le chaton ... la balle autour de la tour quand j''ai lancé l''enregistrement, sérieux.'::text,'pourchassait'::text,'a pourchassé'::text,'a pourchassé'::text,'Mec, le chaton pourchassait la balle autour de la tour quand j''ai lancé l''enregistrement, sérieux.'::text),
(339677,37742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kayda bastığımda kedi yavrusu topu kulenin etrafında ..., cidden.'::text,'kovalıyordu'::text,'kovaladı'::text,'kovaladı'::text,'Kanka, kayda bastığımda kedi yavrusu topu kulenin etrafında kovalıyordu, cidden.'::text),
(339678,37742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a cica éppen ... a labdát a torony körül, amikor elindítottam a felvételt, komolyan.'::text,'kergette'::text,'megkergette'::text,'megkergette'::text,'Tesó, a cica éppen kergette a labdát a torony körül, amikor elindítottam a felvételt, komolyan.'::text),
(339681,37743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kätzchen ... den grünen Ball seit zehn Minuten um den Turm.'::text,'jagt'::text,'jagt'::text,'jagt'::text,'Das Kätzchen jagt den grünen Ball seit zehn Minuten um den Turm.'::text),
(339685,37743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошеня ... зелений м''ячик навколо вежі вже десять хвилин.'::text,'ганяє'::text,'ганяє'::text,'ганяє'::text,'Кошеня ганяє зелений м''ячик навколо вежі вже десять хвилин.'::text),
(339684,37743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gatito ... la pelota verde alrededor de la torre desde hace diez minutos.'::text,'persigue'::text,'está persiguiendo'::text,'persigue'::text,'El gatito persigue la pelota verde alrededor de la torre desde hace diez minutos.'::text),
(339683,37743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaton ... la balle verte autour de la tour depuis dix minutes.'::text,'pourchasse'::text,'pourchasse'::text,'pourchasse'::text,'Le chaton pourchasse la balle verte autour de la tour depuis dix minutes.'::text),
(339686,37743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi yavrusu on dakikadır yeşil topu kulenin etrafında ...'::text,'kovalıyor'::text,'kovalıyor'::text,'kovalar'::text,'Kedi yavrusu on dakikadır yeşil topu kulenin etrafında kovalıyor.'::text),
(339687,37743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cica már tíz perce ... a zöld labdát a torony körül.'::text,'kergeti'::text,'kergeti'::text,'kergeti'::text,'A cica már tíz perce kergeti a zöld labdát a torony körül.'::text),
(339690,37744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kätzchen ... den Ball bis nach unten und streckte sich dann zur oberen Rampe.'::text,'jagte'::text,'jagte gerade'::text,'hat gejagt'::text,'Das Kätzchen jagte den Ball bis nach unten und streckte sich dann zur oberen Rampe.'::text),
(339694,37744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошеня ... м''ячик аж донизу, а потім потягнулося до верхньої рампи.'::text,'погнало'::text,'ганяло'::text,'погнало'::text,'Кошеня погнало м''ячик аж донизу, а потім потягнулося до верхньої рампи.'::text),
(339693,37744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gatito ... la pelota hasta abajo y luego se estiró hacia la rampa de arriba.'::text,'persiguió'::text,'estaba persiguiendo'::text,'ha perseguido'::text,'El gatito persiguió la pelota hasta abajo y luego se estiró hacia la rampa de arriba.'::text),
(339692,37744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaton ... la balle jusqu''en bas, puis s''est étiré vers la rampe du haut.'::text,'a pourchassé'::text,'pourchassait'::text,'a pourchassé'::text,'Le chaton a pourchassé la balle jusqu''en bas, puis s''est étiré vers la rampe du haut.'::text),
(339695,37744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi yavrusu topu ta aşağıya kadar ..., sonra üst rampaya uzandı.'::text,'kovaladı'::text,'kovalıyordu'::text,'kovaladı'::text,'Kedi yavrusu topu ta aşağıya kadar kovaladı, sonra üst rampaya uzandı.'::text),
(339696,37744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cica egészen az aljáig ... a labdát, aztán felnyúlt a felső rámpához.'::text,'kergette'::text,'kergette éppen'::text,'kergette'::text,'A cica egészen az aljáig kergette a labdát, aztán felnyúlt a felső rámpához.'::text),
(339699,37745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kätzchen ... den Ball seit dem Frühstück dreimal den Turm hinuntergejagt.'::text,'hat'::text,'hat'::text,'jagte'::text,'Das Kätzchen hat den Ball seit dem Frühstück dreimal den Turm hinuntergejagt.'::text),
(339703,37745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кошеня від сніданку вже тричі ... м''ячик вниз по вежі.'::text,'прогнало'::text,'ганяло'::text,'прогнало'::text,'Кошеня від сніданку вже тричі прогнало м''ячик вниз по вежі.'::text),
(339702,37745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gatito ... la pelota torre abajo tres veces desde el desayuno.'::text,'ha perseguido'::text,'ha estado persiguiendo'::text,'persiguió'::text,'El gatito ha perseguido la pelota torre abajo tres veces desde el desayuno.'::text),
(339701,37745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaton ... la balle le long de la tour trois fois depuis le petit-déjeuner.'::text,'a pourchassé'::text,'pourchasse'::text,'pourchassa'::text,'Le chaton a pourchassé la balle le long de la tour trois fois depuis le petit-déjeuner.'::text),
(339704,37745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kedi yavrusu kahvaltıdan beri topu kulenin aşağısına üç kez ...'::text,'kovaladı'::text,'kovalıyor'::text,'kovaladı'::text,'Kedi yavrusu kahvaltıdan beri topu kulenin aşağısına üç kez kovaladı.'::text),
(339705,37745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A cica reggeli óta háromszor ... le a labdát a tornyon.'::text,'kergette'::text,'kergette'::text,'kergette'::text,'A cica reggeli óta háromszor kergette le a labdát a tornyon.'::text),
(339708,37746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Ball die Schale erreichte, ... das Jungtier ihn um den ganzen Turm gejagt.'::text,'hatte'::text,'hat'::text,'jagt'::text,'Als der Ball die Schale erreichte, hatte das Jungtier ihn um den ganzen Turm gejagt.'::text),
(339712,37746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли м''ячик дістався лотка, дитинча вже ... його навколо всієї вежі.'::text,'прогнало'::text,'прогнало'::text,'ганяє'::text,'Коли м''ячик дістався лотка, дитинча вже прогнало його навколо всієї вежі.'::text),
(339711,37746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la pelota llegó a la bandeja, el ejemplar joven ya la ... alrededor de toda la torre.'::text,'había perseguido'::text,'ha perseguido'::text,'persigue'::text,'Cuando la pelota llegó a la bandeja, el ejemplar joven ya la había perseguido alrededor de toda la torre.'::text),
(339710,37746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la balle a atteint le plateau, le jeune spécimen ... autour de toute la tour.'::text,'l''avait pourchassée'::text,'l''a pourchassée'::text,'la pourchasse'::text,'Quand la balle a atteint le plateau, le jeune spécimen l''avait pourchassée autour de toute la tour.'::text),
(339713,37746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Top tepsiye ulaştığında yavru onu bütün kulenin etrafında ...'::text,'kovalamıştı'::text,'kovaladı'::text,'kovalıyor'::text,'Top tepsiye ulaştığında yavru onu bütün kulenin etrafında kovalamıştı.'::text),
(339714,37746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a labda elérte a tálcát, a fiatal egyed ... az egész torony körül.'::text,'már végigkergette'::text,'végigkergette'::text,'kergeti'::text,'Mire a labda elérte a tálcát, a fiatal egyed már végigkergette az egész torony körül.'::text),
(339717,37747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich der Ball bewegt, ... das Kätzchen ihm nach, weil der Ball nicht stillsteht.'::text,'jagt'::text,'würde jagen'::text,'jagte'::text,'Wenn sich der Ball bewegt, jagt das Kätzchen ihm nach, weil der Ball nicht stillsteht.'::text),
(339721,37747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо м''ячик поворухнеться, кошеня ... за ним, бо м''ячик не стоїть на місці.'::text,'поженеться'::text,'погналося б'::text,'погналося'::text,'Якщо м''ячик поворухнеться, кошеня поженеться за ним, бо м''ячик не стоїть на місці.'::text),
(339720,37747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pelota se mueve, el gatito la ..., porque la pelota no está quieta.'::text,'perseguirá'::text,'perseguiría'::text,'persiguió'::text,'Si la pelota se mueve, el gatito la perseguirá, porque la pelota no está quieta.'::text),
(339719,37747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la balle bouge, le chaton la ..., parce que la balle ne reste pas immobile.'::text,'pourchassera'::text,'pourchasserait'::text,'pourchassa'::text,'Si la balle bouge, le chaton la pourchassera, parce que la balle ne reste pas immobile.'::text),
(339722,37747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Top hareket ederse kedi yavrusu onu ..., çünkü top yerinde durmuyor.'::text,'kovalayacak'::text,'kovalardı'::text,'kovaladı'::text,'Top hareket ederse kedi yavrusu onu kovalayacak, çünkü top yerinde durmuyor.'::text),
(339723,37747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a labda megmozdul, a cica ..., mert a labda nem áll egy helyben.'::text,'kergetni fogja'::text,'kergetné'::text,'kergette'::text,'Ha a labda megmozdul, a cica kergetni fogja, mert a labda nem áll egy helyben.'::text),
(339735,37749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, sie hat mir gesagt, sie wusste, dass das Kätzchen dem Ball ..., sobald er losrollt.'::text,'nachjagen würde'::text,'nachjagen wird'::text,'nachjagt'::text,'Süße, sie hat mir gesagt, sie wusste, dass das Kätzchen dem Ball nachjagen würde, sobald er losrollt.'::text),
(339739,37749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що знала: кошеня ... за тим м''ячиком, щойно він покотиться.'::text,'поженеться'::text,'поженеться'::text,'жене'::text,'Подруго, вона сказала, що знала: кошеня поженеться за тим м''ячиком, щойно він покотиться.'::text),
(339738,37749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que sabía que el gatito ... esa pelota en cuanto empezara a rodar.'::text,'perseguiría'::text,'perseguirá'::text,'está persiguiendo'::text,'Amiga, me dijo que sabía que el gatito perseguiría esa pelota en cuanto empezara a rodar.'::text),
(339737,37749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''elle savait que le chaton ... cette balle dès qu''elle commencerait à rouler.'::text,'pourchasserait'::text,'pourchassera'::text,'pourchasse'::text,'Ma belle, elle m''a dit qu''elle savait que le chaton pourchasserait cette balle dès qu''elle commencerait à rouler.'::text),
(339740,37749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana kedi yavrusunun o topu yuvarlanmaya başladığı an ... bildiğini söyledi.'::text,'kovalayacağını'::text,'kovalayacağını'::text,'kovaladığını'::text,'Kızım, bana kedi yavrusunun o topu yuvarlanmaya başladığı an kovalayacağını bildiğini söyledi.'::text),
(339741,37749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, tudta, hogy a cica ... azt a labdát, amint gurulni kezd.'::text,'kergetni fogja'::text,'kergetni fogja'::text,'kergeti'::text,'Csajszi, azt mondta, tudta, hogy a cica kergetni fogja azt a labdát, amint gurulni kezd.'::text),
(339744,37750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... dieses Kätzchen den grünen Ball jeden einzelnen Morgen.'::text,'jagt'::text,'jagt gerade'::text,'hat gejagt'::text,'Hör zu, anscheinend jagt dieses Kätzchen den grünen Ball jeden einzelnen Morgen.'::text),
(339748,37750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, це кошеня ... зелений м''ячик кожного ранку.'::text,'ганяє'::text,'ганяє'::text,'ганяло'::text,'Слухай, кажуть, це кошеня ганяє зелений м''ячик кожного ранку.'::text),
(339747,37750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer este gatito ... la pelota verde todas las mañanas sin falta.'::text,'persigue'::text,'está persiguiendo'::text,'ha perseguido'::text,'Oye, al parecer este gatito persigue la pelota verde todas las mañanas sin falta.'::text),
(339746,37750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment ce chaton ... la balle verte tous les matins sans exception.'::text,'pourchasse'::text,'est en train de pourchasser'::text,'a pourchassé'::text,'Écoute, apparemment ce chaton pourchasse la balle verte tous les matins sans exception.'::text),
(339749,37750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre bu kedi yavrusu her sabah istisnasız yeşil topu ...'::text,'kovalar'::text,'kovalıyor'::text,'kovaladı'::text,'Dinle, duyduğuma göre bu kedi yavrusu her sabah istisnasız yeşil topu kovalar.'::text),
(339750,37750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ez a cica minden egyes reggel ... a zöld labdát.'::text,'kergeti'::text,'kergeti'::text,'kergette'::text,'Figyelj, állítólag ez a cica minden egyes reggel kergeti a zöld labdát.'::text),
(339762,37752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abendessen wird das Kätzchen denselben Ball hundertmal ...! Wirklich spannend.'::text,'gejagt haben'::text,'jagen'::text,'jagt'::text,'Bis zum Abendessen wird das Kätzchen denselben Ball hundertmal gejagt haben! Wirklich spannend.'::text),
(339766,37752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечері кошеня ... той самий м''ячик уже сто разів. Просто неймовірно захопливо.'::text,'устигне поганяти'::text,'ганятиме'::text,'ганяє'::text,'До вечері кошеня устигне поганяти той самий м''ячик уже сто разів. Просто неймовірно захопливо.'::text),
(339765,37752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la cena, el gatito ... la misma pelota cien veces. Emocionante de verdad.'::text,'habrá perseguido'::text,'perseguirá'::text,'persigue'::text,'Para la cena, el gatito habrá perseguido la misma pelota cien veces. Emocionante de verdad.'::text),
(339764,37752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le dîner, le chaton ... la même balle cent fois. Vraiment palpitant.'::text,'aura pourchassé'::text,'pourchassera'::text,'pourchasse'::text,'D''ici le dîner, le chaton aura pourchassé la même balle cent fois. Vraiment palpitant.'::text),
(339767,37752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeğine kadar kedi yavrusu aynı topu yüz kez ...! Gerçekten heyecan verici.'::text,'kovalamış olacak'::text,'kovalayacak'::text,'kovalıyor'::text,'Akşam yemeğine kadar kedi yavrusu aynı topu yüz kez kovalamış olacak! Gerçekten heyecan verici.'::text),
(339768,37752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacsoráig a cica már százszor ... ugyanazt a labdát. Tényleg izgalmas.'::text,'megkergeti'::text,'kergetni fogja'::text,'kergeti'::text,'Vacsoráig a cica már százszor megkergeti ugyanazt a labdát. Tényleg izgalmas.'::text),
(373854,41540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Koch den Kuchen versteckt hätte, ... die Kuh keinen einzigen Krümel abbekommen.'::text,'hätte'::text,'wird'::text,'bekam'::text,'Wenn der Koch den Kuchen versteckt hätte, hätte die Kuh keinen einzigen Krümel abbekommen.'::text),
(373858,41540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кухар сховав пиріг, корова ... жодної крихти.'::text,'не отримала б'::text,'не отримає'::text,'не отримала'::text,'Якби кухар сховав пиріг, корова не отримала б жодної крихти.'::text),
(373857,41540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el chef hubiera escondido la tarta, la vaca no ... ni una miga.'::text,'habría pillado'::text,'pillará'::text,'pilló'::text,'Si el chef hubiera escondido la tarta, la vaca no habría pillado ni una miga.'::text),
(373856,41540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chef avait caché la tarte, la vache ... une seule miette.'::text,'n''aurait pas eu'::text,'n''aura pas'::text,'n''a pas eu'::text,'Si le chef avait caché la tarte, la vache n''aurait pas eu une seule miette.'::text),
(373859,41540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şef turtayı saklasaydı inek tek bir kırıntı bile ...'::text,'alamazdı'::text,'alamayacak'::text,'alamadı'::text,'Şef turtayı saklasaydı inek tek bir kırıntı bile alamazdı.'::text),
(373860,41540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szakács elrejtette volna a pitét, a tehén egyetlen morzsát sem ...'::text,'kapott volna'::text,'fog kapni'::text,'kapott'::text,'Ha a szakács elrejtette volna a pitét, a tehén egyetlen morzsát sem kapott volna.'::text),
(373863,41541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Koch zwei Kuchen gebacken, ... jetzt noch Kuchen auf dem Tisch, nicht nur Krümel.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Hätte der Koch zwei Kuchen gebacken, wäre jetzt noch Kuchen auf dem Tisch, nicht nur Krümel.'::text),
(373867,41541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кухар спік два пироги, на столі зараз ... пиріг, а не лише крихти.'::text,'ще був би'::text,'ще був би'::text,'ще буде'::text,'Якби кухар спік два пироги, на столі зараз ще був би пиріг, а не лише крихти.'::text),
(373866,41541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el chef hubiera horneado dos tartas, ahora todavía ... tarta en la mesa, no solo migas.'::text,'habría'::text,'habría habido'::text,'habrá'::text,'Si el chef hubiera horneado dos tartas, ahora todavía habría tarta en la mesa, no solo migas.'::text),
(373865,41541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chef avait fait deux tartes, il y ... encore de la tarte sur la table maintenant, pas que des miettes.'::text,'aurait'::text,'aurait eu'::text,'aura'::text,'Si le chef avait fait deux tartes, il y aurait encore de la tarte sur la table maintenant, pas que des miettes.'::text),
(373868,41541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şef iki turta pişirseydi şimdi masada hâlâ turta ..., sadece kırıntı değil.'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Şef iki turta pişirseydi şimdi masada hâlâ turta olurdu, sadece kırıntı değil.'::text),
(373869,41541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szakács két pitét sütött volna, most még ... pite az asztalon, nem csak morzsa.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a szakács két pitét sütött volna, most még lenne pite az asztalon, nem csak morzsa.'::text),
(373872,41542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Apfelkuchen soll in weniger als einer Minute von der Kuh gefressen ...'::text,'worden sein'::text,'werden'::text,'werdend'::text,'Der Apfelkuchen soll in weniger als einer Minute von der Kuh gefressen worden sein.'::text),
(373876,41542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що яблучний пиріг ... з''їдений коровою менш ніж за хвилину.'::text,'був'::text,'бути'::text,'будучи'::text,'Кажуть, що яблучний пиріг був з''їдений коровою менш ніж за хвилину.'::text),
(373875,41542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la tarta de manzana ... devorada por la vaca en menos de un minuto.'::text,'fue'::text,'es'::text,'siendo'::text,'Se dice que la tarta de manzana fue devorada por la vaca en menos de un minuto.'::text),
(373874,41542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la tarte aux pommes ... mangée par la vache en moins d''une minute.'::text,'a été'::text,'est'::text,'étant'::text,'On dit que la tarte aux pommes a été mangée par la vache en moins d''une minute.'::text),
(373877,41542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elmalı turtanın inek tarafından bir dakikadan kısa sürede ... söyleniyor.'::text,'yendiği'::text,'yendiği'::text,'yenerek'::text,'Elmalı turtanın inek tarafından bir dakikadan kısa sürede yendiği söyleniyor.'::text),
(373878,41542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, az almás pitét a tehén kevesebb mint egy perc alatt ...'::text,'megette'::text,'megeszi'::text,'megevén'::text,'Azt mondják, az almás pitét a tehén kevesebb mint egy perc alatt megette.'::text),
(373890,41544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koch ... den Kuchen vor der Kuh verstecken sollen. Super Idee, ihn genau dort liegen zu lassen.'::text,'hätte'::text,'muss'::text,'hätte nicht'::text,'Der Koch hätte den Kuchen vor der Kuh verstecken sollen. Super Idee, ihn genau dort liegen zu lassen.'::text),
(373894,41544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухарю ... сховати пиріг від корови. Чудова ідея — залишити його просто там.'::text,'слід було'::text,'напевно, довелося'::text,'не треба було'::text,'Кухарю слід було сховати пиріг від корови. Чудова ідея — залишити його просто там.'::text),
(373893,41544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chef ... esconder la tarta de la vaca. Genial idea dejarla justo ahí.'::text,'debería haber'::text,'debe de haber'::text,'no tenía que haber'::text,'El chef debería haber esconder la tarta de la vaca. Genial idea dejarla justo ahí.'::text),
(373892,41544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chef ... caché la tarte à la vache. Super idée de la laisser juste là.'::text,'aurait dû'::text,'a dû'::text,'n''avait pas besoin d''avoir'::text,'Le chef aurait dû caché la tarte à la vache. Super idée de la laisser juste là.'::text),
(373895,41544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şef turtayı inekten ... — tam oraya bırakması da harika bir iş.'::text,'saklamalıydı'::text,'saklamış olmalı'::text,'saklamasına gerek yoktu'::text,'Şef turtayı inekten saklamalıydı — tam oraya bırakması da harika bir iş.'::text),
(373896,41544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakácsnak ... a pitét a tehén elől. Remek ötlet volt pont ott hagyni.'::text,'el kellett volna rejtenie'::text,'biztosan elrejtette'::text,'nem kellett volna elrejtenie'::text,'A szakácsnak el kellett volna rejtenie a pitét a tehén elől. Remek ötlet volt pont ott hagyni.'::text),
(373899,41545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... eine Kuh gesehen, die einem Koch wegen eines einzigen Kuchens durch die Küche folgt.'::text,'habe ich'::text,'ich habe'::text,'ich sah'::text,'Noch nie habe ich eine Kuh gesehen, die einem Koch wegen eines einzigen Kuchens durch die Küche folgt.'::text),
(373903,41545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... корови, яка ходила б за кухарем по кухні заради одного пирога.'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив корови, яка ходила б за кухарем по кухні заради одного пирога.'::text),
(373902,41545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... a una vaca seguir a un chef por la cocina por una sola tarta.'::text,'he visto'::text,'yo he visto'::text,'vi'::text,'Nunca he visto a una vaca seguir a un chef por la cocina por una sola tarta.'::text),
(373901,41545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... une vache suivre un chef dans la cuisine pour une seule tarte.'::text,'n''ai-je vu'::text,'je n''ai vu'::text,'je ne vis'::text,'Jamais n''ai-je vu une vache suivre un chef dans la cuisine pour une seule tarte.'::text),
(373904,41545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ineğin tek bir turta için mutfakta bir şefi takip ettiğini hiç ...'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Bir ineğin tek bir turta için mutfakta bir şefi takip ettiğini hiç görmedim.'::text),
(373905,41545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még tehenet, amely egyetlen pite miatt követi a szakácsot a konyhában.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam még tehenet, amely egyetlen pite miatt követi a szakácsot a konyhában.'::text),
(373908,41546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er sollte die Kuh dazu bringen, den nächsten Kuchen ..., weil sie das ganze Ding gefressen hat, echt jetzt.'::text,'zu backen'::text,'backen'::text,'backend'::text,'Yo, er sollte die Kuh dazu bringen, den nächsten Kuchen zu backen, weil sie das ganze Ding gefressen hat, echt jetzt.'::text),
(373912,41546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, йому варто змусити корову ... наступний пиріг, бо вона з''їла його цілком, чесно.'::text,'спекти'::text,'спекти'::text,'печучи'::text,'Йо, йому варто змусити корову спекти наступний пиріг, бо вона з''їла його цілком, чесно.'::text),
(373911,41546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, debería conseguir que la vaca ... la próxima tarta, que se la ha zampado entera, en serio.'::text,'hornee'::text,'hornear'::text,'horneando'::text,'Oye, debería conseguir que la vaca hornee la próxima tarta, que se la ha zampado entera, en serio.'::text),
(373910,41546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, il devrait pousser la vache ... la prochaine tarte, vu qu''elle a tout mangé, sérieux.'::text,'à faire'::text,'faire'::text,'faisant'::text,'Wesh, il devrait pousser la vache à faire la prochaine tarte, vu qu''elle a tout mangé, sérieux.'::text),
(373913,41546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir sonraki turtayı ineğe ..., çünkü koca turtayı yedi, cidden.'::text,'pişirtmeli'::text,'pişirtmeli'::text,'pişirerek'::text,'Kanka, bir sonraki turtayı ineğe pişirtmeli, çünkü koca turtayı yedi, cidden.'::text),
(373914,41546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a tehénnel kéne ... a következő pitét, mert az egészet megette, komolyan.'::text,'megsüttetnie'::text,'megsüttetni'::text,'sütve'::text,'Tesó, a tehénnel kéne megsüttetnie a következő pitét, mert az egészet megette, komolyan.'::text),
(373917,41547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, die Kuh ... 50 % des Kuchens für das Nachmittagsmeeting aufgehoben.'::text,'hätte'::text,'würde'::text,'hob'::text,'Ich wünschte, die Kuh hätte 50 % des Kuchens für das Nachmittagsmeeting aufgehoben.'::text),
(373921,41547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хотів би я, щоб корова ... 50 % пирога для наради після обіду.'::text,'залишила'::text,'залишила'::text,'залишила'::text,'Хотів би я, щоб корова залишила 50 % пирога для наради після обіду.'::text),
(373920,41547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá la vaca ... el 50 % de la tarta para la reunión de la tarde.'::text,'hubiera guardado'::text,'guardara'::text,'guardó'::text,'Ojalá la vaca hubiera guardado el 50 % de la tarta para la reunión de la tarde.'::text),
(373919,41547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''aurais aimé que la vache ... 50 % de la tarte pour la réunion de l''après-midi.'::text,'ait gardé'::text,'garde'::text,'a gardé'::text,'J''aurais aimé que la vache ait gardé 50 % de la tarte pour la réunion de l''après-midi.'::text),
(373922,41547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke inek turtanın %50''sini öğleden sonraki toplantı için ...'::text,'ayırsaydı'::text,'ayırsa'::text,'ayırdı'::text,'Keşke inek turtanın %50''sini öğleden sonraki toplantı için ayırsaydı.'::text),
(373923,41547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak a tehén ... a pite 50%-át a délutáni megbeszélésre.'::text,'félretette volna'::text,'félretenné'::text,'félretette'::text,'Bárcsak a tehén félretette volna a pite 50%-át a délutáni megbeszélésre.'::text),
(373926,41548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koch, ... Kuh den Großteil des Apfelkuchens gefressen hat, lachte nur.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Koch, dessen Kuh den Großteil des Apfelkuchens gefressen hat, lachte nur.'::text),
(373930,41548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухар, ... корова з''їла більшу частину яблучного пирога, лише сміявся.'::text,'чия'::text,'який'::text,'котрий'::text,'Кухар, чия корова з''їла більшу частину яблучного пирога, лише сміявся.'::text),
(373929,41548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chef, ... vaca se comió casi toda la tarta de manzana, solo se rio.'::text,'cuya'::text,'que'::text,'el cual'::text,'El chef, cuya vaca se comió casi toda la tarta de manzana, solo se rio.'::text),
(373928,41548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chef, ... la vache a mangé presque toute la tarte aux pommes, a juste ri.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le chef, dont la vache a mangé presque toute la tarte aux pommes, a juste ri.'::text),
(373931,41548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İneği elmalı turtanın çoğunu ... şef sadece güldü.'::text,'yiyen'::text,'yiyen'::text,'yiyen'::text,'İneği elmalı turtanın çoğunu yiyen şef sadece güldü.'::text),
(373932,41548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakács, ... tehene megette az almás pite nagy részét, csak nevetett.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A szakács, akinek a tehene megette az almás pite nagy részét, csak nevetett.'::text),
(373935,41549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kühe fressen normalerweise Gras, doch dieses Exemplar hat in Minuten ... verputzt.'::text,'einen ganzen Kuchen'::text,'ganzen Kuchen'::text,'die ganzen Kuchen'::text,'Kühe fressen normalerweise Gras, doch dieses Exemplar hat in Minuten einen ganzen Kuchen verputzt.'::text),
(373939,41549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корови зазвичай їдять траву, але ця особина за лічені хвилини з''їла ...'::text,'цілий пиріг'::text,'цілий пиріг'::text,'цілі пироги'::text,'Корови зазвичай їдять траву, але ця особина за лічені хвилини з''їла цілий пиріг.'::text),
(373938,41549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las vacas suelen comer hierba, pero este ejemplar se comió ... en minutos.'::text,'una tarta entera'::text,'tarta entera'::text,'las tartas enteras'::text,'Las vacas suelen comer hierba, pero este ejemplar se comió una tarta entera en minutos.'::text),
(373937,41549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les vaches mangent généralement de l''herbe, pourtant ce spécimen a englouti ... en quelques minutes.'::text,'une tarte entière'::text,'tarte entière'::text,'les tartes entières'::text,'Les vaches mangent généralement de l''herbe, pourtant ce spécimen a englouti une tarte entière en quelques minutes.'::text),
(373940,41549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnekler genellikle ot yer, ama bu örnek dakikalar içinde ... yedi.'::text,'koca bir turta'::text,'koca turta'::text,'koca turtaları'::text,'İnekler genellikle ot yer, ama bu örnek dakikalar içinde koca bir turta yedi.'::text),
(373941,41549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tehenek jellemzően füvet esznek, ez a példány mégis percek alatt ... megevett.'::text,'egy egész pitét'::text,'egész pitét'::text,'az egész pitéket'::text,'A tehenek jellemzően füvet esznek, ez a példány mégis percek alatt egy egész pitét megevett.'::text),
(373944,41550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kuh blieb in der Nähe des Ofens, ... der Kuchen früher fertig würde.'::text,'falls'::text,'trotz'::text,'es sei denn'::text,'Die Kuh blieb in der Nähe des Ofens, falls der Kuchen früher fertig würde.'::text),
(373948,41550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корова лишалася біля духовки ... пиріг вийде раніше.'::text,'на випадок, якщо'::text,'попри те, що'::text,'хіба що'::text,'Корова лишалася біля духовки на випадок, якщо пиріг вийде раніше.'::text),
(373947,41550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vaca se quedó cerca del horno ... la tarta saliera antes.'::text,'por si'::text,'a pesar de que'::text,'a menos que'::text,'La vaca se quedó cerca del horno por si la tarta saliera antes.'::text),
(373946,41550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vache est restée près du four ... la tarte sortirait plus tôt.'::text,'au cas où'::text,'malgré'::text,'à moins que'::text,'La vache est restée près du four au cas où la tarte sortirait plus tôt.'::text),
(373949,41550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnek, turta erken çıkar ... fırının yakınında kaldı.'::text,'diye'::text,'rağmen'::text,'olmadıkça'::text,'İnek, turta erken çıkar diye fırının yakınında kaldı.'::text),
(373950,41550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tehén a sütő közelében maradt, ... a pite korábban elkészül.'::text,'arra az esetre, ha'::text,'annak ellenére, hogy'::text,'hacsak nem'::text,'A tehén a sütő közelében maradt, arra az esetre, ha a pite korábban elkészül.'::text),
(363585,40399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jungs ... mit verbundenen Augen in einer Reihe, als die Flasche einen umhaute. Genialer Plan.'::text,'saßen'::text,'saßen'::text,'haben gesessen'::text,'Die Jungs saßen mit verbundenen Augen in einer Reihe, als die Flasche einen umhaute. Genialer Plan.'::text),
(363589,40399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопці ... із зав''язаними очима в ряд, коли пляшка збила одного з них. Бездоганний план.'::text,'сиділи'::text,'посиділи'::text,'посиділи'::text,'Хлопці сиділи із зав''язаними очима в ряд, коли пляшка збила одного з них. Бездоганний план.'::text),
(363588,40399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los chicos ... en fila con los ojos vendados cuando la botella tumbó a uno. Plan impecable.'::text,'estaban sentados'::text,'se sentaron'::text,'se han sentado'::text,'Los chicos estaban sentados en fila con los ojos vendados cuando la botella tumbó a uno. Plan impecable.'::text),
(363587,40399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gars ... en rang les yeux bandés quand la bouteille en a renversé un. Plan parfait.'::text,'étaient assis'::text,'se sont assis'::text,'se sont assis'::text,'Les gars étaient assis en rang les yeux bandés quand la bouteille en a renversé un. Plan parfait.'::text),
(363590,40399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuklar gözleri bağlı sıra halinde ... şişe birini devirdi. Kusursuz plan.'::text,'otururken'::text,'oturdu'::text,'oturdu'::text,'Çocuklar gözleri bağlı sıra halinde otururken şişe birini devirdi. Kusursuz plan.'::text),
(363591,40399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A srácok bekötött szemmel ... egy sorban, amikor a palack felborította az egyiküket. Hibátlan terv.'::text,'ültek'::text,'leültek'::text,'ültek'::text,'A srácok bekötött szemmel ültek egy sorban, amikor a palack felborította az egyiküket. Hibátlan terv.'::text),
(363594,40400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Wasserflasche ... schon den ganzen Nachmittag Typen von ihren Sitzen, ohne Witz.'::text,'haut'::text,'haut'::text,'haut'::text,'Bro, die Wasserflasche haut schon den ganzen Nachmittag Typen von ihren Sitzen, ohne Witz.'::text),
(363598,40400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця пляшка з водою ... хлопців із сидінь увесь день, без брехні.'::text,'збиває'::text,'збиває'::text,'збиває'::text,'Бро, ця пляшка з водою збиває хлопців із сидінь увесь день, без брехні.'::text),
(363597,40400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esa botella de agua ... a los tíos de sus asientos toda la tarde, sin mentir.'::text,'ha estado tirando'::text,'está tirando'::text,'tira'::text,'Bro, esa botella de agua ha estado tirando a los tíos de sus asientos toda la tarde, sin mentir.'::text),
(363596,40400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette bouteille d''eau ... des mecs de leurs sièges depuis tout l''après-midi, sans mentir.'::text,'fait tomber'::text,'fait tomber'::text,'fait tomber'::text,'Frère, cette bouteille d''eau fait tomber des mecs de leurs sièges depuis tout l''après-midi, sans mentir.'::text),
(363599,40400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o su şişesi bütün öğleden sonra çocukları koltuklarından ..., yalan yok.'::text,'deviriyor'::text,'deviriyor'::text,'devirir'::text,'Kanka, o su şişesi bütün öğleden sonra çocukları koltuklarından deviriyor, yalan yok.'::text),
(363600,40400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a vizesflakon egész délután ... a srácokat a helyükről, komolyan.'::text,'lökdösi le'::text,'lökdösi le'::text,'löki le'::text,'Tesó, az a vizesflakon egész délután lökdösi le a srácokat a helyükről, komolyan.'::text),
(363603,40401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Flasche ... Typ Nummer drei mit einem Schwung von seinem Block, echt jetzt.'::text,'haute'::text,'haute gerade'::text,'hat gehauen'::text,'Yo, die Flasche haute Typ Nummer drei mit einem Schwung von seinem Block, echt jetzt.'::text),
(363607,40401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, пляшка ... чувака номер три з блока одним махом, чесно.'::text,'збила'::text,'збивала'::text,'збила'::text,'Йо, пляшка збила чувака номер три з блока одним махом, чесно.'::text),
(363606,40401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la botella ... al tío número tres de su bloque de un solo golpe, en serio.'::text,'tiró'::text,'estaba tirando'::text,'ha tirado'::text,'Oye, la botella tiró al tío número tres de su bloque de un solo golpe, en serio.'::text),
(363605,40401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, la bouteille ... le mec numéro trois de son bloc en un seul coup, sérieux.'::text,'a fait tomber'::text,'faisait tomber'::text,'a fait tomber'::text,'Wesh, la bouteille a fait tomber le mec numéro trois de son bloc en un seul coup, sérieux.'::text),
(363608,40401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şişe üç numaralı çocuğu tek vuruşta bloğundan ..., cidden.'::text,'devirdi'::text,'deviriyordu'::text,'devirdi'::text,'Kanka, şişe üç numaralı çocuğu tek vuruşta bloğundan devirdi, cidden.'::text),
(363609,40401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a flakon egy lendülettel ... a hármas számú srácot a blokkjáról, komolyan.'::text,'leverte'::text,'verte le'::text,'leverte'::text,'Tesó, a flakon egy lendülettel leverte a hármas számú srácot a blokkjáról, komolyan.'::text),
(363612,40402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher hat die Flasche heute 3 Spieler von ihren Blöcken ..., über dem Ziel.'::text,'gestoßen'::text,'gestoßen'::text,'stößt'::text,'Bisher hat die Flasche heute 3 Spieler von ihren Blöcken gestoßen, über dem Ziel.'::text),
(363616,40402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні пляшка вже ... 3 гравців із блоків, понад план.'::text,'збила'::text,'збивала'::text,'збиває'::text,'Сьогодні пляшка вже збила 3 гравців із блоків, понад план.'::text),
(363615,40402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En lo que va de día, la botella ... a 3 jugadores de sus bloques, por encima del objetivo.'::text,'ha tirado'::text,'ha estado tirando'::text,'tira'::text,'En lo que va de día, la botella ha tirado a 3 jugadores de sus bloques, por encima del objetivo.'::text),
(363614,40402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis ce matin, la bouteille ... 3 joueurs de leurs blocs, au-dessus de l''objectif.'::text,'a fait tomber'::text,'fait tomber'::text,'fait tomber'::text,'Depuis ce matin, la bouteille a fait tomber 3 joueurs de leurs blocs, au-dessus de l''objectif.'::text),
(363617,40402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün şimdiye kadar şişe 3 oyuncuyu bloklarından ..., hedefin üstünde.'::text,'devirdi'::text,'deviriyor'::text,'devirir'::text,'Bugün şimdiye kadar şişe 3 oyuncuyu bloklarından devirdi, hedefin üstünde.'::text),
(363618,40402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma eddig a flakon 3 játékost ... le a blokkjáról, a célon felül.'::text,'lökött'::text,'lökdösött'::text,'lök'::text,'Ma eddig a flakon 3 játékost lökött le a blokkjáról, a célon felül.'::text),
(363621,40403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie lachten, ... die Flasche ihn schon von seinem Block gestoßen, also saß er nicht.'::text,'hatte'::text,'hat'::text,'stieß'::text,'Als sie lachten, hatte die Flasche ihn schon von seinem Block gestoßen, also saß er nicht.'::text),
(363625,40403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони засміялися, пляшка вже ... його з блока, тож він не сидів.'::text,'збила'::text,'збила'::text,'збивала'::text,'Коли вони засміялися, пляшка вже збила його з блока, тож він не сидів.'::text),
(363624,40403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando se rieron, la botella ya lo ... de su bloque, así que no estaba sentado.'::text,'había tirado'::text,'ha tirado'::text,'estaba tirando'::text,'Cuando se rieron, la botella ya lo había tirado de su bloque, así que no estaba sentado.'::text),
(363623,40403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ont ri, la bouteille ... de son bloc, donc il n''était pas assis.'::text,'l''avait déjà fait tomber'::text,'l''a déjà fait tomber'::text,'le faisait tomber'::text,'Quand ils ont ri, la bouteille l''avait déjà fait tomber de son bloc, donc il n''était pas assis.'::text),
(363626,40403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar güldüğünde şişe onu çoktan bloğundan ..., yani oturmuyordu.'::text,'devirmişti'::text,'devirdi'::text,'deviriyordu'::text,'Onlar güldüğünde şişe onu çoktan bloğundan devirmişti, yani oturmuyordu.'::text),
(363627,40403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire nevettek, a flakon már ... a blokkjáról, szóval nem ült.'::text,'lelökte'::text,'lelökte'::text,'lökte le'::text,'Mire nevettek, a flakon már lelökte a blokkjáról, szóval nem ült.'::text),
(363630,40404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Flasche erneut losgelassen wird, ... sie die dritte Versuchsperson von ihrem Block.'::text,'stößt'::text,'würde stoßen'::text,'stieß'::text,'Wenn die Flasche erneut losgelassen wird, stößt sie die dritte Versuchsperson von ihrem Block.'::text),
(363634,40404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо пляшку знову відпустити, вона ... третього суб''єкта з блока.'::text,'зіб''є'::text,'збила б'::text,'збила'::text,'Якщо пляшку знову відпустити, вона зіб''є третього суб''єкта з блока.'::text),
(363633,40404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la botella se suelta de nuevo, ... al tercer sujeto de su bloque.'::text,'tirará'::text,'tiraría'::text,'tiró'::text,'Si la botella se suelta de nuevo, tirará al tercer sujeto de su bloque.'::text),
(363632,40404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la bouteille est relâchée à nouveau, elle ... le troisième sujet de son bloc.'::text,'fera tomber'::text,'ferait tomber'::text,'fit tomber'::text,'Si la bouteille est relâchée à nouveau, elle fera tomber le troisième sujet de son bloc.'::text),
(363635,40404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişe tekrar bırakılırsa üçüncü deneği bloğundan ...'::text,'devirecek'::text,'devirirdi'::text,'devirdi'::text,'Şişe tekrar bırakılırsa üçüncü deneği bloğundan devirecek.'::text),
(363636,40404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a flakont újra elengedik, ... a harmadik alanyt a blokkjáról.'::text,'le fogja lökni'::text,'lelökné'::text,'lelökte'::text,'Ha a flakont újra elengedik, le fogja lökni a harmadik alanyt a blokkjáról.'::text),
(363648,40406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Freund wusste, die Flasche ... jemanden flach auf den Rücken hauen. Eine totale Katastrophe!'::text,'würde'::text,'wird'::text,'haut'::text,'Sein Freund wusste, die Flasche würde jemanden flach auf den Rücken hauen. Eine totale Katastrophe!'::text),
(363652,40406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друг знав, що пляшка ... когось на спину. Повна катастрофа!'::text,'повалить'::text,'повалить'::text,'валить'::text,'Його друг знав, що пляшка повалить когось на спину. Повна катастрофа!'::text),
(363651,40406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amigo sabía que la botella ... a alguien de espaldas. ¡Un desastre total!'::text,'tumbaría'::text,'tumbará'::text,'tumba'::text,'Su amigo sabía que la botella tumbaría a alguien de espaldas. ¡Un desastre total!'::text),
(363650,40406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son pote savait que la bouteille ... quelqu''un sur le dos. Une catastrophe totale !'::text,'mettrait'::text,'mettra'::text,'met'::text,'Son pote savait que la bouteille mettrait quelqu''un sur le dos. Une catastrophe totale !'::text),
(363653,40406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı şişenin birini sırtüstü ... biliyordu. Tam bir felaket!'::text,'devireceğini'::text,'devireceğini'::text,'devirdiğini'::text,'Arkadaşı şişenin birini sırtüstü devireceğini biliyordu. Tam bir felaket!'::text),
(363654,40406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátja tudta, hogy a flakon ... valakit a hátára. Totális katasztrófa!'::text,'le fog dönteni'::text,'le fog dönteni'::text,'ledönt'::text,'A barátja tudta, hogy a flakon le fog dönteni valakit a hátára. Totális katasztrófa!'::text),
(363657,40407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die schwingende Flasche ... genau jetzt den dritten Mann von seinem Block.'::text,'stößt'::text,'stößt'::text,'hat gestoßen'::text,'Die schwingende Flasche stößt genau jetzt den dritten Mann von seinem Block.'::text),
(363661,40407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пляшка, що гойдається, ... третього чоловіка з блока просто зараз.'::text,'збиває'::text,'збиває'::text,'збила'::text,'Пляшка, що гойдається, збиває третього чоловіка з блока просто зараз.'::text),
(363660,40407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La botella que se balancea ... al tercer hombre de su bloque ahora mismo.'::text,'está tirando'::text,'tira'::text,'ha tirado'::text,'La botella que se balancea está tirando al tercer hombre de su bloque ahora mismo.'::text),
(363659,40407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bouteille qui se balance ... le troisième homme de son bloc en ce moment.'::text,'fait tomber'::text,'fait tomber'::text,'a fait tomber'::text,'La bouteille qui se balance fait tomber le troisième homme de son bloc en ce moment.'::text),
(363662,40407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sallanan şişe şu anda üçüncü adamı bloğundan ...'::text,'deviriyor'::text,'devirir'::text,'devirdi'::text,'Sallanan şişe şu anda üçüncü adamı bloğundan deviriyor.'::text),
(363663,40407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lengő flakon épp most ... le a harmadik férfit a blokkjáról.'::text,'löki'::text,'löki'::text,'lökte'::text,'A lengő flakon épp most löki le a harmadik férfit a blokkjáról.'::text),
(363675,40409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Spiels wird die Flasche jeden Spieler von seinem Block ...'::text,'gestoßen haben'::text,'stoßen'::text,'stößt'::text,'Bis zum Ende des Spiels wird die Flasche jeden Spieler von seinem Block gestoßen haben.'::text),
(363679,40409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця гри пляшка ... кожного гравця з блока.'::text,'зіб''є'::text,'збиватиме'::text,'збиває'::text,'До кінця гри пляшка зіб''є кожного гравця з блока.'::text),
(363678,40409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del juego, la botella ... a todos los jugadores de sus bloques.'::text,'habrá tirado'::text,'tirará'::text,'tira'::text,'Para el final del juego, la botella habrá tirado a todos los jugadores de sus bloques.'::text),
(363677,40409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du jeu, la bouteille ... chaque joueur de son bloc.'::text,'aura fait tomber'::text,'fera tomber'::text,'fait tomber'::text,'D''ici la fin du jeu, la bouteille aura fait tomber chaque joueur de son bloc.'::text),
(363680,40409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyunun sonuna kadar şişe her oyuncuyu bloğundan ...'::text,'devirmiş olacak'::text,'devirecek'::text,'deviriyor'::text,'Oyunun sonuna kadar şişe her oyuncuyu bloğundan devirmiş olacak.'::text),
(363681,40409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játék végére a flakon minden játékost ... a blokkjáról.'::text,'le fog lökni'::text,'le fog lökni'::text,'lelöki'::text,'A játék végére a flakon minden játékost le fog lökni a blokkjáról.'::text),
(397398,44156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Abend um acht werde ich gerade Bälle auf den oberen Ball ..., weil der obere Ball oben ist.'::text,'werfen'::text,'werfen'::text,'werfe'::text,'Heute Abend um acht werde ich gerade Bälle auf den oberen Ball werfen, weil der obere Ball oben ist.'::text),
(397402,44156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні о восьмій вечора я ... м''ячики у верхній м''ячик, бо верхній м''ячик нагорі.'::text,'кидатиму'::text,'кину'::text,'кидаю'::text,'Сьогодні о восьмій вечора я кидатиму м''ячики у верхній м''ячик, бо верхній м''ячик нагорі.'::text),
(397401,44156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta noche a las ocho ... pelotas a la pelota de arriba, porque la pelota de arriba está arriba.'::text,'estaré lanzando'::text,'lanzaré'::text,'lanzo'::text,'Esta noche a las ocho estaré lanzando pelotas a la pelota de arriba, porque la pelota de arriba está arriba.'::text),
(397400,44156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce soir à huit heures, je ... des balles sur la balle du haut, parce que la balle du haut est en haut.'::text,'serai en train de lancer'::text,'lancerai'::text,'lance'::text,'Ce soir à huit heures, je serai en train de lancer des balles sur la balle du haut, parce que la balle du haut est en haut.'::text),
(397403,44156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam saat sekizde üstteki topa top ..., çünkü üstteki top üstte.'::text,'atıyor olacağım'::text,'atacağım'::text,'atarım'::text,'Bu akşam saat sekizde üstteki topa top atıyor olacağım, çünkü üstteki top üstte.'::text),
(397404,44156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma este nyolckor ... a felső labdára, mert a felső labda van felül.'::text,'labdákat fogok dobálni'::text,'labdákat dobok majd'::text,'labdákat dobok'::text,'Ma este nyolckor labdákat fogok dobálni a felső labdára, mert a felső labda van felül.'::text),
(397407,44157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatsächlich ... der obere Ball nur an seinem Platz, wenn niemand den Tisch berührt.'::text,'bleibt'::text,'wird gerade bleiben'::text,'blieb'::text,'Tatsächlich bleibt der obere Ball nur an seinem Platz, wenn niemand den Tisch berührt.'::text),
(397411,44157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Насправді верхній м''ячик ... на місці, лише якщо ніхто не торкнеться столу.'::text,'залишиться'::text,'залишатиметься'::text,'залишився'::text,'Насправді верхній м''ячик залишиться на місці, лише якщо ніхто не торкнеться столу.'::text),
(397410,44157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De hecho, la pelota de arriba ... en su sitio solo si nadie toca la mesa.'::text,'se quedará'::text,'se estará quedando'::text,'se quedó'::text,'De hecho, la pelota de arriba se quedará en su sitio solo si nadie toca la mesa.'::text),
(397409,44157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En fait, la balle du haut ... en place seulement si personne ne touche la table.'::text,'restera'::text,'sera en train de rester'::text,'est restée'::text,'En fait, la balle du haut restera en place seulement si personne ne touche la table.'::text),
(397412,44157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aslında üstteki top ancak kimse masaya dokunmazsa yerinde ...'::text,'kalacak'::text,'kalıyor olacak'::text,'kaldı'::text,'Aslında üstteki top ancak kimse masaya dokunmazsa yerinde kalacak.'::text),
(397413,44157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valójában a felső labda csak akkor ... a helyén, ha senki sem ér az asztalhoz.'::text,'marad'::text,'marad majd'::text,'maradt'::text,'Valójában a felső labda csak akkor marad a helyén, ha senki sem ér az asztalhoz.'::text),
(397425,44159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den oberen Ball auf den Stapel, und der ganze Raum ist komplett ausgerastet!'::text,'warf'::text,'wurde geworfen'::text,'werfend'::text,'Er warf den oberen Ball auf den Stapel, und der ganze Raum ist komplett ausgerastet!'::text),
(397429,44159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... верхній м''ячик на стос, і вся кімната просто вибухнула!'::text,'кинув'::text,'був кинутий'::text,'кидаючи'::text,'Він кинув верхній м''ячик на стос, і вся кімната просто вибухнула!'::text),
(397428,44159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... la pelota de arriba sobre la pila y toda la sala explotó por completo!'::text,'lanzó'::text,'fue lanzado'::text,'lanzando'::text,'¡Él lanzó la pelota de arriba sobre la pila y toda la sala explotó por completo!'::text),
(397427,44159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la balle du haut sur la pile, et toute la salle a carrément explosé !'::text,'a lancé'::text,'a été lancé'::text,'lançant'::text,'Il a lancé la balle du haut sur la pile, et toute la salle a carrément explosé !'::text),
(397430,44159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O üstteki topu yığının üstüne ... ve bütün oda resmen patladı!'::text,'attı'::text,'atıldı'::text,'atarak'::text,'O üstteki topu yığının üstüne attı ve bütün oda resmen patladı!'::text),
(397431,44159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a felső labdát a kupacra, és az egész terem teljesen felrobbant!'::text,'dobta'::text,'dobva lett'::text,'dobva'::text,'Ő dobta a felső labdát a kupacra, és az egész terem teljesen felrobbant!'::text),
(397434,44160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch ein Wurf, und der obere Ball ... herunterfallen. Das Ende von allem!'::text,'könnte'::text,'muss'::text,'sollte'::text,'Noch ein Wurf, und der obere Ball könnte herunterfallen. Das Ende von allem!'::text),
(397438,44160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще один кидок — і верхній м''ячик ... впасти. Кінець усьому!'::text,'може'::text,'мусить'::text,'має'::text,'Ще один кидок — і верхній м''ячик може впасти. Кінець усьому!'::text),
(397437,44160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un lanzamiento más y la pelota de arriba ... caerse. ¡El fin de todo!'::text,'podría'::text,'debe'::text,'debería'::text,'Un lanzamiento más y la pelota de arriba podría caerse. ¡El fin de todo!'::text),
(397436,44160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Encore un lancer et la balle du haut ... tomber. La fin de tout !'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Encore un lancer et la balle du haut pourrait tomber. La fin de tout !'::text),
(397439,44160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir atış daha ve üstteki top ...! Her şeyin sonu!'::text,'düşebilir'::text,'düşmek zorunda'::text,'düşmeli'::text,'Bir atış daha ve üstteki top düşebilir! Her şeyin sonu!'::text),
(397440,44160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még egy dobás, és ... a felső labda. Mindennek vége!'::text,'leeshet'::text,'le kell esnie'::text,'le kellene esnie'::text,'Még egy dobás, és leeshet a felső labda. Mindennek vége!'::text),
(397443,44161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, der Typ, ... den oberen Ball geworfen hat, hat anscheinend wochenlang geübt.'::text,'der'::text,'was'::text,'dessen'::text,'Rate mal, der Typ, der den oberen Ball geworfen hat, hat anscheinend wochenlang geübt.'::text),
(397447,44161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, хлопець, ... кинув верхній м''ячик, кажуть, тренувався тижнями.'::text,'який'::text,'що'::text,'чий'::text,'Уяви, хлопець, який кинув верхній м''ячик, кажуть, тренувався тижнями.'::text),
(397446,44161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, el chico ... lanzó la pelota de arriba al parecer practicó durante semanas.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Adivina qué, el chico que lanzó la pelota de arriba al parecer practicó durante semanas.'::text),
(397445,44161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, le mec ... a lancé la balle du haut s''est apparemment entraîné pendant des semaines.'::text,'qui'::text,'lequel'::text,'dont'::text,'Devine quoi, le mec qui a lancé la balle du haut s''est apparemment entraîné pendant des semaines.'::text),
(397448,44161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, üstteki topu ... çocuk haftalarca antrenman yapmış.'::text,'atan'::text,'atan'::text,'atan'::text,'Bil bakalım, üstteki topu atan çocuk haftalarca antrenman yapmış.'::text),
(397449,44161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, a srác, ... a felső labdát dobta, állítólag hetekig gyakorolt.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Képzeld, a srác, aki a felső labdát dobta, állítólag hetekig gyakorolt.'::text),
(397452,44162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass der obere Ball nie auf der Flasche liegen bleiben ...'::text,'würde'::text,'wird'::text,NULL::text,'Er sagte, dass der obere Ball nie auf der Flasche liegen bleiben würde.'::text),
(397456,44162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що верхній м''ячик ніколи не ... на пляшці.'::text,'втримається'::text,'втримається'::text,'тримається'::text,'Він сказав, що верхній м''ячик ніколи не втримається на пляшці.'::text),
(397455,44162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que la pelota de arriba nunca se ... en la botella.'::text,'quedaría'::text,'quedará'::text,'queda'::text,'Dijo que la pelota de arriba nunca se quedaría en la botella.'::text),
(397454,44162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que la balle du haut ne ... jamais sur la bouteille.'::text,'resterait'::text,'restera'::text,'reste'::text,'Il a dit que la balle du haut ne resterait jamais sur la bouteille.'::text),
(397457,44162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üstteki topun şişenin üstünde asla ... söyledi.'::text,'durmayacağını'::text,'durmayacağını'::text,'durmadığını'::text,'Üstteki topun şişenin üstünde asla durmayacağını söyledi.'::text),
(397458,44162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a felső labda soha nem ... meg az üvegen.'::text,'maradna'::text,'marad'::text,'marad'::text,'Azt mondta, hogy a felső labda soha nem maradna meg az üvegen.'::text),
(397461,44163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der obere Ball ... früher der schwierigste Teil, bevor sie den Trick rausgefunden haben.'::text,'war'::text,'war'::text,'war gewohnt'::text,'Der obere Ball war früher der schwierigste Teil, bevor sie den Trick rausgefunden haben.'::text),
(397465,44163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Верхній м''ячик ... найскладнішою частиною, поки вони не знайшли фішку.'::text,'колись був'::text,'бувало був'::text,'звик бути'::text,'Верхній м''ячик колись був найскладнішою частиною, поки вони не знайшли фішку.'::text),
(397464,44163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pelota de arriba ... ser la parte más difícil antes de que descubrieran el truco.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'La pelota de arriba solía ser la parte más difícil antes de que descubrieran el truco.'::text),
(397463,44163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La balle du haut ... la partie la plus difficile avant qu''ils trouvent l''astuce.'::text,'était autrefois'::text,'était'::text,'avait l''habitude d''être'::text,'La balle du haut était autrefois la partie la plus difficile avant qu''ils trouvent l''astuce.'::text),
(397466,44163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar numarayı bulmadan önce üstteki top en zor kısım ...'::text,'olurdu'::text,'olurdu'::text,'olmaya alışıktı'::text,'Onlar numarayı bulmadan önce üstteki top en zor kısım olurdu.'::text),
(397467,44163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felső labda ... a legnehezebb rész, mielőtt rájöttek a trükkre.'::text,'volt régen'::text,'szokott lenni'::text,'hozzá volt szokva, hogy legyen'::text,'A felső labda volt régen a legnehezebb rész, mielőtt rájöttek a trükkre.'::text),
(397470,44164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben es geschafft, den oberen Ball beim ersten Versuch auf dem Stapel ...'::text,'zu landen'::text,'landend'::text,'landen'::text,'Sie haben es geschafft, den oberen Ball beim ersten Versuch auf dem Stapel zu landen.'::text),
(397474,44164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їм вдалося ... верхній м''ячик на стос з першої спроби.'::text,'посадити'::text,'посадка'::text,'посадити'::text,'Їм вдалося посадити верхній м''ячик на стос з першої спроби.'::text),
(397473,44164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consiguieron ... la pelota de arriba sobre la pila al primer intento.'::text,'colocar'::text,'colocando'::text,'colocar'::text,'Consiguieron colocar la pelota de arriba sobre la pila al primer intento.'::text),
(397472,44164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont réussi ... la balle du haut sur la pile du premier coup.'::text,'à poser'::text,'posant'::text,'poser'::text,'Ils ont réussi à poser la balle du haut sur la pile du premier coup.'::text),
(397475,44164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üstteki topu ilk denemede yığının üstüne ... başardılar.'::text,'kondurmayı'::text,'kondurmayı'::text,'kondurmayı'::text,'Üstteki topu ilk denemede yığının üstüne kondurmayı başardılar.'::text),
(397476,44164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Első próbálkozásra sikerült ... a felső labdát a kupacra.'::text,'feljuttatniuk'::text,'feljuttatás'::text,'feljuttatni'::text,'Első próbálkozásra sikerült feljuttatniuk a felső labdát a kupacra.'::text),
(397479,44165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der obere Ball ... jetzt schon so zehn Sekunden auf dem Stapel, ohne Witz.'::text,'liegt'::text,'liegt'::text,'liegt'::text,'Digga, der obere Ball liegt jetzt schon so zehn Sekunden auf dem Stapel, ohne Witz.'::text),
(397483,44165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, верхній м''ячик ... на стосі вже секунд десять, без брехні.'::text,'лежить'::text,'лежить'::text,'лежить'::text,'Бро, верхній м''ячик лежить на стосі вже секунд десять, без брехні.'::text),
(397482,44165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la pelota de arriba ... como diez segundos encima de la pila, sin mentir.'::text,'lleva'::text,'está'::text,'está'::text,'Tío, la pelota de arriba lleva como diez segundos encima de la pila, sin mentir.'::text),
(397481,44165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, la balle du haut ... sur la pile depuis genre dix secondes, sans mentir.'::text,'est posée'::text,'est posée'::text,'est posée'::text,'Mec, la balle du haut est posée sur la pile depuis genre dix secondes, sans mentir.'::text),
(397484,44165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, üstteki top on saniye gibi bir süredir yığının üstünde ..., yalan yok.'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Kanka, üstteki top on saniye gibi bir süredir yığının üstünde duruyor, yalan yok.'::text),
(397485,44165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a felső labda már vagy tíz másodperce ... a kupacon, komolyan.'::text,'áll'::text,'áll'::text,'áll'::text,'Tesó, a felső labda már vagy tíz másodperce áll a kupacon, komolyan.'::text),
(368481,40943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich schwöre, für diese schleimige Sauerei werde ich mich ...!'::text,'rächen'::text,'gerade rächen'::text,'räche'::text,'Ich schwöre, für diese schleimige Sauerei werde ich mich rächen!'::text),
(368485,40943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клянуся, я ... за цей слизький безлад!'::text,'помщуся'::text,'мститимуся'::text,'мщуся'::text,'Клянуся, я помщуся за цей слизький безлад!'::text),
(368484,40943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Juro que me ... de este desastre viscoso!'::text,'vengaré'::text,'estaré vengando'::text,'estoy vengando'::text,'¡Juro que me vengaré de este desastre viscoso!'::text),
(368483,40943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je jure que je ... de ce bazar gluant !'::text,'me vengerai'::text,'serai en train de me venger'::text,'me venge'::text,'Je jure que je me vengerai de ce bazar gluant !'::text),
(368486,40943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim, bu yapış yapış pisliğin intikamını ...!'::text,'alacağım'::text,'alıyor olacağım'::text,'alıyorum'::text,'Yemin ederim, bu yapış yapış pisliğin intikamını alacağım!'::text),
(368487,40943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszöm, ... ezért a nyálkás felfordulásért!'::text,'bosszút fogok állni'::text,'bosszút fogok állni'::text,'bosszút állok'::text,'Esküszöm, bosszút fogok állni ezért a nyálkás felfordulásért!'::text),
(368490,40944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... der ganze Tisch mit einer ekligen grünen Sauerei bedeckt! Katastrophe!'::text,'war'::text,'bedeckte'::text,'ist'::text,'Gestern Abend war der ganze Tisch mit einer ekligen grünen Sauerei bedeckt! Katastrophe!'::text),
(368494,40944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері весь стіл ... огидним зеленим безладом! Катастрофа!'::text,'був укритий'::text,'укрив'::text,'вкритий'::text,'Учора ввечері весь стіл був укритий огидним зеленим безладом! Катастрофа!'::text),
(368493,40944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Anoche toda la mesa ... de un asqueroso desastre verde! ¡Qué desastre!'::text,'quedó cubierta'::text,'cubrió'::text,'está cubierta'::text,'¡Anoche toda la mesa quedó cubierta de un asqueroso desastre verde! ¡Qué desastre!'::text),
(368492,40944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, toute la table ... d''un bazar vert dégoûtant ! Catastrophe !'::text,'était couverte'::text,'a couvert'::text,'est couverte'::text,'Hier soir, toute la table était couverte d''un bazar vert dégoûtant ! Catastrophe !'::text),
(368495,40944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece bütün masa iğrenç yeşil bir pislikle ...! Felaket!'::text,'kaplandı'::text,'kapladı'::text,'kaplanıyor'::text,'Dün gece bütün masa iğrenç yeşil bir pislikle kaplandı! Felaket!'::text),
(368496,40944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este az egész asztalt ... egy undorító zöld felfordulás! Katasztrófa!'::text,'borította'::text,'borította'::text,'borítja'::text,'Tegnap este az egész asztalt borította egy undorító zöld felfordulás! Katasztrófa!'::text),
(368499,40945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... der Typ links die ganze Sauerei mit Absicht.'::text,'machte'::text,'wurde gemacht'::text,'machend'::text,'Bestie, anscheinend machte der Typ links die ganze Sauerei mit Absicht.'::text),
(368503,40945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, хлопець зліва ... весь цей безлад навмисно.'::text,'влаштував'::text,'був влаштований'::text,'влаштовуючи'::text,'Подруго, кажуть, хлопець зліва влаштував весь цей безлад навмисно.'::text),
(368502,40945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el chico de la izquierda ... todo ese desastre a propósito.'::text,'montó'::text,'fue montado'::text,'montando'::text,'Amiga, al parecer el chico de la izquierda montó todo ese desastre a propósito.'::text),
(368501,40945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment le mec de gauche ... tout ce bazar exprès.'::text,'a fait'::text,'a été fait'::text,'faisant'::text,'Ma belle, apparemment le mec de gauche a fait tout ce bazar exprès.'::text),
(368504,40945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre soldaki çocuk bütün o pisliği bilerek ...'::text,'yapmış'::text,'yapılmış'::text,'yaparak'::text,'Kanka, duyduğuma göre soldaki çocuk bütün o pisliği bilerek yapmış.'::text),
(368505,40945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a bal oldali srác direkt ... az egész felfordulást.'::text,'csinálta'::text,'lett csinálva'::text,'csinálva'::text,'Csajszi, állítólag a bal oldali srác direkt csinálta az egész felfordulást.'::text),
(368508,40946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, dass er dreimal geduscht hat, also ... die Sauerei inzwischen weg sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Hör zu, er hat mir gesagt, dass er dreimal geduscht hat, also muss die Sauerei inzwischen weg sein.'::text),
(368512,40946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав, що тричі приймав душ, тож той безлад ... бути вже змитий.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Слухай, він сказав, що тричі приймав душ, тож той безлад мусить бути вже змитий.'::text),
(368511,40946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que se duchó tres veces, así que ese desastre ... haber desaparecido ya.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Oye, me dijo que se duchó tres veces, así que ese desastre debe de haber desaparecido ya.'::text),
(368510,40946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il s''était douché trois fois, donc ce bazar ... avoir disparu maintenant.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Écoute, il m''a dit qu''il s''était douché trois fois, donc ce bazar doit avoir disparu maintenant.'::text),
(368513,40946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana üç kez duş aldığını söyledi, yani o pislik şimdiye gitmiş ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Dinle, bana üç kez duş aldığını söyledi, yani o pislik şimdiye gitmiş olmalı.'::text),
(368514,40946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, háromszor zuhanyozott, szóval az a felfordulás mostanra ...'::text,'biztosan eltűnt'::text,'nem tűnhetett el'::text,'nem szabad, hogy eltűnjön'::text,'Figyelj, azt mondta, háromszor zuhanyozott, szóval az a felfordulás mostanra biztosan eltűnt.'::text),
(368517,40947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Kopf mit Schleim bedeckt ist, sitzt mitten in der Sauerei.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Mann, dessen Kopf mit Schleim bedeckt ist, sitzt mitten in der Sauerei.'::text),
(368521,40947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... голова вкрита слизом, сидить посеред безладу.'::text,'чия'::text,'який'::text,'котрий'::text,'Чоловік, чия голова вкрита слизом, сидить посеред безладу.'::text),
(368520,40947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... cabeza está cubierta de slime está sentado en medio del desastre.'::text,'cuya'::text,'que'::text,'el cual'::text,'El hombre cuya cabeza está cubierta de slime está sentado en medio del desastre.'::text),
(368519,40947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... la tête est couverte de slime est assis au milieu du bazar.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''homme dont la tête est couverte de slime est assis au milieu du bazar.'::text),
(368522,40947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başı slime ile ... adam pisliğin ortasında oturuyor.'::text,'kaplı olan'::text,'kaplı olan'::text,'kaplı olan'::text,'Başı slime ile kaplı olan adam pisliğin ortasında oturuyor.'::text),
(368523,40947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... feje nyálkás, a felfordulás közepén ül.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A férfi, akinek a feje nyálkás, a felfordulás közepén ül.'::text),
(368526,40948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann links sagte, dass er die Sauerei nach dem Video ...'::text,'aufräumen würde'::text,'aufräumen wird'::text,'aufräumt'::text,'Der Mann links sagte, dass er die Sauerei nach dem Video aufräumen würde.'::text),
(368530,40948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік зліва сказав, що ... безлад після відео.'::text,'прибере'::text,'прибере'::text,'прибирає'::text,'Чоловік зліва сказав, що прибере безлад після відео.'::text),
(368529,40948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de la izquierda dijo que ... el desastre después del vídeo.'::text,'limpiaría'::text,'limpiará'::text,'limpia'::text,'El hombre de la izquierda dijo que limpiaría el desastre después del vídeo.'::text),
(368528,40948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme de gauche a dit qu''il ... le bazar après la vidéo.'::text,'nettoierait'::text,'nettoiera'::text,'nettoie'::text,'L''homme de gauche a dit qu''il nettoierait le bazar après la vidéo.'::text),
(368531,40948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soldaki adam videodan sonra pisliği ... söyledi.'::text,'temizleyeceğini'::text,'temizleyeceğini'::text,'temizlediğini'::text,'Soldaki adam videodan sonra pisliği temizleyeceğini söyledi.'::text),
(368532,40948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bal oldali férfi azt mondta, hogy a videó után ... a felfordulást.'::text,'feltakarítja'::text,'fel fogja takarítani'::text,'feltakarítja'::text,'A bal oldali férfi azt mondta, hogy a videó után feltakarítja a felfordulást.'::text),
(368535,40949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher in der Schule ... diese drei jeden Freitag eine Sauerei mit Schleim.'::text,'machten immer'::text,'machten früher'::text,'waren es gewohnt, zu machen'::text,'Früher in der Schule machten immer diese drei jeden Freitag eine Sauerei mit Schleim.'::text),
(368539,40949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще в школі ці троє ... безлад зі слизом щоп''ятниці.'::text,'влаштовували'::text,'влаштовували'::text,'звикли влаштовувати'::text,'Ще в школі ці троє влаштовували безлад зі слизом щоп''ятниці.'::text),
(368538,40949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el colegio, estos tres ... montar un desastre con slime todos los viernes.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'En el colegio, estos tres solían montar un desastre con slime todos los viernes.'::text),
(368537,40949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''école, ces trois-là ... du bazar avec du slime tous les vendredis.'::text,'faisaient'::text,'faisaient'::text,'avaient l''habitude de faire'::text,'À l''école, ces trois-là faisaient du bazar avec du slime tous les vendredis.'::text),
(368540,40949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okuldayken bu üçü her cuma slime ile ortalığı ...'::text,'batırırdı'::text,'batırırdı'::text,'batırmaya alışkındı'::text,'Okuldayken bu üçü her cuma slime ile ortalığı batırırdı.'::text),
(368541,40949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még a suliban ez a három minden pénteken ... a nyálkával.'::text,'felfordulást csinált'::text,'felfordulást szokott csinálni'::text,'hozzá volt szokva a felfordulás csinálásához'::text,'Még a suliban ez a három minden pénteken felfordulást csinált a nyálkával.'::text),
(368544,40950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team hat vereinbart, die Schleim-Sauerei vor dem Meeting um 17 Uhr ...'::text,'aufzuräumen'::text,'Aufräumen'::text,'aufräumen'::text,'Das Team hat vereinbart, die Schleim-Sauerei vor dem Meeting um 17 Uhr aufzuräumen.'::text),
(368548,40950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда домовилася ... слизовий безлад до наради о 17:00.'::text,'прибрати'::text,'прибирання'::text,'прибрати'::text,'Команда домовилася прибрати слизовий безлад до наради о 17:00.'::text),
(368547,40950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo acordó ... el desastre de slime antes de la reunión de las 17:00.'::text,'limpiar'::text,'limpiando'::text,'limpiar'::text,'El equipo acordó limpiar el desastre de slime antes de la reunión de las 17:00.'::text),
(368546,40950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe a convenu ... le bazar de slime avant la réunion de 17 h.'::text,'de nettoyer'::text,'nettoyant'::text,'nettoyer'::text,'L''équipe a convenu de nettoyer le bazar de slime avant la réunion de 17 h.'::text),
(368549,40950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip, slime pisliğini saat 17:00 toplantısından önce ... kabul etti.'::text,'temizlemeyi'::text,'temizlemeyi'::text,'temizlemeyi'::text,'Ekip, slime pisliğini saat 17:00 toplantısından önce temizlemeyi kabul etti.'::text),
(368550,40950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat megegyezett, hogy a délután 5 órás megbeszélés előtt ... a nyálkás felfordulást.'::text,'feltakarítja'::text,'takarítás'::text,'feltakarít'::text,'A csapat megegyezett, hogy a délután 5 órás megbeszélés előtt feltakarítja a nyálkás felfordulást.'::text),
(368562,40952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Versuchsperson die Schleimschicht anhob, ... sich die Sauerei bereits über den ganzen Tisch ausgebreitet.'::text,'hatte'::text,'breitete'::text,'breitete gerade'::text,'Als die Versuchsperson die Schleimschicht anhob, hatte sich die Sauerei bereits über den ganzen Tisch ausgebreitet.'::text),
(368566,40952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли суб''єкт підняв шар слизу, безлад ... по всьому столу.'::text,'уже розповзся'::text,'розповзся'::text,'розповзався'::text,'Коли суб''єкт підняв шар слизу, безлад уже розповзся по всьому столу.'::text),
(368565,40952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el sujeto levantó la lámina de slime, el desastre ... por toda la mesa.'::text,'ya se había extendido'::text,'se extendió'::text,'se estaba extendiendo'::text,'Cuando el sujeto levantó la lámina de slime, el desastre ya se había extendido por toda la mesa.'::text),
(368564,40952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le sujet a soulevé la couche de slime, le bazar ... sur toute la table.'::text,'s''était déjà répandu'::text,'s''est répandu'::text,'se répandait'::text,'Quand le sujet a soulevé la couche de slime, le bazar s''était déjà répandu sur toute la table.'::text),
(368567,40952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek slime tabakasını kaldırdığında pislik bütün masaya çoktan ...'::text,'yayılmıştı'::text,'yayıldı'::text,'yayılıyordu'::text,'Denek slime tabakasını kaldırdığında pislik bütün masaya çoktan yayılmıştı.'::text),
(368568,40952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az alany felemelte a nyálkaréteget, a felfordulás ... az egész asztalon.'::text,'már szétterjedt'::text,'szétterjedt'::text,'terjedt szét'::text,'Mire az alany felemelte a nyálkaréteget, a felfordulás már szétterjedt az egész asztalon.'::text),
(344100,38234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er schwört, dass er beim nächsten Mal langsamer ..., damit das Band sie nicht zurückzieht.'::text,'kriechen wird'::text,'kriechen wird'::text,'kriecht'::text,'Bestie, er schwört, dass er beim nächsten Mal langsamer kriechen wird, damit das Band sie nicht zurückzieht.'::text),
(344104,38234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він клянеться, що наступного разу ... повільніше, щоб гумка не тягнула її назад.'::text,'повзтиме'::text,'повзтиме'::text,'повзе'::text,'Подруго, він клянеться, що наступного разу повзтиме повільніше, щоб гумка не тягнула її назад.'::text),
(344103,38234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, jura que la próxima vez ... más despacio para que la banda no la tire hacia atrás.'::text,'gateará'::text,'estará gateando'::text,'está gateando'::text,'Amiga, jura que la próxima vez gateará más despacio para que la banda no la tire hacia atrás.'::text),
(344102,38234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il jure que la prochaine fois il ... plus lentement, pour que l''élastique ne la tire pas en arrière.'::text,'rampera'::text,'sera en train de ramper'::text,'rampe'::text,'Ma belle, il jure que la prochaine fois il rampera plus lentement, pour que l''élastique ne la tire pas en arrière.'::text),
(344105,38234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bant onu geri çekmesin diye bir dahaki sefere daha yavaş ... yemin ediyor.'::text,'emekleyeceğine'::text,'emekliyor olacağına'::text,'emeklediğine'::text,'Kanka, bant onu geri çekmesin diye bir dahaki sefere daha yavaş emekleyeceğine yemin ediyor.'::text),
(344106,38234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy legközelebb lassabban ..., hogy a gumiszalag ne rántsa vissza.'::text,'fog kúszni'::text,'fog kúszni'::text,'kúszik'::text,'Csajszi, esküszik, hogy legközelebb lassabban fog kúszni, hogy a gumiszalag ne rántsa vissza.'::text),
(344109,38235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend ... sie vom roten Band zurückgezogen, während sie kroch.'::text,'wurde'::text,'zog'::text,'wird'::text,'Okay, also anscheinend wurde sie vom roten Band zurückgezogen, während sie kroch.'::text),
(344113,38235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, її ... назад червоною гумкою, коли вона повзла.'::text,'відтягнуло'::text,'відтягла'::text,'відтягує'::text,'Отже, кажуть, її відтягнуло назад червоною гумкою, коли вона повзла.'::text),
(344112,38235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer ella ... hacia atrás por la banda roja mientras gateaba.'::text,'fue arrastrada'::text,'arrastró'::text,'es arrastrada'::text,'Vale, al parecer ella fue arrastrada hacia atrás por la banda roja mientras gateaba.'::text),
(344111,38235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle ... en arrière par l''élastique rouge pendant qu''elle rampait.'::text,'a été tirée'::text,'a tiré'::text,'est tirée'::text,'Bon, apparemment elle a été tirée en arrière par l''élastique rouge pendant qu''elle rampait.'::text),
(344114,38235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre emeklerken kırmızı bant tarafından geri ...'::text,'çekilmiş'::text,'çekmiş'::text,'çekiliyor'::text,'Tamam, duyduğuma göre emeklerken kırmızı bant tarafından geri çekilmiş.'::text),
(344115,38235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag a piros gumiszalag ... őt, miközben kúszott.'::text,'visszarántotta'::text,'visszarántotta'::text,'visszarántja'::text,'Oké, szóval állítólag a piros gumiszalag visszarántotta őt, miközben kúszott.'::text),
(344118,38236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden ... mit einem roten Band zwischen sich die Bahn entlang.'::text,'krochen'::text,'wurden gekrochen'::text,'kriechend'::text,'Die beiden krochen mit einem roten Band zwischen sich die Bahn entlang.'::text),
(344122,38236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони обоє ... по доріжці з червоною гумкою між собою.'::text,'повзли'::text,'були проповзені'::text,'повзучи'::text,'Вони обоє повзли по доріжці з червоною гумкою між собою.'::text),
(344121,38236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos ... por la pista con una banda roja entre ellos.'::text,'gatearon'::text,'fueron gateados'::text,'gateando'::text,'Los dos gatearon por la pista con una banda roja entre ellos.'::text),
(344120,38236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tous les deux ... le long de la piste avec un élastique rouge entre eux.'::text,'ont rampé'::text,'ont été rampés'::text,'rampant'::text,'Tous les deux ont rampé le long de la piste avec un élastique rouge entre eux.'::text),
(344123,38236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkisi aralarında kırmızı bir bantla pist boyunca ...'::text,'emekledi'::text,'emeklendi'::text,'emekleyerek'::text,'İkisi aralarında kırmızı bir bantla pist boyunca emekledi.'::text),
(344124,38236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ketten ... végig a pályán, köztük egy piros gumiszalaggal.'::text,'kúsztak'::text,'kúszva lettek'::text,'kúszva'::text,'Ők ketten kúsztak végig a pályán, köztük egy piros gumiszalaggal.'::text),
(344127,38237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... echt stark sein, um mit dem Band so schnell zu kriechen.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Ehrlich, du musst echt stark sein, um mit dem Band so schnell zu kriechen.'::text),
(344131,38237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... бути дуже сильним, щоб так швидко повзти з гумкою.'::text,'мусиш'::text,'не можеш'::text,'не маєш'::text,'Чесно, ти мусиш бути дуже сильним, щоб так швидко повзти з гумкою.'::text),
(344130,38237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... ser muy fuerte para gatear tan rápido con la banda puesta.'::text,'debes de'::text,'no puedes'::text,'no deberías'::text,'No te voy a mentir, debes de ser muy fuerte para gatear tan rápido con la banda puesta.'::text),
(344129,38237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... être hyper fort pour ramper aussi vite avec l''élastique.'::text,'dois'::text,'ne peux pas'::text,'ne devrais pas'::text,'Je vais pas mentir, tu dois être hyper fort pour ramper aussi vite avec l''élastique.'::text),
(344132,38237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bantla o kadar hızlı emeklemek için gerçekten güçlü ...'::text,'olmalısın'::text,'olamazsın'::text,'olmamalısın'::text,'Yalan yok, bantla o kadar hızlı emeklemek için gerçekten güçlü olmalısın.'::text),
(344133,38237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ... nagyon erősnek lenned, hogy ilyen gyorsan kússz a gumival.'::text,'kell'::text,'nem lehet'::text,'nem kellene'::text,'Nem hazudok, kell nagyon erősnek lenned, hogy ilyen gyorsan kússz a gumival.'::text),
(344136,38238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Band, ... ihr beim Kriechen helfen sollte, hat sie flach hingelegt. Makellose Ausrüstung.'::text,'das'::text,'wer'::text,'wo'::text,'Das Band, das ihr beim Kriechen helfen sollte, hat sie flach hingelegt. Makellose Ausrüstung.'::text),
(344140,38238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гумка, ... мала допомогти їй повзти, повалила її на підлогу. Бездоганне спорядження.'::text,'яка'::text,'хто'::text,'де'::text,'Гумка, яка мала допомогти їй повзти, повалила її на підлогу. Бездоганне спорядження.'::text),
(344139,38238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... debía ayudarla a gatear la dejó tirada en el suelo. Equipo impecable.'::text,'que'::text,'quien'::text,'donde'::text,'La banda que debía ayudarla a gatear la dejó tirada en el suelo. Equipo impecable.'::text),
(344138,38238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''élastique ... devait l''aider à ramper l''a plaquée au sol. Équipement impeccable.'::text,'qui'::text,'qui'::text,'où'::text,'L''élastique qui devait l''aider à ramper l''a plaquée au sol. Équipement impeccable.'::text),
(344141,38238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Emeklemesine yardım ... bant onu yere serdi. Kusursuz ekipman.'::text,'etmesi gereken'::text,'etmesi gereken'::text,'etmesi gereken'::text,'Emeklemesine yardım etmesi gereken bant onu yere serdi. Kusursuz ekipman.'::text),
(344142,38238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gumiszalag, ... a kúszásban kellett volna segítenie, a földre rántotta. Hibátlan felszerelés.'::text,'amelynek'::text,'akinek'::text,'ahol'::text,'A gumiszalag, amelynek a kúszásban kellett volna segítenie, a földre rántotta. Hibátlan felszerelés.'::text),
(344145,38239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er versprach, sie ... schneller kriechen als er. Natürlich hatte das Band andere Pläne.'::text,'würde'::text,'wird'::text,'kriecht'::text,'Er versprach, sie würde schneller kriechen als er. Natürlich hatte das Band andere Pläne.'::text),
(344149,38239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він пообіцяв, що вона ... швидше за нього. Звісно, у гумки були інші плани.'::text,'повзтиме'::text,'повзтиме'::text,'повзе'::text,'Він пообіцяв, що вона повзтиме швидше за нього. Звісно, у гумки були інші плани.'::text),
(344148,38239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometió que ella ... más rápido que él. Claro, la banda tenía otros planes.'::text,'gatearía'::text,'gateará'::text,'gatea'::text,'Prometió que ella gatearía más rápido que él. Claro, la banda tenía otros planes.'::text),
(344147,38239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a promis qu''elle ... plus vite que lui. Évidemment, l''élastique avait d''autres plans.'::text,'ramperait'::text,'rampera'::text,'rampe'::text,'Il a promis qu''elle ramperait plus vite que lui. Évidemment, l''élastique avait d''autres plans.'::text),
(344150,38239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun kendisinden hızlı ... söz verdi. Tabii bandın başka planları vardı.'::text,'emekleyeceğine'::text,'emekleyeceğine'::text,'emeklediğine'::text,'Onun kendisinden hızlı emekleyeceğine söz verdi. Tabii bandın başka planları vardı.'::text),
(344151,38239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérte, hogy a lány gyorsabban ... nála. Persze a gumiszalagnak más tervei voltak.'::text,'fog kúszni'::text,'fog kúszni'::text,'kúszik'::text,'Megígérte, hogy a lány gyorsabban fog kúszni nála. Persze a gumiszalagnak más tervei voltak.'::text),
(344154,38240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, sie ist noch nicht ... mit Band gewöhnt, deshalb ist sie hingefallen, Bro.'::text,'ans Kriechen'::text,'zu kriechen'::text,'Kriechen'::text,'Nee, sie ist noch nicht ans Kriechen mit Band gewöhnt, deshalb ist sie hingefallen, Bro.'::text),
(344158,38240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-а, вона ще не звикла ... з гумкою, тому й упала, бро.'::text,'повзати'::text,'повзти'::text,'повзання'::text,'Не-а, вона ще не звикла повзати з гумкою, тому й упала, бро.'::text),
(344157,38240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, todavía no está acostumbrada ... con una banda, por eso se cayó, bro.'::text,'a gatear'::text,'gatear'::text,'gateando'::text,'Qué va, todavía no está acostumbrada a gatear con una banda, por eso se cayó, bro.'::text),
(344156,38240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, elle a pas encore l''habitude ... avec un élastique, c''est pour ça qu''elle est tombée, frère.'::text,'de ramper'::text,'ramper'::text,'rampant'::text,'Nan, elle a pas encore l''habitude de ramper avec un élastique, c''est pour ça qu''elle est tombée, frère.'::text),
(344159,38240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bantla ... henüz alışık değil, o yüzden düştü.'::text,'emeklemeye'::text,'emeklemeye'::text,'emeklemek'::text,'Yok kanka, bantla emeklemeye henüz alışık değil, o yüzden düştü.'::text),
(344160,38240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, még nincs hozzászokva ... gumival, ezért esett el, tesó.'::text,'a kúszáshoz'::text,'kúszni'::text,'kúszás'::text,'Á, még nincs hozzászokva a kúszáshoz gumival, ezért esett el, tesó.'::text),
(344163,38241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... weiter, auch als das Band sie zurückzog, irgendwie legendär.'::text,'kroch'::text,'zu kriechen'::text,'kriechen'::text,'Bro, sie kroch weiter, auch als das Band sie zurückzog, irgendwie legendär.'::text),
(344167,38241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... далі, навіть коли гумка тягнула її назад, реально легенда.'::text,'повзла'::text,'повзти'::text,'повзти'::text,'Бро, вона повзла далі, навіть коли гумка тягнула її назад, реально легенда.'::text),
(344166,38241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella siguió ... incluso cuando la banda la tiraba hacia atrás, una crack total.'::text,'gateando'::text,'a gatear'::text,'gatear'::text,'Bro, ella siguió gateando incluso cuando la banda la tiraba hacia atrás, una crack total.'::text),
(344165,38241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a continué ... même quand l''élastique la tirait en arrière, trop une boss.'::text,'à ramper'::text,'de ramper'::text,'ramper'::text,'Frère, elle a continué à ramper même quand l''élastique la tirait en arrière, trop une boss.'::text),
(344168,38241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bant onu geri çekerken bile ... devam etti, resmen efsane.'::text,'emeklemeye'::text,'emeklemeye'::text,'emeklemeye'::text,'Kanka, bant onu geri çekerken bile emeklemeye devam etti, resmen efsane.'::text),
(344169,38241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tovább ..., még amikor a gumi visszahúzta is, tiszta legenda.'::text,'kúszott'::text,'kúszni'::text,'kússz'::text,'Tesó, tovább kúszott, még amikor a gumi visszahúzta is, tiszta legenda.'::text),
(344172,38242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... das Paar die Bahn entlang, während das Band immer straffer wird.'::text,'kriecht'::text,'kriecht'::text,'ist gekrochen'::text,'In diesem Moment kriecht das Paar die Bahn entlang, während das Band immer straffer wird.'::text),
(344176,38242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї миті пара ... доріжкою, поки гумка натягується.'::text,'повзе'::text,'повзе'::text,'проповзла'::text,'Цієї миті пара повзе доріжкою, поки гумка натягується.'::text),
(344175,38242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, la pareja ... por la pista mientras la banda se tensa.'::text,'está gateando'::text,'gatea'::text,'ha gateado'::text,'En este momento, la pareja está gateando por la pista mientras la banda se tensa.'::text),
(344174,38242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le duo ... le long de la piste pendant que l''élastique se tend.'::text,'rampe'::text,'rampe'::text,'a rampé'::text,'En ce moment, le duo rampe le long de la piste pendant que l''élastique se tend.'::text),
(344177,38242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda ikili, bant gittikçe gerilirken pist boyunca ...'::text,'emekliyor'::text,'emekler'::text,'emekledi'::text,'Şu anda ikili, bant gittikçe gerilirken pist boyunca emekliyor.'::text),
(344178,38242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban a páros ... a pályán, miközben a gumi egyre feszesebb.'::text,'kúszik'::text,'kúszik'::text,'kúszott'::text,'Ebben a pillanatban a páros kúszik a pályán, miközben a gumi egyre feszesebb.'::text),
(394491,43833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ein Typ ein Mädchen so mit Blumen ..., weint sie, echt jetzt.'::text,'überrascht'::text,'überraschte'::text,'überraschen wird'::text,'Bro, wenn ein Typ ein Mädchen so mit Blumen überrascht, weint sie, echt jetzt.'::text),
(394495,43833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, коли хлопець ... дівчину такими квітами, вона плаче, чесно.'::text,'дивує'::text,'здивував'::text,'здивує'::text,'Бро, коли хлопець дивує дівчину такими квітами, вона плаче, чесно.'::text),
(394494,43833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si un chico ... a una chica con flores así, ella llora, en serio.'::text,'sorprende'::text,'sorprendió'::text,'sorprenderá'::text,'Bro, si un chico sorprende a una chica con flores así, ella llora, en serio.'::text),
(394493,43833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si un mec ... une meuf avec des fleurs comme ça, elle pleure, sérieux.'::text,'surprend'::text,'a surpris'::text,'surprendra'::text,'Frère, si un mec surprend une meuf avec des fleurs comme ça, elle pleure, sérieux.'::text),
(394496,43833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir erkek bir kızı böyle çiçeklerle ..., kız ağlar, cidden.'::text,'şaşırtırsa'::text,'şaşırttıysa'::text,'şaşırtacaksa'::text,'Kanka, bir erkek bir kızı böyle çiçeklerle şaşırtırsa, kız ağlar, cidden.'::text),
(394497,43833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy srác ... egy csajt ilyen virágokkal, a csaj sír, komolyan.'::text,'meglep'::text,'meglepett'::text,'meg fog lepni'::text,'Tesó, ha egy srác meglep egy csajt ilyen virágokkal, a csaj sír, komolyan.'::text),
(394500,43834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat sie mit diesen rosa Pfingstrosen überrascht, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Er hat sie mit diesen rosa Pfingstrosen überrascht, oder?'::text),
(394504,43834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він здивував її тими рожевими півоніями, ...?'::text,'так'::text,'так'::text,'так'::text,'Він здивував її тими рожевими півоніями, так?'::text),
(394503,43834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sorprendió con esas peonías rosas, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La sorprendió con esas peonías rosas, ¿verdad?'::text),
(394502,43834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il l''a surprise avec ces pivoines roses, ... ?'::text,'non'::text,'non'::text,'non'::text,'Il l''a surprise avec ces pivoines roses, non ?'::text),
(394505,43834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu o pembe şakayıklarla şaşırttı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Onu o pembe şakayıklarla şaşırttı, değil mi?'::text),
(394506,43834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meglepte azokkal a rózsaszín bazsarózsákkal, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Meglepte azokkal a rózsaszín bazsarózsákkal, ugye?'::text),
(394518,43836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis sie die Ecke erreicht, wird das Männchen sie mit den Pfingstrosen ...'::text,'überrascht haben'::text,'überraschen'::text,'gerade überraschen'::text,'Bis sie die Ecke erreicht, wird das Männchen sie mit den Pfingstrosen überrascht haben.'::text),
(394522,43836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона дійде до рогу, самець уже ... її півоніями.'::text,'здивує'::text,'здивує'::text,'дивуватиме'::text,'Поки вона дійде до рогу, самець уже здивує її півоніями.'::text),
(394521,43836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella llegue a la esquina, el macho ya la ... con las peonías.'::text,'habrá sorprendido'::text,'sorprenderá'::text,'estará sorprendiendo'::text,'Para cuando ella llegue a la esquina, el macho ya la habrá sorprendido con las peonías.'::text),
(394520,43836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''elle atteigne le coin, le mâle ... avec les pivoines.'::text,'l''aura surprise'::text,'la surprendra'::text,'sera en train de la surprendre'::text,'D''ici à ce qu''elle atteigne le coin, le mâle l''aura surprise avec les pivoines.'::text),
(394523,43836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köşeye vardığında erkek onu şakayıklarla ...'::text,'şaşırtmış olacak'::text,'şaşırtacak'::text,'şaşırtıyor olacak'::text,'O köşeye vardığında erkek onu şakayıklarla şaşırtmış olacak.'::text),
(394524,43836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire eléri a sarkot, a hím már ... a bazsarózsákkal.'::text,'meglepte'::text,'meg fogja lepni'::text,'éppen meglepi'::text,'Mire eléri a sarkot, a hím már meglepte a bazsarózsákkal.'::text),
(394527,43837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich nicht umgedreht hätte, ... er sie überhaupt nicht überrascht. Totale Katastrophe!'::text,'hätte'::text,'wird'::text,'überraschte'::text,'Wenn sie sich nicht umgedreht hätte, hätte er sie überhaupt nicht überrascht. Totale Katastrophe!'::text),
(394531,43837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не обернулася, він ... її взагалі. Повна катастрофа!'::text,'не здивував би'::text,'не здивує'::text,'не здивував'::text,'Якби вона не обернулася, він не здивував би її взагалі. Повна катастрофа!'::text),
(394530,43837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera dado la vuelta, él no la ... en absoluto. ¡Un desastre total!'::text,'habría sorprendido'::text,'sorprenderá'::text,'sorprendió'::text,'Si no se hubiera dado la vuelta, él no la habría sorprendido en absoluto. ¡Un desastre total!'::text),
(394529,43837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne s''était pas retournée, il ... du tout. Catastrophe totale !'::text,'ne l''aurait pas surprise'::text,'ne la surprendra pas'::text,'ne l''a pas surprise'::text,'Si elle ne s''était pas retournée, il ne l''aurait pas surprise du tout. Catastrophe totale !'::text),
(394532,43837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasını dönmeseydi onu hiç ...! Tam bir felaket!'::text,'şaşırtmazdı'::text,'şaşırtmayacak'::text,'şaşırtmadı'::text,'Arkasını dönmeseydi onu hiç şaşırtmazdı! Tam bir felaket!'::text),
(394533,43837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem fordult volna meg, egyáltalán nem ... őt. Totális katasztrófa!'::text,'lepte volna meg'::text,'fogja meglepni'::text,'lepte meg'::text,'Ha nem fordult volna meg, egyáltalán nem lepte volna meg őt. Totális katasztrófa!'::text),
(394536,43838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er versprach, sie mit Blumen ..., und er hielt Wort.'::text,'zu überraschen'::text,'überraschend'::text,'überrascht zu haben'::text,'Er versprach, sie mit Blumen zu überraschen, und er hielt Wort.'::text),
(394540,43838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він пообіцяв ... її квітами — і дотримав слова.'::text,'здивувати'::text,'дивування'::text,'здивувавши'::text,'Він пообіцяв здивувати її квітами — і дотримав слова.'::text),
(394539,43838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometió ... con flores, y cumplió su palabra.'::text,'sorprenderla'::text,'sorprendiéndola'::text,'haberla sorprendido'::text,'Prometió sorprenderla con flores, y cumplió su palabra.'::text),
(394538,43838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a promis de la ... avec des fleurs, et il a tenu parole.'::text,'surprendre'::text,'surprenant'::text,'avoir surprise'::text,'Il a promis de la surprendre avec des fleurs, et il a tenu parole.'::text),
(394541,43838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu çiçeklerle ... söz verdi ve sözünü tuttu.'::text,'şaşırtacağına'::text,'şaşırtarak'::text,'şaşırttığına'::text,'Onu çiçeklerle şaşırtacağına söz verdi ve sözünü tuttu.'::text),
(394542,43838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérte, hogy virágokkal ... meg, és állta a szavát.'::text,'lepi'::text,'lepve'::text,'lepte'::text,'Megígérte, hogy virágokkal lepi meg, és állta a szavát.'::text),
(394545,43839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... tagelang geplant haben, sie zu überraschen; der Strauß ist riesig.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Er muss tagelang geplant haben, sie zu überraschen; der Strauß ist riesig.'::text),
(394549,43839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... днями, як її здивувати; букет величезний.'::text,'мабуть, планував'::text,'мав планувати'::text,'не міг планувати'::text,'Він мабуть, планував днями, як її здивувати; букет величезний.'::text),
(394548,43839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... planeado sorprenderla durante días; el ramo es enorme.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'Él debe de haber planeado sorprenderla durante días; el ramo es enorme.'::text),
(394547,43839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... prévu de la surprendre depuis des jours ; le bouquet est énorme.'::text,'a dû'::text,'aurait dû'::text,'ne peut pas avoir'::text,'Il a dû prévu de la surprendre depuis des jours ; le bouquet est énorme.'::text),
(394550,43839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu şaşırtmayı günlerdir ...; buket devasa.'::text,'planlamış olmalı'::text,'planlamalıydı'::text,'planlamış olamaz'::text,'Onu şaşırtmayı günlerdir planlamış olmalı; buket devasa.'::text),
(394551,43839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napok óta ..., hogy meglepi; a csokor hatalmas.'::text,'biztosan tervezte'::text,'tervezhette volna'::text,'nem tervezhette'::text,'Napok óta biztosan tervezte, hogy meglepi; a csokor hatalmas.'::text),
(394563,43841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich hat sie es gehasst; sie wünschte, er ... sie überhaupt nicht überrascht.'::text,'hätte'::text,'hat'::text,'überrascht'::text,'Offensichtlich hat sie es gehasst; sie wünschte, er hätte sie überhaupt nicht überrascht.'::text),
(394567,43841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, їй це не сподобалося; вона хотіла б, щоб він її взагалі ...'::text,'не здивував'::text,'не здивував'::text,'не дивує'::text,'Очевидно, їй це не сподобалося; вона хотіла б, щоб він її взагалі не здивував.'::text),
(394566,43841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente lo odió; ojalá él no la ... en absoluto.'::text,'hubiera sorprendido'::text,'ha sorprendido'::text,'sorprende'::text,'Obviamente lo odió; ojalá él no la hubiera sorprendido en absoluto.'::text),
(394565,43841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, elle a détesté ; elle aurait voulu qu''il ... du tout.'::text,'ne l''ait pas surprise'::text,'ne l''a pas surprise'::text,'ne la surprend pas'::text,'Évidemment, elle a détesté ; elle aurait voulu qu''il ne l''ait pas surprise du tout.'::text),
(394568,43841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki nefret etti; keşke onu hiç ... diyor.'::text,'şaşırtmasaydı'::text,'şaşırtmadı'::text,'şaşırtmıyor'::text,'Belli ki nefret etti; keşke onu hiç şaşırtmasaydı diyor.'::text),
(394569,43841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván utálta; azt kívánja, bárcsak egyáltalán ne ... meg.'::text,'lepte volna'::text,'lepte'::text,'lepi'::text,'Nyilván utálta; azt kívánja, bárcsak egyáltalán ne lepte volna meg.'::text),
(394572,43842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pfingstrosen, ... sie so sehr überrascht haben, waren offensichtlich eine schreckliche Idee.'::text,'die'::text,'deren'::text,'was'::text,'Die Pfingstrosen, die sie so sehr überrascht haben, waren offensichtlich eine schreckliche Idee.'::text),
(394576,43842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Півонії, ... її так здивували, були, очевидно, жахливою ідеєю.'::text,'які'::text,'чиї'::text,'що'::text,'Півонії, які її так здивували, були, очевидно, жахливою ідеєю.'::text),
(394575,43842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las peonías, ... tanto la sorprendieron, fueron obviamente una idea terrible.'::text,'que'::text,'cuyas'::text,'lo que'::text,'Las peonías, que tanto la sorprendieron, fueron obviamente una idea terrible.'::text),
(394574,43842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pivoines, ... l''ont tellement surprise, étaient évidemment une idée horrible.'::text,'qui'::text,'dont'::text,'ce qui'::text,'Les pivoines, qui l''ont tellement surprise, étaient évidemment une idée horrible.'::text),
(394577,43842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu o kadar ... şakayıklar belli ki berbat bir fikirdi.'::text,'şaşırtan'::text,'şaşırtan'::text,'şaşırtan'::text,'Onu o kadar şaşırtan şakayıklar belli ki berbat bir fikirdi.'::text),
(394578,43842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bazsarózsák, ... annyira meglepték, nyilvánvalóan szörnyű ötletnek bizonyultak.'::text,'amelyek'::text,'amelyeknek a'::text,'ami'::text,'A bazsarózsák, amelyek annyira meglepték, nyilvánvalóan szörnyű ötletnek bizonyultak.'::text),
(394581,43843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seiner Schüchternheit überraschte er sie mitten auf der Straße mit Blumen.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz seiner Schüchternheit überraschte er sie mitten auf der Straße mit Blumen.'::text),
(394585,43843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свою сором''язливість, він здивував її квітами посеред вулиці.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри свою сором''язливість, він здивував її квітами посеред вулиці.'::text),
(394584,43843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ser tímido, la sorprendió con flores en medio de la calle.'::text,'A pesar de'::text,'Aunque'::text,'Por'::text,'A pesar de ser tímido, la sorprendió con flores en medio de la calle.'::text),
(394583,43843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sa timidité, il l''a surprise avec des fleurs au milieu de la rue.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré sa timidité, il l''a surprise avec des fleurs au milieu de la rue.'::text),
(394586,43843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Utangaç olmasına ... onu sokağın ortasında çiçeklerle şaşırttı.'::text,'rağmen'::text,'olsa da'::text,'yüzünden'::text,'Utangaç olmasına rağmen onu sokağın ortasında çiçeklerle şaşırttı.'::text),
(394587,43843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Félénksége ... virágokkal lepte meg az utca közepén.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Félénksége ellenére virágokkal lepte meg az utca közepén.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
